    ArrayCompressedBigDecimal d2 = ArrayCompressedBigDecimal.allocateZero(CompressedBigDecimalAggregatorFactoryBase.DEFAULT_SIZE + 2, CompressedBigDecimalAggregatorFactoryBase.DEFAULT_SCALE);
