/**
 * ingetion method for all groupBy query.
 *
 * @throws IOException IOException
 * @throws Exception   Exception
 */
@Test
public void testIngestAndGroupByAllQuery() throws IOException, Exception {
    String groupByQueryJson = Resources.asCharSource(this.getClass().getResource("/" + cbdGroupByQueryConfig.getJsonQueryFile()), StandardCharsets.UTF_8).read();
    Sequence<ResultRow> seq = helper.createIndexAndRunQueryOnSegment(this.getClass().getResourceAsStream("/" + "bd_test_data.csv"), Resources.asCharSource(this.getClass().getResource("/" + "bd_test_data_parser.json"), StandardCharsets.UTF_8).read(), Resources.asCharSource(this.getClass().getResource("/" + cbdGroupByQueryConfig.getJsonAggregatorsFile()), StandardCharsets.UTF_8).read(), 0, Granularities.NONE, 5, groupByQueryJson);
    List<ResultRow> results = seq.toList();
    Assert.assertThat(results, IsCollectionWithSize.hasSize(1));
    ResultRow row = results.get(0);
    ObjectMapper mapper = helper.getObjectMapper();
    GroupByQuery groupByQuery = mapper.readValue(groupByQueryJson, GroupByQuery.class);
    MapBasedRow mapBasedRow = row.toMapBasedRow(groupByQuery);
    Map<String, Object> event = mapBasedRow.getEvent();
    Assert.assertEquals(new DateTime("2017-01-01T00:00:00Z", DateTimeZone.forTimeZone(TimeZone.getTimeZone("UTC"))), mapBasedRow.getTimestamp());
    Assert.assertThat(event, IsMapWithSize.aMapWithSize(3));
    Assert.assertThat(event, IsMapContaining.hasEntry("cbdRevenueFromString", new ArrayCompressedBigDecimal(new BigDecimal(cbdGroupByQueryConfig.getStringRevenue()))));
    // long conversion of 5000000000.000000005 results in null/0 value
    Assert.assertThat(event, IsMapContaining.hasEntry("cbdRevenueFromLong", new ArrayCompressedBigDecimal(new BigDecimal(cbdGroupByQueryConfig.getLongRevenue()))));
    // double input changes 5000000000.000000005 to 5000000000.5 to fit in double mantissa space
    Assert.assertThat(event, IsMapContaining.hasEntry("cbdRevenueFromDouble", new ArrayCompressedBigDecimal(new BigDecimal(cbdGroupByQueryConfig.getDoubleRevenue()))));
}

