@Test
void testAddingMonitors() throws IOException {
    TestKubernetesClient testClient = new TestKubernetesClient(client);
    PeonCommandContext context = new PeonCommandContext(new ArrayList<>(), new ArrayList<>(), new File("/tmp/"), 0);
    KubernetesTaskRunnerConfig config = KubernetesTaskRunnerConfig.builder().withNamespace("test").build();
    K8sTaskAdapter adapter = new SingleContainerTaskAdapter(testClient, config, taskConfig, startupLoggingConfig, node, jsonMapper, taskLogs);
    Task task = K8sTestUtils.getTask();
    // no monitor in overlord, no monitor override
    Container container = new ContainerBuilder().withName("container").build();
    adapter.addEnvironmentVariables(container, context, task.toString());
    assertFalse(container.getEnv().stream().anyMatch(x -> x.getName().equals("druid_monitoring_monitors")), "Didn't match, envs: " + Joiner.on(',').join(container.getEnv()));
    // we have an override, but nothing in the overlord
    config = KubernetesTaskRunnerConfig.builder().withNamespace("test").withPeonMonitors(ImmutableList.of("org.apache.druid.java.util.metrics.JvmMonitor")).build();
    adapter = new SingleContainerTaskAdapter(testClient, config, taskConfig, startupLoggingConfig, node, jsonMapper, taskLogs);
    adapter.addEnvironmentVariables(container, context, task.toString());
    EnvVar env = container.getEnv().stream().filter(x -> x.getName().equals("druid_monitoring_monitors")).findFirst().get();
    assertEquals(jsonMapper.writeValueAsString(config.getPeonMonitors()), env.getValue());
    // we override what is in the overlord
    adapter = new SingleContainerTaskAdapter(testClient, config, taskConfig, startupLoggingConfig, node, jsonMapper, taskLogs);
    container.getEnv().add(new EnvVarBuilder().withName("druid_monitoring_monitors").withValue("'[\"org.apache.druid.java.util.metrics.JvmMonitor\", " + "\"org.apache.druid.server.metrics.TaskCountStatsMonitor\"]'").build());
    adapter.addEnvironmentVariables(container, context, task.toString());
    env = container.getEnv().stream().filter(x -> x.getName().equals("druid_monitoring_monitors")).findFirst().get();
    assertEquals(jsonMapper.writeValueAsString(config.getPeonMonitors()), env.getValue());
}

