public void testPercentilePostAggregator() throws Exception {
    Sequence<ResultRow> seq = helper.createIndexAndRunQueryOnSegment(new File(this.getClass().getClassLoader().getResource("input_data.tsv").getFile()), INPUT_DATA_PARSE_SPEC, String.join("\n", "[", "  {\"type\": \"spectatorHistogram\", \"name\": \"histogram\", \"fieldName\": \"cost\"}", "]"), // minTimestamp
