    // prepare data
    GenericRecord someAvroDatum = buildSomeAvroDatum();
    // encode schema id
    Avro1124SubjectAndIdConverter converter = new Avro1124SubjectAndIdConverter(TOPIC);
    TypedSchemaRepository<Integer, Schema, String> repositoryClient = new TypedSchemaRepository<>(repository, new IntegerConverter(), new AvroSchemaConverter(), new IdentityConverter());
    Integer id = repositoryClient.registerSchema(TOPIC, SomeAvroDatum.getClassSchema());
    ByteBuffer byteBuffer = ByteBuffer.allocate(4);
    converter.putSubjectAndId(id, byteBuffer);
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    out.write(byteBuffer.array());
    // encode data
    DatumWriter<GenericRecord> writer = new SpecificDatumWriter<>(someAvroDatum.getSchema());
    // write avro datum to bytes
    writer.write(someAvroDatum, EncoderFactory.get().directBinaryEncoder(out, null));
    final ByteEntity entity = new ByteEntity(ByteBuffer.wrap(out.toByteArray()));
    DimensionsSpec dimensionsSpec = new DimensionsSpec(ImmutableList.of(new AutoTypeColumnSchema("someIntValueMap", null), new AutoTypeColumnSchema("someStringValueMap", null), new AutoTypeColumnSchema("someRecord", null), new AutoTypeColumnSchema("someRecordArray", null), new LongDimensionSchema("tSomeIntValueMap8"), new LongDimensionSchema("tSomeIntValueMap8_2"), new StringDimensionSchema("tSomeStringValueMap8"), new LongDimensionSchema("tSomeRecordSubLong"), new AutoTypeColumnSchema("tSomeRecordArray0", null), new StringDimensionSchema("tSomeRecordArray0nestedString")));
    InputEntityReader reader = inputFormat2.createReader(new InputRowSchema(timestampSpec, dimensionsSpec, null), entity, null);
    TransformSpec transformSpec = new TransformSpec(null, ImmutableList.of(new ExpressionTransform("tSomeIntValueMap8", "json_value(someIntValueMap, '$.8')", TestExprMacroTable.INSTANCE), new ExpressionTransform("tSomeIntValueMap8_2", "json_value(json_query(someIntValueMap, '$'), '$.8')", TestExprMacroTable.INSTANCE), new ExpressionTransform("tSomeStringValueMap8", "json_value(someStringValueMap, '$.8')", TestExprMacroTable.INSTANCE), new ExpressionTransform("tSomeRecordSubLong", "json_value(someRecord, '$.subLong')", TestExprMacroTable.INSTANCE), new ExpressionTransform("tSomeRecordArray0", "json_query(someRecordArray, '$[0]')", TestExprMacroTable.INSTANCE), new ExpressionTransform("tSomeRecordArray0nestedString", "json_value(someRecordArray, '$[0].nestedString')", TestExprMacroTable.INSTANCE)));
    TransformingInputEntityReader transformingReader = new TransformingInputEntityReader(reader, transformSpec.toTransformer());
    InputRow inputRow = transformingReader.read().next();
    Assert.assertEquals(1543698L, inputRow.getTimestampFromEpoch());
    Assert.assertEquals(AvroStreamInputRowParserTest.SOME_INT_VALUE_MAP_VALUE, StructuredData.unwrap(inputRow.getRaw("someIntValueMap")));
    Assert.assertEquals(AvroStreamInputRowParserTest.SOME_STRING_VALUE_MAP_VALUE, StructuredData.unwrap(inputRow.getRaw("someStringValueMap")));
    Assert.assertEquals(ImmutableMap.of("subInt", 4892, "subLong", 1543698L), StructuredData.unwrap(inputRow.getRaw("someRecord")));
    Assert.assertEquals(ImmutableList.of(ImmutableMap.of("nestedString", "string in record")), StructuredData.unwrap(inputRow.getRaw("someRecordArray")));
    Assert.assertEquals(8L, inputRow.getRaw("tSomeIntValueMap8"));
    Assert.assertEquals(8L, inputRow.getRaw("tSomeIntValueMap8_2"));
    Assert.assertEquals("8", inputRow.getRaw("tSomeStringValueMap8"));
    Assert.assertEquals(1543698L, inputRow.getRaw("tSomeRecordSubLong"));
    Assert.assertEquals(ImmutableMap.of("nestedString", "string in record"), StructuredData.unwrap(inputRow.getRaw("tSomeRecordArray0")));
    Assert.assertEquals("string in record", inputRow.getRaw("tSomeRecordArray0nestedString"));
}

