@Test
public void test_next_prefixesWithMultipleBlobsAndSomeDirectories_returnsExpectedBlobs() throws Exception {
    List<URI> prefixes = ImmutableList.of(new URI(StringUtils.format("azure://%s/dir1", CONTAINER)), new URI(StringUtils.format("azure://%s/dir2", CONTAINER)));
    BlobItem blobItem = new BlobItem().setName("blobName").setProperties(new BlobItemProperties().setContentLength(10L));
    SettableSupplier<PagedResponse<BlobItem>> supplier = new SettableSupplier<>();
    supplier.set(new TestPagedResponse<>(ImmutableList.of(blobItem)));
    PagedIterable<BlobItem> pagedIterable = new PagedIterable<>(supplier);
    EasyMock.expect(storage.listBlobsWithPrefixInContainerSegmented(DEFAULT_STORAGE_ACCOUNT, CONTAINER, "dir1", MAX_LISTING_LENGTH, MAX_TRIES)).andReturn(pagedIterable);
    BlobItem blobPrefixItem = new BlobItem().setIsPrefix(true).setName("subdir").setProperties(new BlobItemProperties());
    BlobItem blobItem2 = new BlobItem().setName("blobName2").setProperties(new BlobItemProperties().setContentLength(10L));
    SettableSupplier<PagedResponse<BlobItem>> supplier2 = new SettableSupplier<>();
    supplier2.set(new TestPagedResponse<>(ImmutableList.of(blobPrefixItem, blobItem2)));
    PagedIterable<BlobItem> pagedIterable2 = new PagedIterable<>(supplier2);
    EasyMock.expect(storage.listBlobsWithPrefixInContainerSegmented(DEFAULT_STORAGE_ACCOUNT, CONTAINER, "dir2", MAX_LISTING_LENGTH, MAX_TRIES)).andReturn(pagedIterable2);
    replayAll();
    final AzureCloudBlobIterator azureCloudBlobIterator = new AzureCloudBlobIterator(storage, config, prefixes, MAX_LISTING_LENGTH);
    List<CloudBlobHolder> actualBlobItems = new ArrayList<>();
    while (azureCloudBlobIterator.hasNext()) {
        actualBlobItems.add(azureCloudBlobIterator.next());
    }
    verifyAll();
    List<CloudBlobHolder> expectedBlobItems = ImmutableList.of(new CloudBlobHolder(blobItem, CONTAINER, DEFAULT_STORAGE_ACCOUNT), new CloudBlobHolder(blobItem2, CONTAINER, DEFAULT_STORAGE_ACCOUNT));
    assertEquals(expectedBlobItems.size(), actualBlobItems.size());
    assertEquals(expectedBlobItems.stream().map(CloudBlobHolder::getName).collect(Collectors.toSet()), actualBlobItems.stream().map(CloudBlobHolder::getName).collect(Collectors.toSet()));
    assertEquals(expectedBlobItems.stream().map(CloudBlobHolder::getStorageAccount).collect(Collectors.toSet()), actualBlobItems.stream().map(CloudBlobHolder::getStorageAccount).collect(Collectors.toSet()));
    assertEquals(expectedBlobItems.stream().map(CloudBlobHolder::getContainerName).collect(Collectors.toSet()), actualBlobItems.stream().map(CloudBlobHolder::getContainerName).collect(Collectors.toSet()));
}

