@Test
public void testUpdateProperties() throws CatalogException {
    final String tableName = "table5";
    TableMetadata table = TableBuilder.datasource(tableName, "P1D").build();
    catalog.tables().create(table);
    // Null merge map
    UpdateProperties cmd = new UpdateProperties(null);
    assertEquals(0, new TableEditor(catalog, table.id(), cmd).go());
    // Empty merge map
    cmd = new UpdateProperties(Collections.emptyMap());
    assertEquals(0, new TableEditor(catalog, table.id(), cmd).go());
    // Can't test an empty property set: no table type allows empty
    // properties.
    Map<String, Object> updates = new HashMap<>();
    updates.put(DatasourceDefn.SEGMENT_GRANULARITY_PROPERTY, null);
    cmd = new UpdateProperties(updates);
    Map<String, Object> expected = ImmutableMap.of();
    assertEquals(expected, doEdit(tableName, cmd).spec().properties());
    // Add and update properties
    updates = new HashMap<>();
    updates.put(DatasourceDefn.SEGMENT_GRANULARITY_PROPERTY, "PT1H");
    updates.put("foo", "bar");
    cmd = new UpdateProperties(updates);
    expected = ImmutableMap.of(DatasourceDefn.SEGMENT_GRANULARITY_PROPERTY, "PT1H", "foo", "bar");
    assertEquals(expected, doEdit(tableName, cmd).spec().properties());
    // Update only
    updates = new HashMap<>();
    updates.put("foo", "mumble");
    cmd = new UpdateProperties(updates);
    expected = ImmutableMap.of(DatasourceDefn.SEGMENT_GRANULARITY_PROPERTY, "PT1H", "foo", "mumble");
    assertEquals(expected, doEdit(tableName, cmd).spec().properties());
    // Remove a property
    updates = new HashMap<>();
    updates.put("foo", null);
    cmd = new UpdateProperties(updates);
    expected = ImmutableMap.of(DatasourceDefn.SEGMENT_GRANULARITY_PROPERTY, "PT1H");
    assertEquals(expected, doEdit(tableName, cmd).spec().properties());
    // Add a DESC cluster key - should fail
    Map<String, Object> updates1 = new HashMap<>();
    updates1.put(DatasourceDefn.CLUSTER_KEYS_PROPERTY, ImmutableList.of(new ClusterKeySpec("clusterKeyA", true)));
    assertThrows(CatalogException.class, () -> new TableEditor(catalog, table.id(), new UpdateProperties(updates1)).go());
    // Add a ASC cluster key - should succeed
    updates = new HashMap<>();
    updates.put(DatasourceDefn.CLUSTER_KEYS_PROPERTY, ImmutableList.of(new ClusterKeySpec("clusterKeyA", false)));
    cmd = new UpdateProperties(updates);
    expected = ImmutableMap.of(DatasourceDefn.SEGMENT_GRANULARITY_PROPERTY, "PT1H", DatasourceDefn.CLUSTER_KEYS_PROPERTY, ImmutableList.of(new ClusterKeySpec("clusterKeyA", false)));
    Map<String, Object> actual = doEdit(tableName, cmd).spec().properties();
    actual.put(DatasourceDefn.CLUSTER_KEYS_PROPERTY, MAPPER.convertValue(actual.get(DatasourceDefn.CLUSTER_KEYS_PROPERTY), ClusterKeySpec.CLUSTER_KEY_LIST_TYPE_REF));
    assertEquals(expected, actual);
}

