    cmd = new UpdateColumns(Collections.singletonList(new ColumnSpec("a", Columns.LONG, ImmutableMap.of("foo", "bar"))));
    revised = doEdit(tableName, cmd);
    assertEquals(Arrays.asList("a", "b", "c", "d"), CatalogUtils.columnNames(revised.spec().columns()));
    ColumnSpec colA = revised.spec().columns().get(0);
    assertEquals("a", colA.name());
    assertEquals(Columns.LONG, colA.dataType());
    assertEquals(ImmutableMap.of("foo", "bar"), colA.properties());
    // Duplicates
    UpdateColumns cmd2 = new UpdateColumns(Arrays.asList(new ColumnSpec("e", Columns.STRING, null), new ColumnSpec("e", null, null)));
    assertThrows(CatalogException.class, () -> doEdit(tableName, cmd2));
    // Valid time column type
    cmd = new UpdateColumns(Collections.singletonList(new ColumnSpec(Columns.TIME_COLUMN, Columns.LONG, null)));
    revised = doEdit(tableName, cmd);
    assertEquals(Arrays.asList("a", "b", "c", "d", "__time"), CatalogUtils.columnNames(revised.spec().columns()));
}

