    records = Arrays.asList(new ProducerRecord<byte[], byte[]>(topic, 0, null, jbb("2049", "a", "y", "10", "20.0", "1.0"), SAMPLE_HEADERS), new ProducerRecord<byte[], byte[]>(topic, 0, null, jbb("200", TestKafkaFormatWithMalformedDataDetection.MALFORMED_KEY, "y1", "10", "20.0", "1.0"), SAMPLE_HEADERS), new ProducerRecord<byte[], byte[]>(topic, 0, null, jbb("2009", TestKafkaFormatWithMalformedDataDetection.MALFORMED_KEY, "y2", "10", "20.0", "1.0"), SAMPLE_HEADERS), new ProducerRecord<byte[], byte[]>(topic, 0, null, jbb("2049", "b", "y", "10", "21.0", "1.0"), SAMPLE_HEADERS), new ProducerRecord<byte[], byte[]>(topic, 0, null, jbb("200", TestKafkaFormatWithMalformedDataDetection.MALFORMED_KEY, "y3", "10", "20.0", "1.0"), SAMPLE_HEADERS), new ProducerRecord<byte[], byte[]>(topic, 0, null, jbb("2049", "c", "y", "10", "21.0", "1.0"), SAMPLE_HEADERS));
