    // Insert data
    try (final KafkaProducer<byte[], byte[]> kafkaProducer = KAFKA_SERVER.newProducer()) {
        kafkaProducer.initTransactions();
        kafkaProducer.beginTransaction();
        for (ProducerRecord<byte[], byte[]> record : records.subList(0, 13)) {
