    }
    Set<StreamPartition<KafkaTopicPartition>> partitions = ImmutableSet.of(StreamPartition.of(TOPIC, PARTITION_0), StreamPartition.of(TOPIC, PARTITION_1));
    KafkaRecordSupplier recordSupplier = new KafkaRecordSupplier(KAFKA_SERVER.consumerProperties(), OBJECT_MAPPER, null, false);
    recordSupplier.assign(partitions);
    recordSupplier.seekToEarliest(partitions);
    List<OrderedPartitionableRecord<KafkaTopicPartition, Long, KafkaRecordEntity>> polledRecords = recordSupplier.poll(POLL_TIMEOUT_MILLIS);
    for (int i = 0; polledRecords.size() != 13 && i < POLL_RETRY; i++) {
        polledRecords.addAll(recordSupplier.poll(POLL_TIMEOUT_MILLIS));
        Thread.sleep(200);
    }
    // Insert data
    try (final KafkaProducer<byte[], byte[]> kafkaProducer = KAFKA_SERVER.newProducer()) {
        kafkaProducer.initTransactions();
        kafkaProducer.beginTransaction();
        for (ProducerRecord<byte[], byte[]> record : records.subList(13, 15)) {
            kafkaProducer.send(record).get();
        }
        kafkaProducer.commitTransaction();
    }
    for (int i = 0; polledRecords.size() != records.size() && i < POLL_RETRY; i++) {
        polledRecords.addAll(recordSupplier.poll(POLL_TIMEOUT_MILLIS));
        Thread.sleep(200);
    }
    List<OrderedPartitionableRecord<KafkaTopicPartition, Long, KafkaRecordEntity>> initialRecords = createOrderedPartitionableRecords();
    Assert.assertEquals(records.size(), polledRecords.size());
    Assert.assertEquals(partitions, recordSupplier.getAssignment());
    final int initialRecordsPartition0Size = initialRecords.stream().filter(r -> r.getPartitionId().partition() == 0).collect(Collectors.toSet()).size();
    final int initialRecordsPartition1Size = initialRecords.stream().filter(r -> r.getPartitionId().partition() == 1).collect(Collectors.toSet()).size();
    final int polledRecordsPartition0Size = polledRecords.stream().filter(r -> r.getPartitionId().partition() == 0).collect(Collectors.toSet()).size();
    final int polledRecordsPartition1Size = polledRecords.stream().filter(r -> r.getPartitionId().partition() == 1).collect(Collectors.toSet()).size();
    Assert.assertEquals(initialRecordsPartition0Size, polledRecordsPartition0Size);
    Assert.assertEquals(initialRecordsPartition1Size, polledRecordsPartition1Size);
    recordSupplier.close();
}

