@Test
public void testSerde() throws Exception {
    final String stream = "theStream";
    final Map<KafkaTopicPartition, Long> offsetMap = ImmutableMap.of(new KafkaTopicPartition(false, null, 1), 2L, new KafkaTopicPartition(false, null, 3), 4L);
    final KafkaSeekableStreamEndSequenceNumbers partitions = new KafkaSeekableStreamEndSequenceNumbers(stream, null, offsetMap, null);
    final String serializedString = OBJECT_MAPPER.writeValueAsString(partitions);
    // Check round-trip.
    final SeekableStreamEndSequenceNumbers<KafkaTopicPartition, Long> partitions2 = OBJECT_MAPPER.readValue(serializedString, new TypeReference<SeekableStreamEndSequenceNumbers<KafkaTopicPartition, Long>>() {
    });
    Assert.assertEquals("Round trip", partitions, new KafkaSeekableStreamEndSequenceNumbers(partitions2.getStream(), partitions2.getTopic(), partitions2.getPartitionSequenceNumberMap(), partitions2.getPartitionOffsetMap()));
    // Check backwards compatibility.
    final Map<String, Object> asMap = OBJECT_MAPPER.readValue(serializedString, JacksonUtils.TYPE_REFERENCE_MAP_STRING_OBJECT);
    Assert.assertEquals(stream, asMap.get("stream"));
    Assert.assertEquals(stream, asMap.get("topic"));
    // Jackson will deserialize the maps as string -> int maps, not int -> long.
    Assert.assertEquals(offsetMap, OBJECT_MAPPER.convertValue(asMap.get("partitionSequenceNumberMap"), new TypeReference<Map<KafkaTopicPartition, Long>>() {
    }));
    Assert.assertEquals(offsetMap, OBJECT_MAPPER.convertValue(asMap.get("partitionOffsetMap"), new TypeReference<Map<KafkaTopicPartition, Long>>() {
    }));
    // check that KafkaSeekableStreamEndSequenceNumbers not registered with mapper, so no possible collision
    // when deserializing it from String / bytes
    boolean expectedExceptionThrown = false;
    try {
        OBJECT_MAPPER.readValue(serializedString, KafkaSeekableStreamEndSequenceNumbers.class);
    } catch (InvalidTypeIdException e) {
        expectedExceptionThrown = true;
    }
    Assert.assertTrue("KafkaSeekableStreamEndSequenceNumbers should not be registered type", expectedExceptionThrown);
}

