    DataSchema modifiedDataSchema = getDataSchema("some other datasource");
    KinesisSupervisorTuningConfig modifiedTuningConfig = new KinesisSupervisorTuningConfig(null, 1000, null, null, 50000, null, new Period("P1Y"), null, null, null, false, null, null, null, null, numThreads, TEST_CHAT_RETRIES, TEST_HTTP_TIMEOUT, TEST_SHUTDOWN_TIMEOUT, null, null, null, null, null, null, null, null, // This property is different from tuningConfig
