@Test
public void testReplaceWithTooManySegmentsInTimeChunk() throws IOException {
    // Each segment will contain at most 10 rows. So with ALL granularity, an ingest query will
    // attempt to generate a total of 5 segments for 50 input rows but will fail since only 1 segment is allowed.
    final int maxNumSegments = 1;
    final int rowsPerSegment = 10;
    final int numRowsInInputFile = 50;
    final Map<String, Object> context = ImmutableMap.<String, Object>builder().putAll(DEFAULT_MSQ_CONTEXT).put("maxNumSegments", maxNumSegments).put("rowsPerSegment", rowsPerSegment).build();
    final File file = createNdJsonFile(newTempFile("ndjson30k"), numRowsInInputFile, 1);
    final String filePathAsJson = queryFramework().queryJsonMapper().writeValueAsString(file.getAbsolutePath());
    testIngestQuery().setSql("REPLACE INTO foo1 " + " OVERWRITE ALL " + " SELECT FLOOR(TIME_PARSE(\"timestamp\") to day) AS __time" + " FROM TABLE(\n" + "  EXTERN(\n" + "    '{ \"files\": [" + filePathAsJson + "],\"type\":\"local\"}',\n" + "    '{\"type\": \"json\"}',\n" + "    '[{\"name\": \"timestamp\",\"type\":\"string\"}]'\n" + "  )\n" + " ) PARTITIONED BY ALL").setExpectedDataSource("foo1").setExpectedRowSignature(RowSignature.builder().add("__time", ColumnType.LONG).build()).setQueryContext(context).setExpectedMSQFault(new TooManySegmentsInTimeChunkFault(DateTimes.of("1970-01-01"), numRowsInInputFile / rowsPerSegment, maxNumSegments, Granularities.ALL)).verifyResults();
}

