@Test
public void testReplaceTombstonesWithTooManyBucketsThrowsFault() {
    RowSignature rowSignature = RowSignature.builder().add("__time", ColumnType.LONG).add("dim1", ColumnType.STRING).add("cnt", ColumnType.LONG).build();
    // Create a datasegment which lies partially outside the generated segment
    DataSegment existingDataSegment = DataSegment.builder().interval(Intervals.of("2001-01-01T/2003-01-04T")).size(50).version(MSQTestTaskActionClient.VERSION).dataSource("foo1").build();
