@Test
public void triggerCancellationFromAnotherThread() throws Exception {
    brokerClient = mock(BrokerClient.class);
    doReturn(mock(Request.class)).when(brokerClient).makeRequest(any(), anyString());
    doAnswer(new Answer<String>() {

        int timesInvoked = 0;

        @Override
        public String answer(InvocationOnMock invocation) throws Throwable {
            // sleeping broker call to simulate a long running query
            Thread.sleep(1000);
            timesInvoked++;
            SegmentLoadStatusFetcher.VersionLoadStatus loadStatus = new SegmentLoadStatusFetcher.VersionLoadStatus(5, timesInvoked, 0, 5 - timesInvoked, 0);
            return new ObjectMapper().writeValueAsString(loadStatus);
        }
    }).when(brokerClient).sendQuery(any());
    segmentLoadWaiter = new SegmentLoadStatusFetcher(brokerClient, new ObjectMapper(), "id", TEST_DATASOURCE, IntStream.range(0, 5).boxed().map(partitionNum -> createTestDataSegment("version1", partitionNum)).collect(Collectors.toSet()), true);
    Thread t = new Thread(() -> segmentLoadWaiter.waitForSegmentsToLoad());
    t.start();
    // call close from main thread
    segmentLoadWaiter.close();
    t.join(1000);
    Assert.assertFalse(t.isAlive());
    Assert.assertTrue(segmentLoadWaiter.status().getState().isFinished());
    Assert.assertTrue(segmentLoadWaiter.status().getState() == SegmentLoadStatusFetcher.State.FAILED);
}

@Test
public void testConcurrency() {
    final int iterations = 1000;
    final List<ListenableFuture<Boolean>> testFutures = new ArrayList<>();
    for (int i = 0; i < iterations; i++) {
        final int expectedSegmentNumber = i % NUM_SEGMENTS;
        final DataSegment segment = segments.get(expectedSegmentNumber);
        final ListenableFuture<Supplier<ResourceHolder<Segment>>> f = exec.submit(() -> provider.fetchSegment(segment.getId(), new ChannelCounters(), false));
        testFutures.add(FutureUtils.transform(f, holderSupplier -> {
            try {
                final ResourceHolder<Segment> holder = holderSupplier.get();
                Assert.assertEquals(segment.getId(), holder.get().getId());
                final String expectedStorageDir = DataSegmentPusher.getDefaultStorageDir(segment, false);
                final File expectedFile = new File(StringUtils.format("%s/%s/%s", cacheDir, expectedStorageDir, LOAD_SPEC_FILE_NAME));
                Assert.assertTrue(expectedFile.exists());
                Assert.assertArrayEquals(Ints.toByteArray(expectedSegmentNumber), Files.readAllBytes(expectedFile.toPath()));
                holder.close();
                return true;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }));
    }
    Assert.assertEquals(iterations, testFutures.size());
    for (int i = 0; i < iterations; i++) {
        ListenableFuture<Boolean> testFuture = testFutures.get(i);
        Assert.assertTrue("Test iteration #" + i, FutureUtils.getUnchecked(testFuture, false));
    }
    // Cache dir should exist, but be empty, since we've closed all holders.
    Assert.assertTrue(cacheDir.exists());
    Assert.assertArrayEquals(new String[] {}, cacheDir.list());
}

