@Test
public void test_taskReportDestination() throws IOException {
    final TaskReportQueryListener listener = new TaskReportQueryListener(TaskReportMSQDestination.instance(), Suppliers.ofInstance(baos)::get, JSON_MAPPER, TASK_ID, TASK_CONTEXT);
    Assert.assertTrue(listener.readResults());
    listener.onResultsStart(SIGNATURE, SQL_TYPE_NAMES);
    Assert.assertTrue(listener.onResultRow(new Object[] { "foo" }));
    Assert.assertTrue(listener.onResultRow(new Object[] { "bar" }));
    listener.onResultsComplete();
    listener.onQueryComplete(new MSQTaskReportPayload(new MSQStatusReport(TaskState.SUCCESS, null, Collections.emptyList(), null, 0, new HashMap<>(), 1, 2, null, null), MSQStagesReport.create(MSQTaskReportTest.QUERY_DEFINITION, ImmutableMap.of(), ImmutableMap.of(), ImmutableMap.of(), ImmutableMap.of(), ImmutableMap.of()), new CounterSnapshotsTree(), null));
    final TaskReport.ReportMap reportMap = JSON_MAPPER.readValue(baos.toByteArray(), new TypeReference<TaskReport.ReportMap>() {
    });
    Assert.assertEquals(ImmutableSet.of("multiStageQuery", TaskContextReport.REPORT_KEY), reportMap.keySet());
    Assert.assertEquals(TASK_CONTEXT, ((TaskContextReport) reportMap.get(TaskContextReport.REPORT_KEY)).getPayload());
    final MSQTaskReport report = (MSQTaskReport) reportMap.get("multiStageQuery");
    final List<List<Object>> results = report.getPayload().getResults().getResults().stream().map(Arrays::asList).collect(Collectors.toList());
    Assert.assertEquals(ImmutableList.of(ImmutableList.of("foo"), ImmutableList.of("bar")), results);
    Assert.assertFalse(report.getPayload().getResults().isResultsTruncated());
    Assert.assertEquals(TaskState.SUCCESS, report.getPayload().getStatus().getStatus());
}

@Test
public void test_durableDestination() throws IOException {
    final TaskReportQueryListener listener = new TaskReportQueryListener(DurableStorageMSQDestination.instance(), Suppliers.ofInstance(baos)::get, JSON_MAPPER, TASK_ID, TASK_CONTEXT);
    Assert.assertTrue(listener.readResults());
    listener.onResultsStart(SIGNATURE, SQL_TYPE_NAMES);
    for (int i = 0; i < Limits.MAX_SELECT_RESULT_ROWS - 1; i++) {
        Assert.assertTrue("row #" + i, listener.onResultRow(new Object[] { "foo" }));
    }
    Assert.assertFalse(listener.onResultRow(new Object[] { "foo" }));
    listener.onQueryComplete(new MSQTaskReportPayload(new MSQStatusReport(TaskState.SUCCESS, null, Collections.emptyList(), null, 0, new HashMap<>(), 1, 2, null, null), MSQStagesReport.create(MSQTaskReportTest.QUERY_DEFINITION, ImmutableMap.of(), ImmutableMap.of(), ImmutableMap.of(), ImmutableMap.of(), ImmutableMap.of()), new CounterSnapshotsTree(), null));
    final TaskReport.ReportMap reportMap = JSON_MAPPER.readValue(baos.toByteArray(), new TypeReference<TaskReport.ReportMap>() {
    });
    Assert.assertEquals(ImmutableSet.of("multiStageQuery", TaskContextReport.REPORT_KEY), reportMap.keySet());
    Assert.assertEquals(TASK_CONTEXT, ((TaskContextReport) reportMap.get(TaskContextReport.REPORT_KEY)).getPayload());
    final MSQTaskReport report = (MSQTaskReport) reportMap.get("multiStageQuery");
    final List<List<Object>> results = report.getPayload().getResults().getResults().stream().map(Arrays::asList).collect(Collectors.toList());
    Assert.assertEquals(IntStream.range(0, (int) Limits.MAX_SELECT_RESULT_ROWS).mapToObj(i -> ImmutableList.of("foo")).collect(Collectors.toList()), results);
    Assert.assertTrue(report.getPayload().getResults().isResultsTruncated());
    Assert.assertEquals(TaskState.SUCCESS, report.getPayload().getStatus().getStatus());
}

