@Test
public void testBuildTableAndInlineData() throws IOException {
    final Int2IntMap sideStageChannelNumberMap = new Int2IntOpenHashMap();
    sideStageChannelNumberMap.put(3, 1);
    sideStageChannelNumberMap.put(4, 2);
    final List<ReadableFrameChannel> channels = new ArrayList<>();
    channels.add(new ExplodingReadableFrameChannel());
    channels.add(new ReadableFileFrameChannel(FrameFile.open(testDataFile1, null)));
    channels.add(new ReadableFileFrameChannel(FrameFile.open(testDataFile2, null)));
    final List<FrameReader> channelReaders = new ArrayList<>();
    channelReaders.add(null);
    channelReaders.add(frameReader1);
    channelReaders.add(frameReader2);
    final BroadcastJoinSegmentMapFnProcessor broadcastJoinReader = new BroadcastJoinSegmentMapFnProcessor(null, /* Query; not used for the methods we're testing */
    sideStageChannelNumberMap, channels, channelReaders, // High enough memory limit that we won't hit it
    25_000_000L);
    Assert.assertEquals(ImmutableSet.of(1, 2), broadcastJoinReader.getSideChannelNumbers());
    boolean doneReading = false;
    while (!doneReading) {
        final IntSet readableInputs = new IntOpenHashSet();
        for (int i = 1; i < channels.size(); i++) {
            // Frame file channels are always ready, so this is OK.
            readableInputs.add(i);
        }
        doneReading = broadcastJoinReader.buildBroadcastTablesIncrementally(readableInputs);
    }
    Assert.assertTrue(channels.get(1).isFinished());
    Assert.assertTrue(channels.get(2).isFinished());
    Assert.assertEquals(new InputNumberDataSource(0), broadcastJoinReader.inlineChannelData(new InputNumberDataSource(0)));
    Assert.assertEquals(new InputNumberDataSource(1), broadcastJoinReader.inlineChannelData(new InputNumberDataSource(1)));
    Assert.assertEquals(new InputNumberDataSource(2), broadcastJoinReader.inlineChannelData(new InputNumberDataSource(2)));
    final List<Object[]> rowsFromStage3 = ((InlineDataSource) broadcastJoinReader.inlineChannelData(new InputNumberDataSource(3))).getRowsAsList();
    Assert.assertEquals(1209, rowsFromStage3.size());
    FrameTestUtil.assertRowsEqual(FrameTestUtil.readRowsFromAdapter(adapter, null, false), Sequences.simple(rowsFromStage3.stream().map(Arrays::asList).collect(Collectors.toList())));
    final List<Object[]> rowsFromStage4 = ((InlineDataSource) broadcastJoinReader.inlineChannelData(new InputNumberDataSource(4))).getRowsAsList();
    Assert.assertEquals(2, rowsFromStage4.size());
    FrameTestUtil.assertRowsEqual(FrameTestUtil.readRowsFromAdapter(adapter, null, false).limit(2), Sequences.simple(rowsFromStage4.stream().map(Arrays::asList).collect(Collectors.toList())));
    final DataSource inlinedJoinDataSource = broadcastJoinReader.inlineChannelData(JoinDataSource.create(new InputNumberDataSource(0), new InputNumberDataSource(4), "j.", JoinConditionAnalysis.forExpression("x == \"j.x\"", "j.", ExprMacroTable.nil()), JoinType.INNER, null, null));
    MatcherAssert.assertThat(((JoinDataSource) inlinedJoinDataSource).getRight(), CoreMatchers.instanceOf(InlineDataSource.class));
    Assert.assertEquals(2, ((InlineDataSource) ((JoinDataSource) inlinedJoinDataSource).getRight()).getRowsAsList().size());
}

@Test
public void testBuildTableMemoryLimit() throws IOException {
    final Int2IntMap sideStageChannelNumberMap = new Int2IntOpenHashMap();
    sideStageChannelNumberMap.put(0, 0);
    final List<ReadableFrameChannel> channels = new ArrayList<>();
    channels.add(new ReadableFileFrameChannel(FrameFile.open(testDataFile1, ByteTracker.unboundedTracker())));
    final List<FrameReader> channelReaders = new ArrayList<>();
    channelReaders.add(frameReader1);
    final BroadcastJoinSegmentMapFnProcessor broadcastJoinHelper = new BroadcastJoinSegmentMapFnProcessor(null, /* Query; not used for the methods we're testing */
    sideStageChannelNumberMap, channels, channelReaders, // Low memory limit; we will hit this
    100_000);
    Assert.assertEquals(ImmutableSet.of(0), broadcastJoinHelper.getSideChannelNumbers());
    final MSQException e = Assert.assertThrows(MSQException.class, () -> {
        boolean doneReading = false;
        while (!doneReading) {
            final IntSet readableInputs = new IntOpenHashSet(new int[] { 0 });
            doneReading = broadcastJoinHelper.buildBroadcastTablesIncrementally(readableInputs);
        }
    });
    Assert.assertEquals(new BroadcastTablesTooLargeFault(100_000, null), e.getFault());
}

