@Test
public void testBuildTableMemoryLimitWithSortMergeConfigured() throws IOException {
    final Int2IntMap sideStageChannelNumberMap = new Int2IntOpenHashMap();
    sideStageChannelNumberMap.put(0, 0);
    final List<ReadableFrameChannel> channels = new ArrayList<>();
    channels.add(new ReadableFileFrameChannel(FrameFile.open(testDataFile1, ByteTracker.unboundedTracker())));
    final List<FrameReader> channelReaders = new ArrayList<>();
    channelReaders.add(frameReader1);
    // Query: used only to retrieve configured join from context
    final Query<?> mockQuery = EasyMock.mock(Query.class);
    EasyMock.expect(mockQuery.context()).andReturn(QueryContext.of(ImmutableMap.of(PlannerContext.CTX_SQL_JOIN_ALGORITHM, JoinAlgorithm.SORT_MERGE.getId())));
    EasyMock.replay(mockQuery);
    final BroadcastJoinSegmentMapFnProcessor broadcastJoinHelper = new BroadcastJoinSegmentMapFnProcessor(mockQuery, sideStageChannelNumberMap, channels, channelReaders, // Low memory limit; we will hit this
    100_000);
    Assert.assertEquals(ImmutableSet.of(0), broadcastJoinHelper.getSideChannelNumbers());
    final MSQException e = Assert.assertThrows(MSQException.class, () -> {
        boolean doneReading = false;
        while (!doneReading) {
            final IntSet readableInputs = new IntOpenHashSet(new int[] { 0 });
            doneReading = broadcastJoinHelper.buildBroadcastTablesIncrementally(readableInputs);
        }
    });
    Assert.assertEquals(new BroadcastTablesTooLargeFault(100_000, JoinAlgorithm.SORT_MERGE), e.getFault());
    EasyMock.verify(mockQuery);
}

/**
 * Simple functional test of the chained processor manager.
 * The {@link ChainedProcessorManager#first} is a {@link SimpleReturningFrameProcessor} which returns the list of
 * values. The {@link ChainedProcessorManager#restFactory} is a function that creates a
 * {@link SingleRowWritingFrameProcessor} for each value.
 */
@Test
public void test_simple_chained_processor() throws ExecutionException, InterruptedException {
    final ImmutableList<Long> expectedValues = ImmutableList.of(1L, 2L, 3L);
    final BlockingQueueFrameChannel outputChannel = new BlockingQueueFrameChannel(3);
    final SimpleReturningFrameProcessor<List<Long>> firstProcessor = new SimpleReturningFrameProcessor<>(expectedValues);
    final ChainedProcessorManager<List<Long>, Long, Long> chainedProcessorManager = new ChainedProcessorManager<>(ProcessorManagers.of(() -> firstProcessor), (values) -> createNextProcessors(outputChannel.writable(), values.stream().flatMap(List::stream).collect(Collectors.toList())));
    exec.runAllFully(chainedProcessorManager, maxOutstandingProcessors, bouncer, null).get();
    final HashSet<Long> actualValues = new HashSet<>();
    try (ReadableFrameChannel readable = outputChannel.readable()) {
        while (readable.canRead()) {
            actualValues.add(extractColumnValue(readable.read(), 1));
        }
    }
    Assert.assertEquals(new HashSet<>(expectedValues), actualValues);
}

