@Test
public void test_validateCondition() {
    Assert.assertNotNull(SortMergeJoinFrameProcessorFactory.validateCondition(JoinConditionAnalysis.forExpression("1", "j.", ExprMacroTable.nil())));
    Assert.assertNotNull(SortMergeJoinFrameProcessorFactory.validateCondition(JoinConditionAnalysis.forExpression("x == \"j.y\"", "j.", ExprMacroTable.nil())));
    Assert.assertNotNull(SortMergeJoinFrameProcessorFactory.validateCondition(JoinConditionAnalysis.forExpression("1", "j.", ExprMacroTable.nil())));
    Assert.assertNotNull(SortMergeJoinFrameProcessorFactory.validateCondition(JoinConditionAnalysis.forExpression("x == \"j.y\" && a == \"j.b\"", "j.", ExprMacroTable.nil())));
    Assert.assertNotNull(SortMergeJoinFrameProcessorFactory.validateCondition(JoinConditionAnalysis.forExpression("notdistinctfrom(x, \"j.y\") && a == \"j.b\"", "j.", ExprMacroTable.nil())));
    Assert.assertThrows(IllegalArgumentException.class, () -> SortMergeJoinFrameProcessorFactory.validateCondition(JoinConditionAnalysis.forExpression("x == y", "j.", ExprMacroTable.nil())));
