    final FrameSequenceBuilder frameSequenceBuilder = FrameSequenceBuilder.fromAdapter(adapter).maxRowsPerFrame(5).frameType(FrameType.ROW_BASED).allocator(ArenaMemoryAllocator.createOnHeap(100_000));
