    final ScanQuery query = Druids.newScanQueryBuilder().dataSource("test").intervals(new MultipleIntervalSegmentSpec(Intervals.ONLY_ETERNITY)).columns(adapter.getRowSignature().getColumnNames()).build();
    final StagePartition stagePartition = new StagePartition(new StageId("query", 0), 0);
    // Limit output frames to 1 row to ensure we test edge cases
    final FrameWriterFactory frameWriterFactory = new LimitedFrameWriterFactory(FrameWriters.makeRowBasedFrameWriterFactory(new SingleMemoryAllocatorFactory(HeapMemoryAllocator.unlimited()), signature, Collections.emptyList(), false), 1);
    final ScanQueryFrameProcessor processor = new ScanQueryFrameProcessor(query, null, new DefaultObjectMapper(), ReadableInput.channel(inputChannel.readable(), FrameReader.create(signature), stagePartition), Function.identity(), new ResourceHolder<WritableFrameChannel>() {

        @Override
