public void testAverageKeyLength() {
    final QuantilesSketchKeyCollector collector = QuantilesSketchKeyCollectorFactory.create(clusterBy, signature).newKeyCollector();
    final QuantilesSketchKeyCollector other = QuantilesSketchKeyCollectorFactory.create(clusterBy, signature).newKeyCollector();
    RowSignature smallKeySignature = KeyTestUtils.createKeySignature(new ClusterBy(ImmutableList.of(new KeyColumn("x", KeyOrder.ASCENDING)), 0).getColumns(), RowSignature.builder().add("x", ColumnType.LONG).build());
    RowKey smallKey = KeyTestUtils.createKey(smallKeySignature, 1L);
    RowSignature largeKeySignature = KeyTestUtils.createKeySignature(new ClusterBy(ImmutableList.of(new KeyColumn("x", KeyOrder.ASCENDING), new KeyColumn("y", KeyOrder.ASCENDING), new KeyColumn("z", KeyOrder.ASCENDING)), 0).getColumns(), RowSignature.builder().add("x", ColumnType.LONG).add("y", ColumnType.LONG).add("z", ColumnType.LONG).build());
    RowKey largeKey = KeyTestUtils.createKey(largeKeySignature, 1L, 2L, 3L);
    collector.add(smallKey, 3);
    Assert.assertEquals(smallKey.estimatedObjectSizeBytes(), collector.getAverageKeyLength(), 0);
    other.add(largeKey, 5);
    Assert.assertEquals(largeKey.estimatedObjectSizeBytes(), other.getAverageKeyLength(), 0);
    collector.addAll(other);
    Assert.assertEquals((smallKey.estimatedObjectSizeBytes() * 3 + largeKey.estimatedObjectSizeBytes() * 5) / 8.0, collector.getAverageKeyLength(), 0);
}

