    Assert.assertThrows(BadQueryContextException.class, () -> decodeSortOrder("[["));
}

@Test
public void testGetIndexSpec() {
    Assert.assertNull(decodeIndexSpec(null));
    Assert.assertEquals(IndexSpec.DEFAULT, decodeIndexSpec("{}"));
    Assert.assertEquals(IndexSpec.DEFAULT, decodeIndexSpec(Collections.emptyMap()));
    Assert.assertEquals(IndexSpec.builder().withStringDictionaryEncoding(new StringEncodingStrategy.FrontCoded(null, null)).build(), decodeIndexSpec("{\"stringDictionaryEncoding\":{\"type\":\"frontCoded\"}}"));
    Assert.assertEquals(IndexSpec.builder().withStringDictionaryEncoding(new StringEncodingStrategy.FrontCoded(null)).build(), decodeIndexSpec(ImmutableMap.of("stringDictionaryEncoding", ImmutableMap.of("type", "frontCoded"))));
    final BadQueryContextException e = Assert.assertThrows(BadQueryContextException.class, () -> decodeIndexSpec("{"));
    MatcherAssert.assertThat(e, ThrowableMessageMatcher.hasMessage(CoreMatchers.equalTo("Expected key [indexSpec] to be an indexSpec, but got [{]")));
}

