        Assert.assertEquals(2L, row.getRaw("struct_list_struct_int"));
        Assert.assertEquals(DateTimes.of("2000-03-12T15:00:00.0Z"), row.getTimestamp());
        while (iterator.hasNext()) {
            actualRowCount++;
            row = iterator.next();
        }
        // Check the last row
        Assert.assertEquals(ImmutableMap.of("list", ImmutableList.of(ImmutableMap.of("int1", 1, "string1", "bye"), ImmutableMap.of("int1", 2, "string1", "sigh"))), row.getRaw("middle"));
        Assert.assertEquals(ImmutableList.of(ImmutableMap.of("int1", 100000000, "string1", "cat"), ImmutableMap.of("int1", -100000, "string1", "in"), ImmutableMap.of("int1", 1234, "string1", "hat")), row.getRaw("list"));
