@Test
public void testListMap() throws IOException {
    final InputFormat inputFormat = new OrcInputFormat(new JSONPathSpec(true, ImmutableList.of(new JSONPathFieldSpec(JSONPathFieldType.PATH, "a_id0", "$.a['id0']"), new JSONPathFieldSpec(JSONPathFieldType.PATH, "b_raw_str", "$.b"), new JSONPathFieldSpec(JSONPathFieldType.PATH, "b0_id0", "$.b[0]['id0']"))), null, new Configuration());
    final InputEntityReader reader = createReader(new TimestampSpec("timestamp", "auto", null), new DimensionsSpec(ImmutableList.of(new AutoTypeColumnSchema("a", null), new AutoTypeColumnSchema("b", null))), inputFormat, "example/test_list_map.orc");
    final TransformSpec transformSpec = new TransformSpec(null, ImmutableList.of(new ExpressionTransform("t_a_id0", "json_value(a, '$.id0')", TestExprMacroTable.INSTANCE), new ExpressionTransform("t_b0_id0", "json_value(b, '$[0].id0')", TestExprMacroTable.INSTANCE)));
    final InputEntityReader transformingReader = new TransformingInputEntityReader(reader, transformSpec.toTransformer());
    try (CloseableIterator<InputRow> iterator = transformingReader.read()) {
        Assert.assertTrue(iterator.hasNext());
        final InputRow row = iterator.next();
        /*
        {
          "timestamp": "2022-01-01T00:00:00",
          "a": {"id0": "str0", "id1": "str1"},
          "b": [{"id0": "str0", "id1": "str1"}, {"id0": "str2", "id1": "str3"}]
        }
     */
        Assert.assertEquals(DateTimes.of("2022-01-01T00:00:00.000Z"), row.getTimestamp());
        Assert.assertEquals("str0", Iterables.getOnlyElement(row.getDimension("a_id0")));
        Assert.assertEquals("str0", Iterables.getOnlyElement(row.getDimension("t_a_id0")));
        Assert.assertEquals("str0", Iterables.getOnlyElement(row.getDimension("b0_id0")));
        Assert.assertEquals("str0", Iterables.getOnlyElement(row.getDimension("t_b0_id0")));
        Assert.assertEquals(ImmutableList.of("{id0=str0, id1=str1}", "{id0=str2, id1=str3}"), row.getDimension("b_raw_str"));
        Assert.assertEquals(ImmutableMap.of("id0", "str0", "id1", "str1"), row.getRaw("a"));
        Assert.assertEquals(ImmutableList.of(ImmutableMap.of("id0", "str0", "id1", "str1"), ImmutableMap.of("id0", "str2", "id1", "str3")), row.getRaw("b"));
        Assert.assertFalse(iterator.hasNext());
    }
}

@Test
public void testNestedArray() throws IOException {
    final InputFormat inputFormat = new OrcInputFormat(new JSONPathSpec(true, ImmutableList.of(new JSONPathFieldSpec(JSONPathFieldType.PATH, "a_0", "$.a[0]"), new JSONPathFieldSpec(JSONPathFieldType.PATH, "b_0", "$.b[0]"), new JSONPathFieldSpec(JSONPathFieldType.PATH, "c_0_0", "$.c[0][0]"), new JSONPathFieldSpec(JSONPathFieldType.PATH, "d_0_1", "$.d[0][1]"))), null, new Configuration());
    final InputEntityReader reader = createReader(new TimestampSpec("timestamp", "auto", null), new DimensionsSpec(ImmutableList.of(new AutoTypeColumnSchema("a", null), new AutoTypeColumnSchema("b", null), new AutoTypeColumnSchema("c", null), new AutoTypeColumnSchema("d", null), new AutoTypeColumnSchema("t_d_0", null))), inputFormat, "example/test_nested_array.orc");
    final TransformSpec transformSpec = new TransformSpec(null, ImmutableList.of(new ExpressionTransform("t_a_0", "json_value(a, '$[0]')", TestExprMacroTable.INSTANCE), new ExpressionTransform("t_b_0", "json_value(b, '$[0]')", TestExprMacroTable.INSTANCE), new ExpressionTransform("t_c_0_0", "json_value(c, '$[0][0]')", TestExprMacroTable.INSTANCE), new ExpressionTransform("t_d_0_1", "json_value(d, '$[0][1]')", TestExprMacroTable.INSTANCE), new ExpressionTransform("t_d_0", "json_query(d, '$[0]')", TestExprMacroTable.INSTANCE)));
    final InputEntityReader transformingReader = new TransformingInputEntityReader(reader, transformSpec.toTransformer());
    try (CloseableIterator<InputRow> iterator = transformingReader.read()) {
        Assert.assertTrue(iterator.hasNext());
        final InputRow row = iterator.next();
        /*
        {
          "timestamp": "2022-01-01T00:00:00",
          "a": ["str1", "str2"],
          "b": [1, 2],
          "c": [["str1", "str2"], ["str3", "str4"]],
          "d": [[1, 2], [3, 4]]
        }
       */
        Assert.assertEquals(DateTimes.of("2022-01-01T00:00:00.000Z"), row.getTimestamp());
        Assert.assertEquals("str1", Iterables.getOnlyElement(row.getDimension("a_0")));
        Assert.assertEquals("str1", Iterables.getOnlyElement(row.getDimension("t_a_0")));
        Assert.assertEquals("1", Iterables.getOnlyElement(row.getDimension("b_0")));
        Assert.assertEquals("1", Iterables.getOnlyElement(row.getDimension("t_b_0")));
        Assert.assertEquals("str1", Iterables.getOnlyElement(row.getDimension("c_0_0")));
        Assert.assertEquals("str1", Iterables.getOnlyElement(row.getDimension("t_c_0_0")));
        Assert.assertEquals("2", Iterables.getOnlyElement(row.getDimension("d_0_1")));
        Assert.assertEquals("2", Iterables.getOnlyElement(row.getDimension("t_d_0_1")));
        Assert.assertEquals(ImmutableList.of("str1", "str2"), row.getRaw("a"));
        Assert.assertEquals(ImmutableList.of(1, 2), row.getRaw("b"));
        Assert.assertEquals(ImmutableList.of(ImmutableList.of("str1", "str2"), ImmutableList.of("str3", "str4")), row.getRaw("c"));
        Assert.assertEquals(ImmutableList.of(ImmutableList.of(1, 2), ImmutableList.of(3, 4)), row.getRaw("d"));
        Assert.assertArrayEquals(new Object[] { 1L, 2L }, (Object[]) row.getRaw("t_d_0"));
        Assert.assertFalse(iterator.hasNext());
    }
}

