@Test
public void testParseNestedData() throws Exception {
    ProtobufInputFormat protobufInputFormat = new ProtobufInputFormat(JSONPathSpec.DEFAULT, decoder);
    //create binary of proto test event
    DateTime dateTime = new DateTime(2012, 7, 12, 9, 30, ISOChronology.getInstanceUTC());
    ProtoTestEventWrapper.ProtoTestEvent event = ProtobufInputRowParserTest.buildNestedData(dateTime);
    final ByteEntity entity = new ByteEntity(ProtobufInputRowParserTest.toByteBuffer(event));
    InputEntityReader reader = protobufInputFormat.createReader(new InputRowSchema(timestampSpec, new DimensionsSpec(Lists.newArrayList(new AutoTypeColumnSchema("event", null), new AutoTypeColumnSchema("id", null), new AutoTypeColumnSchema("someOtherId", null), new AutoTypeColumnSchema("isValid", null), new AutoTypeColumnSchema("eventType", null), new AutoTypeColumnSchema("foo", null), new AutoTypeColumnSchema("bar", null), new AutoTypeColumnSchema("someBytesColumn", null))), null), entity, null);
    TransformSpec transformSpec = new TransformSpec(null, Lists.newArrayList(new ExpressionTransform("foobar", "JSON_VALUE(foo, '$.bar')", TestExprMacroTable.INSTANCE), new ExpressionTransform("bar0", "JSON_VALUE(bar, '$[0].bar')", TestExprMacroTable.INSTANCE)));
    TransformingInputEntityReader transformingReader = new TransformingInputEntityReader(reader, transformSpec.toTransformer());
    InputRow row = transformingReader.read().next();
    Assert.assertEquals(ImmutableList.builder().add("event").add("id").add("someOtherId").add("isValid").add("eventType").add("foo").add("bar").add("someBytesColumn").build(), row.getDimensions());
    Assert.assertEquals(ImmutableMap.of("bar", "baz"), row.getRaw("foo"));
    Assert.assertEquals(ImmutableList.of(ImmutableMap.of("bar", "bar0"), ImmutableMap.of("bar", "bar1")), row.getRaw("bar"));
    Assert.assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04 }, (byte[]) row.getRaw("someBytesColumn"));
    ProtobufInputRowParserTest.verifyNestedData(row, dateTime);
}

