@Test
public void testReadRange() throws IOException {
    String data = "test";
    // non empty reads
    for (int start = 0; start < data.length(); start++) {
        for (int length = 1; length <= data.length() - start; length++) {
            String dataQueried = data.substring(start, start + length);
            EasyMock.reset(s3Client);
            S3Object s3Object = new S3Object();
            s3Object.setObjectContent(new ByteArrayInputStream(dataQueried.getBytes(StandardCharsets.UTF_8)));
            EasyMock.expect(s3Client.getObject(new GetObjectRequest(BUCKET, PREFIX + "/" + TEST_FILE).withRange(start, start + length - 1))).andReturn(s3Object);
            EasyMock.replay(s3Client);
            InputStream is = storageConnector.readRange(TEST_FILE, start, length);
            byte[] dataBytes = new byte[length];
            Assert.assertEquals(length, is.read(dataBytes));
            // reading further produces no data
            Assert.assertEquals(-1, is.read());
            Assert.assertEquals(dataQueried, new String(dataBytes, StandardCharsets.UTF_8));
            EasyMock.reset(s3Client);
        }
    }
    // empty read
    EasyMock.reset(s3Client);
    S3Object s3Object = new S3Object();
    s3Object.setObjectContent(new ByteArrayInputStream("".getBytes(StandardCharsets.UTF_8)));
    EasyMock.expect(s3Client.getObject(new GetObjectRequest(BUCKET, PREFIX + "/" + TEST_FILE).withRange(0, -1))).andReturn(s3Object);
    EasyMock.replay(s3Client);
    InputStream is = storageConnector.readRange(TEST_FILE, 0, 0);
    byte[] dataBytes = new byte[0];
    Assert.assertEquals(is.read(dataBytes), -1);
    Assert.assertEquals("", new String(dataBytes, StandardCharsets.UTF_8));
    EasyMock.reset(s3Client);
}

