        new File(baseDir, "dir1/file2").createNewFile();
        FileUtils.mkdirp(new File(baseDir, "dir2/subDir1"));
        new File(baseDir, "dir2/subDir1/file3").createNewFile();
        FileUtils.mkdirp(new File(baseDir, "dir2/subDir2"));
