        final List<TaskLock> futureLocks = taskActionTestKit.getTaskLockbox().findLocksForTask(task).stream().filter(input -> input.getInterval().contains(THE_DISTANT_FUTURE)).collect(Collectors.toList());
        Assert.assertEquals(1, futureLocks.size());
        partitionIdToLock.clear();
        futureLocks.forEach(lock -> {
            Assert.assertEquals(LockGranularity.SEGMENT, lock.getGranularity());
            final SegmentLock segmentLock = (SegmentLock) lock;
            partitionIdToLock.put(segmentLock.getPartitionId(), segmentLock);
        });
        for (Entry<Integer, SegmentLock> entry : partitionIdToLock.entrySet()) {
            assertSameIdentifier(new SegmentIdWithShardSpec(DATA_SOURCE, Granularities.HOUR.bucket(THE_DISTANT_FUTURE), allocatedFutureIds.get(entry.getKey()).getVersion(), new NumberedShardSpec(entry.getValue().getPartitionId(), 0)), allocatedFutureIds.get(entry.getKey()));
        }
    }
    Assert.assertNull(id4);
    assertSameIdentifier(id2, id5);
    Assert.assertNull(id6);
    assertSameIdentifier(id2, id7);
}

@Test
public void testSegmentIsAllocatedForLatestUsedSegmentVersion() {
    final Task task = NoopTask.create();
    taskActionTestKit.getTaskLockbox().add(task);
    final String sequenceName = "sequence_1";
    // Allocate segments when there are no committed segments
    final SegmentIdWithShardSpec pendingSegmentV01 = allocate(task, PARTY_TIME, Granularities.NONE, Granularities.HOUR, sequenceName, null);
    final SegmentIdWithShardSpec pendingSegmentV02 = allocate(task, PARTY_TIME, Granularities.NONE, Granularities.HOUR, sequenceName, null);
    assertSameIdentifier(pendingSegmentV01, pendingSegmentV02);
    // Commit a segment for version V1
    final DataSegment segmentV1 = DataSegment.builder().dataSource(DATA_SOURCE).interval(Granularities.HOUR.bucket(PARTY_TIME)).version(PARTY_TIME.plusDays(1).toString()).shardSpec(new LinearShardSpec(0)).size(100).build();
    taskActionTestKit.getMetadataStorageCoordinator().commitSegments(Collections.singleton(segmentV1), null);
    // Verify that new allocations use version V1
    final SegmentIdWithShardSpec pendingSegmentV11 = allocate(task, PARTY_TIME, Granularities.NONE, Granularities.HOUR, sequenceName, null);
    final SegmentIdWithShardSpec pendingSegmentV12 = allocate(task, PARTY_TIME, Granularities.NONE, Granularities.HOUR, sequenceName, null);
    assertSameIdentifier(pendingSegmentV11, pendingSegmentV12);
    Assert.assertEquals(segmentV1.getVersion(), pendingSegmentV11.getVersion());
    Assert.assertNotEquals(pendingSegmentV01, pendingSegmentV11);
    // Commit a segment for version V2 to overshadow V1
    final DataSegment segmentV2 = DataSegment.builder().dataSource(DATA_SOURCE).interval(Granularities.HOUR.bucket(PARTY_TIME)).version(PARTY_TIME.plusDays(2).toString()).shardSpec(new LinearShardSpec(0)).size(100).build();
    taskActionTestKit.getMetadataStorageCoordinator().commitSegments(Collections.singleton(segmentV2), null);
    Assert.assertTrue(segmentV2.getVersion().compareTo(segmentV1.getVersion()) > 0);
    // Verify that new segment allocations use version V2
    final SegmentIdWithShardSpec pendingSegmentV21 = allocate(task, PARTY_TIME, Granularities.NONE, Granularities.HOUR, sequenceName, null);
