// The next test also verifies replace functionality. Now, they are together to save on test execution time
// due to Travis CI 10 minute default running time (with no output) -- having it separate made it
// last longer. At some point we should really simplify this file, so it runs faster (splitting, etc.)
@Test
public void createsCorrectRangePartitions() throws Exception {
    int targetRowsPerSegment = NUM_ROW * 2 / DIM_FILE_CARDINALITY / NUM_PARTITION;
    // verify dropExisting false
    final DataSegmentsWithSchemas publishedDataSegmentsWithSchemas = runTask(runTestTask(new DimensionRangePartitionsSpec(targetRowsPerSegment, null, Collections.singletonList(DIM1), false), inputDir, false, false), useMultivalueDim ? TaskState.FAILED : TaskState.SUCCESS);
    final Set<DataSegment> publishedSegments = publishedDataSegmentsWithSchemas.getSegments();
    if (!useMultivalueDim) {
        assertRangePartitions(publishedSegments);
        Assert.assertEquals(1, publishedDataSegmentsWithSchemas.getSegmentSchemaMapping().getSchemaFingerprintToPayloadMap().size());
        Assert.assertEquals(publishedSegments.size(), publishedDataSegmentsWithSchemas.getSegmentSchemaMapping().getSegmentIdToMetadataMap().size());
        for (DataSegment segment : publishedSegments) {
            Assert.assertTrue(publishedDataSegmentsWithSchemas.getSegmentSchemaMapping().getSegmentIdToMetadataMap().containsKey(segment.getId().toString()));
        }
    }
    // verify dropExisting true
    if (intervalToIndex == null) {
        // dropExisting requires intervals
        return;
    }
    File inputDirectory = temporaryFolder.newFolder("dataReplace");
    createInputFilesForReplace(inputDirectory, useMultivalueDim);
    final DataSegmentsWithSchemas publishedDataSegmentsWithSchemasAfterReplace = runTask(runTestTask(new DimensionRangePartitionsSpec(targetRowsPerSegment, null, Collections.singletonList(DIM1), false), inputDirectory, false, true), useMultivalueDim ? TaskState.FAILED : TaskState.SUCCESS);
    final Set<DataSegment> publishedSegmentsAfterReplace = publishedDataSegmentsWithSchemasAfterReplace.getSegments();
    int tombstones = 0;
    for (DataSegment ds : publishedSegmentsAfterReplace) {
        if (ds.isTombstone()) {
            tombstones++;
        }
    }
    if (!useMultivalueDim) {
        Assert.assertEquals(11, tombstones);
        Assert.assertEquals(10, publishedSegmentsAfterReplace.size() - tombstones);
        for (DataSegment segment : publishedSegmentsAfterReplace) {
            if (!segment.isTombstone()) {
                Assert.assertTrue(publishedDataSegmentsWithSchemasAfterReplace.getSegmentSchemaMapping().getSegmentIdToMetadataMap().containsKey(segment.getId().toString()));
            }
        }
        Assert.assertEquals(10, publishedDataSegmentsWithSchemasAfterReplace.getSegmentSchemaMapping().getSegmentIdToMetadataMap().size());
        Assert.assertEquals(1, publishedDataSegmentsWithSchemasAfterReplace.getSegmentSchemaMapping().getSchemaFingerprintToPayloadMap().size());
    }
}

@Test
public void testAppendLinearlyPartitionedSegmentsToHashPartitionedDatasourceSuccessfullyAppend() {
    if (useMultivalueDim) {
        return;
    }
    final int targetRowsPerSegment = NUM_ROW / DIM_FILE_CARDINALITY / NUM_PARTITION;
    DataSegmentsWithSchemas dataSegmentsWithSchemas = runTask(runTestTask(new SingleDimensionPartitionsSpec(targetRowsPerSegment, null, DIM1, false), inputDir, false, false), TaskState.SUCCESS);
    verifySchema(dataSegmentsWithSchemas);
    final Set<DataSegment> publishedSegments = new HashSet<>(dataSegmentsWithSchemas.getSegments());
    // Append
    dataSegmentsWithSchemas = runTask(runTestTask(new DynamicPartitionsSpec(5, null), inputDir, true, false), TaskState.SUCCESS);
    publishedSegments.addAll(dataSegmentsWithSchemas.getSegments());
    verifySchema(dataSegmentsWithSchemas);
    // And append again
    dataSegmentsWithSchemas = runTask(runTestTask(new DynamicPartitionsSpec(10, null), inputDir, true, false), TaskState.SUCCESS);
    verifySchema(dataSegmentsWithSchemas);
    publishedSegments.addAll(dataSegmentsWithSchemas.getSegments());
    final Map<Interval, List<DataSegment>> intervalToSegments = new HashMap<>();
    publishedSegments.forEach(segment -> intervalToSegments.computeIfAbsent(segment.getInterval(), k -> new ArrayList<>()).add(segment));
    for (Entry<Interval, List<DataSegment>> entry : intervalToSegments.entrySet()) {
        final List<DataSegment> segments = entry.getValue();
        final List<DataSegment> rangedSegments = segments.stream().filter(segment -> segment.getShardSpec().getClass() == SingleDimensionShardSpec.class).collect(Collectors.toList());
        final List<DataSegment> linearSegments = segments.stream().filter(segment -> segment.getShardSpec().getClass() == NumberedShardSpec.class).collect(Collectors.toList());
        for (DataSegment rangedSegment : rangedSegments) {
            final SingleDimensionShardSpec rangeShardSpec = (SingleDimensionShardSpec) rangedSegment.getShardSpec();
            for (DataSegment linearSegment : linearSegments) {
                Assert.assertEquals(rangedSegment.getInterval(), linearSegment.getInterval());
                Assert.assertEquals(rangedSegment.getVersion(), linearSegment.getVersion());
                final NumberedShardSpec numberedShardSpec = (NumberedShardSpec) linearSegment.getShardSpec();
                Assert.assertEquals(rangeShardSpec.getNumCorePartitions(), numberedShardSpec.getNumCorePartitions());
                Assert.assertTrue(rangeShardSpec.getPartitionNum() < numberedShardSpec.getPartitionNum());
            }
        }
    }
}

