@Test
public void testBasic() throws InterruptedException, ExecutionException, TimeoutException {
    final List<ListenableFuture<SubTaskCompleteEvent<TestTask>>> futures = IntStream.range(0, 10).mapToObj(i -> monitor.submit(new TestTaskSpec("specId" + i, "groupId", "supervisorId", null, new IntegerInputSplit(i), 100L, 0, false))).collect(Collectors.toList());
