@Test
public void testRunWithSpatialDimensions() throws Exception {
    final List<String> spatialrows = ImmutableList.of("2014-01-01T00:00:10Z,a,10,100,1\n", "2014-01-01T00:00:10Z,b,20,110,2\n", "2014-01-01T00:00:10Z,c,30,120,3\n", "2014-01-01T01:00:20Z,a,10,100,1\n", "2014-01-01T01:00:20Z,b,20,110,2\n", "2014-01-01T01:00:20Z,c,30,120,3\n");
    final ParseSpec spatialSpec = new CSVParseSpec(new TimestampSpec("ts", "auto", null), DimensionsSpec.builder().setDimensions(Arrays.asList(new StringDimensionSchema("ts"), new StringDimensionSchema("dim"), new NewSpatialDimensionSchema("spatial", Arrays.asList("x", "y")))).build(), "|", Arrays.asList("ts", "dim", "x", "y", "val"), false, 0);
    Pair<TaskStatus, DataSegmentsWithSchemas> indexTaskResult = runIndexTask(null, null, spatialSpec, spatialrows, false);
    verifySchema(indexTaskResult.rhs);
    final Builder builder = new Builder(DATA_SOURCE, segmentCacheManagerFactory);
    final CompactionTask compactionTask = builder.interval(Intervals.of("2014-01-01/2014-01-02")).build();
    final Pair<TaskStatus, DataSegmentsWithSchemas> resultPair = runTask(compactionTask);
    verifySchema(resultPair.rhs);
    Assert.assertTrue(resultPair.lhs.isSuccess());
    final List<DataSegment> segments = new ArrayList<>(resultPair.rhs.getSegments());
    Assert.assertEquals(2, segments.size());
    for (int i = 0; i < 2; i++) {
        Assert.assertEquals(Intervals.of("2014-01-01T0%d:00:00/2014-01-01T0%d:00:00", i, i + 1), segments.get(i).getInterval());
        Map<String, String> expectedLongSumMetric = new HashMap<>();
        expectedLongSumMetric.put("name", "val");
        expectedLongSumMetric.put("type", "longSum");
        expectedLongSumMetric.put("fieldName", "val");
        Assert.assertEquals(getDefaultCompactionState(Granularities.HOUR, Granularities.MINUTE, ImmutableList.of(Intervals.of("2014-01-01T0%d:00:00/2014-01-01T0%d:00:00", i, i + 1)), DimensionsSpec.builder().setDimensions(Arrays.asList(new StringDimensionSchema("ts"), new StringDimensionSchema("dim"), new NewSpatialDimensionSchema("spatial", Collections.singletonList("spatial")))).build(), expectedLongSumMetric), segments.get(i).getLastCompactionState());
        if (lockGranularity == LockGranularity.SEGMENT) {
            Assert.assertEquals(new NumberedOverwriteShardSpec(32768, 0, 2, (short) 1, (short) 1), segments.get(i).getShardSpec());
        } else {
            Assert.assertEquals(new NumberedShardSpec(0, 1), segments.get(i).getShardSpec());
        }
    }
    final File cacheDir = temporaryFolder.newFolder();
    final SegmentCacheManager segmentCacheManager = segmentCacheManagerFactory.manufacturate(cacheDir);
    List<String> rowsFromSegment = new ArrayList<>();
    for (DataSegment segment : segments) {
        final File segmentFile = segmentCacheManager.getSegmentFiles(segment);
        final WindowedStorageAdapter adapter = new WindowedStorageAdapter(new QueryableIndexStorageAdapter(testUtils.getTestIndexIO().loadIndex(segmentFile)), segment.getInterval());
        final Sequence<Cursor> cursorSequence = adapter.getAdapter().makeCursors(null, segment.getInterval(), VirtualColumns.EMPTY, Granularities.ALL, false, null);
        cursorSequence.accumulate(rowsFromSegment, (accumulated, cursor) -> {
            cursor.reset();
            final ColumnSelectorFactory factory = cursor.getColumnSelectorFactory();
            Assert.assertTrue(factory.getColumnCapabilities("spatial").hasSpatialIndexes());
            while (!cursor.isDone()) {
                final ColumnValueSelector<?> selector1 = factory.makeColumnValueSelector("ts");
                final DimensionSelector selector2 = factory.makeDimensionSelector(new DefaultDimensionSpec("dim", "dim"));
                final DimensionSelector selector3 = factory.makeDimensionSelector(new DefaultDimensionSpec("spatial", "spatial"));
                final DimensionSelector selector4 = factory.makeDimensionSelector(new DefaultDimensionSpec("val", "val"));
                rowsFromSegment.add(StringUtils.format("%s,%s,%s,%s\n", selector1.getObject(), selector2.getObject(), selector3.getObject(), selector4.getObject()));
                cursor.advance();
            }
            return accumulated;
        });
    }
    Assert.assertEquals(spatialrows, rowsFromSegment);
}

