@Test
public void testIndexTaskTuningConfigTargetPartitionSizeOrNumShards() throws Exception {
    IndexTask.IndexTuningConfig tuningConfig = jsonMapper.readValue("{\"type\":\"index\", \"targetPartitionSize\":10}", IndexTask.IndexTuningConfig.class);
    Assert.assertEquals(10, (int) tuningConfig.getMaxRowsPerSegment());
    Assert.assertNull(tuningConfig.getNumShards());
    tuningConfig = jsonMapper.readValue("{\"type\":\"index\"}", IndexTask.IndexTuningConfig.class);
    Assert.assertNull(tuningConfig.getMaxRowsPerSegment());
    tuningConfig = jsonMapper.readValue("{\"type\":\"index\", \"maxRowsPerSegment\":10}", IndexTask.IndexTuningConfig.class);
    Assert.assertEquals(10, (int) tuningConfig.getMaxRowsPerSegment());
    Assert.assertNull(tuningConfig.getNumShards());
    tuningConfig = jsonMapper.readValue("{\"type\":\"index\", \"numShards\":10, \"forceGuaranteedRollup\": true}", IndexTask.IndexTuningConfig.class);
    Assert.assertNull(tuningConfig.getMaxRowsPerSegment());
    Assert.assertEquals(10, (int) tuningConfig.getNumShards());
    tuningConfig = jsonMapper.readValue("{\"type\":\"index\", \"targetPartitionSize\":-1, \"numShards\":10, \"forceGuaranteedRollup\": true}", IndexTask.IndexTuningConfig.class);
    Assert.assertNull(tuningConfig.getMaxRowsPerSegment());
    Assert.assertEquals(10, (int) tuningConfig.getNumShards());
    tuningConfig = jsonMapper.readValue("{\"type\":\"index\", \"targetPartitionSize\":10, \"numShards\":-1}", IndexTask.IndexTuningConfig.class);
    Assert.assertNull(tuningConfig.getNumShards());
    Assert.assertEquals(10, (int) tuningConfig.getMaxRowsPerSegment());
    tuningConfig = jsonMapper.readValue("{\"type\":\"index\", \"targetPartitionSize\":-1, \"numShards\":-1, \"forceGuaranteedRollup\": true}", IndexTask.IndexTuningConfig.class);
    Assert.assertNull(tuningConfig.getNumShards());
    Assert.assertNotNull(tuningConfig.getMaxRowsPerSegment());
    Assert.assertEquals(PartitionsSpec.DEFAULT_MAX_ROWS_PER_SEGMENT, tuningConfig.getMaxRowsPerSegment().intValue());
}

