    Assert.assertTrue(TestUtils.conditionValid(() -> !remoteTaskRunner.getRunningTasks().isEmpty() && !Iterables.getOnlyElement(remoteTaskRunner.getRunningTasks()).getLocation().equals(TaskLocation.unknown())));
    // Stream task reports from a running task.
