@Test
public void testStop() throws ExecutionException, InterruptedException, TimeoutException {
    AtomicReference<Boolean> methodCallHolder = new AtomicReference<>();
    final ListenableFuture<TaskStatus> future = runner.run(new // infinite task
    NoopTask(// infinite task
    null, // infinite task
    null, // infinite task
    null, // infinite task
    Long.MAX_VALUE, // infinite task
    0, // infinite task
    null) {

        @Override
        public boolean waitForCleanupToFinish() {
            methodCallHolder.set(true);
            return true;
        }
    });
    runner.stop();
    Assert.assertEquals(TaskState.FAILED, future.get(1000, TimeUnit.MILLISECONDS).getStatusCode());
    Assert.assertTrue(methodCallHolder.get());
}

