@Test
public void testUnlockSupersededLocks() {
    final Task task = NoopTask.create();
    taskStorage.insert(task, TaskStatus.running(task.getId()));
    lockbox.add(task);
    final Task otherTask = NoopTask.create();
    taskStorage.insert(otherTask, TaskStatus.running(otherTask.getId()));
    lockbox.add(otherTask);
    // Can coexist and is superseded. Will be unlocked
    final TaskLock supersededLock = tryTimeChunkLock(TaskLockType.APPEND, task, Intervals.of("2024-01-01/2024-01-02"), "v0").getTaskLock();
    Assert.assertEquals(ImmutableSet.copyOf(taskStorage.getLocks(task.getId())), ImmutableSet.of(supersededLock));
    // Can coexist, but is not superseded as the task doesn't belong to this posse
    final TaskLock taskNotInPosse = tryTimeChunkLock(TaskLockType.APPEND, otherTask, Intervals.of("2024-01-01/2024-01-02"), "v0").getTaskLock();
    Assert.assertEquals(ImmutableSet.copyOf(taskStorage.getLocks(otherTask.getId())), ImmutableSet.of(taskNotInPosse));
    // Can coexist, but is not superseded as it is not an APPEND lock
    final TaskLock replaceLock = tryTimeChunkLock(TaskLockType.REPLACE, task, Intervals.of("2024-01-01/2025-01-01"), "v0").getTaskLock();
    Assert.assertEquals(ImmutableSet.copyOf(taskStorage.getLocks(task.getId())), ImmutableSet.of(supersededLock, replaceLock));
    // Can coexist, but is not superseded due to higher version
    final TaskLock higherVersion = tryTimeChunkLock(TaskLockType.APPEND, task, Intervals.of("2024-01-11/2024-01-12"), "v1").getTaskLock();
    Assert.assertEquals(ImmutableSet.copyOf(taskStorage.getLocks(task.getId())), ImmutableSet.of(supersededLock, replaceLock, higherVersion));
    // Can coexist, but is not superseded as interval is not fully contained
    final TaskLock uncontainedInterval = tryTimeChunkLock(TaskLockType.APPEND, task, Intervals.of("2024-01-28/2024-02-04"), "v0").getTaskLock();
    Assert.assertEquals(ImmutableSet.copyOf(taskStorage.getLocks(task.getId())), ImmutableSet.of(supersededLock, replaceLock, higherVersion, uncontainedInterval));
    final TaskLock theLock = tryTimeChunkLock(TaskLockType.APPEND, task, Intervals.of("2024-01-01/2024-02-01"), "v0").getTaskLock();
    Assert.assertEquals(ImmutableSet.copyOf(taskStorage.getLocks(task.getId())), ImmutableSet.of(theLock, replaceLock, higherVersion, uncontainedInterval));
    Assert.assertEquals(ImmutableSet.copyOf(taskStorage.getLocks(otherTask.getId())), ImmutableSet.of(taskNotInPosse));
}

