@Test(timeout = 60_000L)
public void doMassLaunchAndShutdown() throws Exception {
    Assert.assertEquals("no tasks should be running", 0, taskRunner.getKnownTasks().size());
    // Add all tasks.
    final List<String> taskIds = new ArrayList<>();
    for (int i = 0; i < numTasks; i++) {
        final NoopTask testTask = createTestTask(Duration.standardHours(1).getMillis());
        taskQueue.add(testTask);
        taskIds.add(testTask.getId());
    }
    // wait for all tasks to progress to running state
    while (taskStorage.getActiveTasks().size() < numTasks) {
        Thread.sleep(100);
    }
    Assert.assertEquals("all tasks should be running", numTasks, taskStorage.getActiveTasks().size());
    // Shut down all tasks.
    for (final String taskId : taskIds) {
        taskQueue.shutdown(taskId, "test shutdown");
    }
    // Wait for all tasks to finish.
    while (!taskStorage.getActiveTasks().isEmpty()) {
        Thread.sleep(100);
    }
    Assert.assertEquals("no tasks should be running", 0, taskStorage.getActiveTasks().size());
    int completed = taskStorage.getTaskInfos(TaskLookup.CompleteTaskLookup.of(numTasks, Duration.standardHours(1)), DATASOURCE).size();
    Assert.assertEquals("all tasks should have completed", numTasks, completed);
}

@Test
public void testManageInternalReleaseLockWhenTaskIsNotReady() throws Exception {
    // task1 emulates a case when there is a task that was issued before task2 and acquired locks conflicting
    // to task2.
    final TestTask task1 = new TestTask("t1", Intervals.of("2021-01/P1M"));
    // Manually get locks for task1. task2 cannot be ready because of task1.
    prepareTaskForLocking(task1);
    Assert.assertTrue(task1.isReady(actionClientFactory.create(task1)));
    final TestTask task2 = new TestTask("t2", Intervals.of("2021-01-31/P1M"));
    taskQueue.add(task2);
    taskQueue.manageInternal();
    Assert.assertFalse(task2.isDone());
    Assert.assertTrue(getLockbox().findLocksForTask(task2).isEmpty());
    // task3 can run because task2 is still blocked by task1.
    final TestTask task3 = new TestTask("t3", Intervals.of("2021-02-01/P1M"));
    taskQueue.add(task3);
    taskQueue.manageInternal();
    Assert.assertFalse(task2.isDone());
    Assert.assertTrue(task3.isDone());
    Assert.assertTrue(getLockbox().findLocksForTask(task2).isEmpty());
    // Shut down task1 and task3 and release their locks.
    shutdownTask(task1);
    taskQueue.shutdown(task3.getId(), "Emulating shutdown of task3");
    // Now task2 should run.
    taskQueue.manageInternal();
    Assert.assertTrue(task2.isDone());
}

