    final SeekableStreamSupervisor.TaskGroup taskGroup1 = supervisor.addTaskGroupToActivelyReadingTaskGroup(supervisor.getTaskGroupIdForPartition("1"), ImmutableMap.of("1", "6"), Optional.absent(), Optional.absent(), ImmutableSet.of("task1"), ImmutableSet.of());
    final SeekableStreamSupervisor.TaskGroup taskGroup2 = supervisor.addTaskGroupToPendingCompletionTaskGroup(supervisor.getTaskGroupIdForPartition("2"), ImmutableMap.of("2", "100"), Optional.absent(), Optional.absent(), ImmutableSet.of("task2"), ImmutableSet.of());
    final PendingSegmentRecord pendingSegmentRecord0 = new PendingSegmentRecord(new SegmentIdWithShardSpec("DS", Intervals.of("2024/2025"), "2024", new NumberedShardSpec(1, 0)), taskGroup0.getBaseSequenceName(), "prevId0", "someAppendedSegment0", taskGroup0.getBaseSequenceName());
