    supervisor.registerNewVersionOfPendingSegment(pendingSegmentRecord1);
    Assert.assertEquals(pendingSegmentRecord0, captured0.getValue());
    Assert.assertEquals(pendingSegmentRecord1, captured1.getValue());
    verifyAll();
}

