        assertThrows(Exception.class, () -> client.createTable(table, false));
    }
}

/**
 * Run though a table lifecycle to sanity check each API. Thorough
 * testing of each API appears in unit tests.
 */
@Test
public void testLifecycle() {
    CatalogClient client = new CatalogClient(clusterClient);
    // Create a datasource
    TableMetadata table = TableBuilder.datasource("example", "P1D").column("a", "VARCHAR").column("b", "BIGINT").column("c", "FLOAT").build();
    // Use force action so test is reentrant if it fails part way through
    // when debugging.
    long version = client.createTable(table, true);
    // Update the datasource
    TableSpec dsSpec2 = TableBuilder.copyOf(table).property(DatasourceDefn.TARGET_SEGMENT_ROWS_PROPERTY, 3_000_000).column("d", "DOUBLE").buildSpec();
    // First, optimistic locking, wrong version
    assertThrows(ISE.class, () -> client.updateTable(table.id(), dsSpec2, 1));
    // Optimistic locking, correct version
    long newVersion = client.updateTable(table.id(), dsSpec2, version);
    assertTrue(newVersion > version);
    // Verify the update
    TableMetadata read = client.readTable(table.id());
    assertEquals(dsSpec2, read.spec());
    // Move a column
    MoveColumn moveCmd = new MoveColumn("d", MoveColumn.Position.BEFORE, "a");
    client.editTable(table.id(), moveCmd);
    // Drop a column
    DropColumns dropCmd = new DropColumns(Collections.singletonList("b"));
    client.editTable(table.id(), dropCmd);
    read = client.readTable(table.id());
    assertEquals(Arrays.asList("d", "a", "c"), CatalogUtils.columnNames(read.spec().columns()));
    // Hide columns
    HideColumns hideCmd = new HideColumns(Arrays.asList("e", "f"));
    client.editTable(table.id(), hideCmd);
    read = client.readTable(table.id());
    assertEquals(Arrays.asList("e", "f"), read.spec().properties().get(DatasourceDefn.HIDDEN_COLUMNS_PROPERTY));
    // Unhide
    UnhideColumns unhideCmd = new UnhideColumns(Collections.singletonList("e"));
    client.editTable(table.id(), unhideCmd);
    read = client.readTable(table.id());
    assertEquals(Collections.singletonList("f"), read.spec().properties().get(DatasourceDefn.HIDDEN_COLUMNS_PROPERTY));
    // List schemas
    List<String> schemaNames = client.listSchemas();
    assertTrue(schemaNames.contains(TableId.DRUID_SCHEMA));
    assertTrue(schemaNames.contains(TableId.EXTERNAL_SCHEMA));
    assertTrue(schemaNames.contains(TableId.SYSTEM_SCHEMA));
    assertTrue(schemaNames.contains(TableId.CATALOG_SCHEMA));
    // List table names in schema
    List<String> tableNames = client.listTableNamesInSchema(TableId.DRUID_SCHEMA);
    assertTrue(tableNames.contains(table.id().name()));
    // List tables
    List<TableId> tables = client.listTables();
    assertTrue(tables.contains(table.id()));
    // Drop the table
    client.dropTable(table.id());
    tableNames = client.listTableNamesInSchema(TableId.DRUID_SCHEMA);
    assertFalse(tableNames.contains(table.id().name()));
}

@Test
public void testYaml() {
    ClusterConfig config = ClusterConfig.loadFromResource("/config-test/test.yaml");
    // Uncomment this line to see the full config with includes resolved.
    //System.out.println(config.resolveIncludes());
    ResolvedConfig resolved = config.resolve("Test");
    assertEquals(ClusterType.docker, resolved.type());
    assertEquals(ResolvedConfig.DEFAULT_READY_TIMEOUT_SEC, resolved.readyTimeoutSec());
    assertEquals(ResolvedConfig.DEFAULT_READY_POLL_MS, resolved.readyPollMs());
    assertEquals(3, resolved.properties().size());
    ResolvedZk zk = resolved.zk();
    assertNotNull(zk);
    assertEquals("zookeeper", zk.service());
    assertEquals(1, zk.requireInstances().size());
    assertEquals(2181, zk.instance().port());
    assertEquals(2181, zk.instance().clientPort());
    assertEquals("zookeeper", zk.instance().host());
    assertEquals("localhost", zk.instance().clientHost());
    assertEquals("zookeeper:2181", zk.clusterHosts());
    assertEquals("localhost:2181", zk.clientHosts());
