@Test
public void testExport() throws Exception {
    String exportQuery = StringUtils.format("INSERT INTO extern(%s(exportPath => '%s'))\n" + "AS CSV\n" + "SELECT page, added, delta\n" + "FROM TABLE(\n" + "  EXTERN(\n" + "    '{\"type\":\"local\",\"files\":[\"/resources/data/batch_index/json/wikipedia_index_data1.json\"]}',\n" + "    '{\"type\":\"json\"}',\n" + "    '[{\"type\":\"string\",\"name\":\"timestamp\"},{\"type\":\"string\",\"name\":\"isRobot\"},{\"type\":\"string\",\"name\":\"diffUrl\"},{\"type\":\"long\",\"name\":\"added\"},{\"type\":\"string\",\"name\":\"countryIsoCode\"},{\"type\":\"string\",\"name\":\"regionName\"},{\"type\":\"string\",\"name\":\"channel\"},{\"type\":\"string\",\"name\":\"flags\"},{\"type\":\"long\",\"name\":\"delta\"},{\"type\":\"string\",\"name\":\"isUnpatrolled\"},{\"type\":\"string\",\"name\":\"isNew\"},{\"type\":\"double\",\"name\":\"deltaBucket\"},{\"type\":\"string\",\"name\":\"isMinor\"},{\"type\":\"string\",\"name\":\"isAnonymous\"},{\"type\":\"long\",\"name\":\"deleted\"},{\"type\":\"string\",\"name\":\"cityName\"},{\"type\":\"long\",\"name\":\"metroCode\"},{\"type\":\"string\",\"name\":\"namespace\"},{\"type\":\"string\",\"name\":\"comment\"},{\"type\":\"string\",\"name\":\"page\"},{\"type\":\"long\",\"name\":\"commentLength\"},{\"type\":\"string\",\"name\":\"countryName\"},{\"type\":\"string\",\"name\":\"user\"},{\"type\":\"string\",\"name\":\"regionIsoCode\"}]'\n" + "  )\n" + ")\n", LocalFileExportStorageProvider.TYPE_NAME, "/shared/export/");
    SqlTaskStatus exportTask = msqHelper.submitMsqTaskSuccesfully(exportQuery);
    msqHelper.pollTaskIdForSuccess(exportTask.getTaskId());
    if (exportTask.getState().isFailure()) {
        Assert.fail(StringUtils.format("Unable to start the task successfully.\nPossible exception: %s", exportTask.getError()));
    }
    String resultQuery = StringUtils.format("SELECT page, delta, added\n" + "  FROM TABLE(\n" + "    EXTERN(\n" + "      '{\"type\":\"local\",\"baseDir\":\"/shared/export/\",\"filter\":\"*.csv\"}',\n" + "      '{\"type\":\"csv\",\"findColumnsFromHeader\":true}'\n" + "    )\n" + "  ) EXTEND (\"added\" BIGINT, \"delta\" BIGINT, \"page\" VARCHAR)\n" + "   WHERE delta != 0\n" + "   ORDER BY page");
    SqlTaskStatus resultTaskStatus = msqHelper.submitMsqTaskSuccesfully(resultQuery);
    msqHelper.pollTaskIdForSuccess(resultTaskStatus.getTaskId());
    TaskReport.ReportMap statusReport = msqHelper.fetchStatusReports(resultTaskStatus.getTaskId());
    MSQTaskReport taskReport = (MSQTaskReport) statusReport.get(MSQTaskReport.REPORT_KEY);
