    MSQTaskReportPayload taskReportPayload = Preconditions.checkNotNull(taskReport.getPayload(), "payload");
    MSQResultsReport resultsReport = Preconditions.checkNotNull(taskReportPayload.getResults(), "Results report for the task id is empty");
    List<List<Object>> actualResults = new ArrayList<>();
    for (final Object[] row : resultsReport.getResults()) {
        actualResults.add(Arrays.asList(row));
    }
    ImmutableList<ImmutableList<Object>> expectedResults = ImmutableList.of(ImmutableList.of("Cherno Alpha", 111, 123), ImmutableList.of("Gypsy Danger", -143, 57), ImmutableList.of("Striker Eureka", 330, 459));
