@Test
public void testUnionQuery() throws Exception {
    fullDatasourceName = UNION_DATASOURCE + config.getExtraDatasourceNameSuffix();
    final String baseName = fullDatasourceName + UUID.randomUUID();
    KafkaAdminClient streamAdminClient = new KafkaAdminClient(config);
    List<String> supervisors = new ArrayList<>();
    final int numDatasources = 3;
    for (int i = 0; i < numDatasources; i++) {
        String datasource = baseName + "-" + i;
        streamAdminClient.createStream(datasource, 1, Collections.emptyMap());
        ITRetryUtil.retryUntil(() -> streamAdminClient.isStreamActive(datasource), true, 10000, 30, "Wait for stream active");
        String supervisorSpec = generateStreamIngestionPropsTransform(datasource, datasource, config).apply(getResourceAsString(UNION_SUPERVISOR_TEMPLATE));
        LOG.info("supervisorSpec: [%s]\n", supervisorSpec);
        // Start supervisor
        String specResponse = indexer.submitSupervisor(supervisorSpec);
        LOG.info("Submitted supervisor [%s]", specResponse);
        supervisors.add(specResponse);
        int ctr = 0;
        try (StreamEventWriter streamEventWriter = new KafkaEventWriter(config, false);
            BufferedReader reader = new BufferedReader(new InputStreamReader(getResourceAsStream(UNION_DATA_FILE), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                streamEventWriter.write(datasource, StringUtils.toUtf8(line));
                ctr++;
            }
        }
        final int numWritten = ctr;
        LOG.info("Waiting for stream indexing tasks to consume events");
        ITRetryUtil.retryUntilTrue(() -> numWritten == this.queryHelper.countRows(datasource, Intervals.ETERNITY, name -> new LongSumAggregatorFactory(name, "count")), StringUtils.format("dataSource[%s] consumed [%,d] events, expected [%,d]", datasource, this.queryHelper.countRows(datasource, Intervals.ETERNITY, name -> new LongSumAggregatorFactory(name, "count")), numWritten));
    }
    String queryResponseTemplate = StringUtils.replace(getResourceAsString(UNION_QUERIES_RESOURCE), "%%DATASOURCE%%", baseName);
    queryHelper.testQueriesFromString(queryResponseTemplate);
    for (int i = 0; i < numDatasources; i++) {
        indexer.terminateSupervisor(supervisors.get(i));
        streamAdminClient.deleteStream(baseName + "-" + i);
    }
    for (int i = 0; i < numDatasources; i++) {
        final int datasourceNumber = i;
        ITRetryUtil.retryUntil(() -> coordinator.areSegmentsLoaded(baseName + "-" + datasourceNumber), true, 10000, 10, "Kafka segments loaded");
    }
    queryHelper.testQueriesFromString(queryResponseTemplate);
    for (int i = 0; i < numDatasources; i++) {
        final String datasource = baseName + "-" + i;
        List<String> intervals = coordinator.getSegmentIntervals(datasource);
        Collections.sort(intervals);
        String first = intervals.get(0).split("/")[0];
        String last = intervals.get(intervals.size() - 1).split("/")[1];
        Interval interval = Intervals.of(first + "/" + last);
        coordinator.unloadSegmentsForDataSource(baseName + "-" + i);
        ITRetryUtil.retryUntilFalse(() -> coordinator.areSegmentsLoaded(datasource), "Segment Unloading");
        coordinator.deleteSegmentsDataSource(baseName + "-" + i, interval);
    }
}

@Test
public void testEqualsAndHashCode() throws NoSuchMethodException {
    // Exclude test classes
    Set<URL> urls = ClasspathHelper.forPackage("org.apache.druid").stream().filter(url -> !url.toString().contains("/target/test-classes")).collect(Collectors.toSet());
    Reflections reflections = new Reflections(urls);
    Set<Class<?>> classes = reflections.getTypesAnnotatedWith(SubclassesMustOverrideEqualsAndHashCode.class);
    Set<String> failed = new HashSet<>();
    for (Class<?> clazz : classes) {
        if (clazz.isInterface() || Modifier.isAbstract(clazz.getModifiers())) {
            continue;
        }
        Method m = clazz.getMethod("hashCode");
        String className = clazz.getName();
        try {
            Assert.assertNotSame(className + " does not implment hashCode", Object.class, m.getDeclaringClass());
        } catch (AssertionError e) {
            failed.add(className);
        }
    }
    if (!failed.isEmpty()) {
        System.err.println("failed classes [" + failed.size() + "] : ");
        failed.forEach(c -> System.err.println("\t" + c));
        Assert.fail();
    }
}

