@Test
public void testCondenseIntervalsSimpleSortedIterator() {
    List<Interval> intervals = Arrays.asList(Intervals.of("2011-01-01/2011-01-02"), Intervals.of("2011-01-02/2011-01-03"), Intervals.of("2011-02-03/2011-02-08"), Intervals.of("2011-02-01/2011-02-02"), Intervals.of("2011-02-01/2011-02-05"), Intervals.of("2011-03-01/2011-03-02"), Intervals.of("2011-03-03/2011-03-04"), Intervals.of("2011-03-05/2011-03-06"));
    intervals.sort(Comparators.intervalsByStartThenEnd());
