    ResourceHolder<WritableMemory> memoryResourceHolder2 = memoryResourceHolderOptional2.get();
    WritableMemory memory2 = memoryResourceHolder2.get();
    for (int i = 0; i < ALLOCATOR_SIZE - 4; ++i) {
