    for (int i = 0; i < 4; ++i) {
        memory2.putByte(i, (byte) 0xFE);
    }
    // Readback to ensure that value hasn't been overwritten
    for (int i = 0; i < ALLOCATOR_SIZE - 4; ++i) {
        Assert.assertEquals((byte) 0xFF, memory1.getByte(i));
    }
    for (int i = 0; i < 4; ++i) {
