@Test
public void testWriteFullyThenRead() throws IOException {
    // Create a frame file.
    final IncrementalIndexStorageAdapter adapter = new IncrementalIndexStorageAdapter(TestIndex.getIncrementalTestIndex());
    final File file = FrameTestUtil.writeFrameFile(FrameSequenceBuilder.fromAdapter(adapter).maxRowsPerFrame(maxRowsPerFrame).frameType(frameType).frames(), temporaryFolder.newFile());
    final ReadableByteChunksFrameChannel channel = ReadableByteChunksFrameChannel.create("test", false);
    ListenableFuture<?> firstBackpressureFuture = null;
    long totalSize = 0;
    Assert.assertEquals(0, channel.getBytesBuffered());
    try (final Chunker chunker = new Chunker(new FileInputStream(file), chunkSize)) {
        byte[] chunk;
        while ((chunk = chunker.nextChunk()) != null) {
            totalSize += chunk.length;
            final ListenableFuture<?> backpressureFuture = channel.addChunk(chunk);
            Assert.assertEquals(channel.getBytesAdded(), totalSize);
            // Minimally-sized channel means backpressure is exerted as soon as a single frame is available.
            Assert.assertEquals(channel.canRead(), backpressureFuture != null);
            if (backpressureFuture != null) {
                if (firstBackpressureFuture == null) {
                    firstBackpressureFuture = backpressureFuture;
                } else {
                    Assert.assertSame(firstBackpressureFuture, backpressureFuture);
                }
            }
        }
        // Backpressure should be exerted right now, since this is a minimal channel with at least one full frame in it.
        Assert.assertNotNull(firstBackpressureFuture);
        Assert.assertFalse(firstBackpressureFuture.isDone());
        channel.doneWriting();
    }
    FrameTestUtil.assertRowsEqual(FrameTestUtil.readRowsFromAdapter(adapter, null, false), FrameTestUtil.readRowsFromFrameChannel(channel, FrameReader.create(adapter.getRowSignature())));
}

@Test
public void testWriteReadInterleaved() throws IOException {
    // Create a frame file.
    final IncrementalIndexStorageAdapter adapter = new IncrementalIndexStorageAdapter(TestIndex.getIncrementalTestIndex());
    final File file = FrameTestUtil.writeFrameFile(FrameSequenceBuilder.fromAdapter(adapter).maxRowsPerFrame(maxRowsPerFrame).frameType(frameType).frames(), temporaryFolder.newFile());
    final ReadableByteChunksFrameChannel channel = ReadableByteChunksFrameChannel.create("test", false);
    // Enough to hold all frames
    final BlockingQueueFrameChannel outChannel = new BlockingQueueFrameChannel(10_000);
    ListenableFuture<?> backpressureFuture = null;
    int iteration = 0;
    long totalSize = 0;
    try (final Chunker chunker = new Chunker(new FileInputStream(file), chunkSize)) {
        byte[] chunk;
        while ((chunk = chunker.nextChunk()) != null) {
            // Read one frame every 3 iterations. Read everything every 11 iterations. Otherwise, read nothing.
            if (iteration % 3 == 0) {
                while (channel.canRead()) {
                    outChannel.writable().write(channel.read());
                }
                // After reading everything, backpressure should be off.
                Assert.assertTrue(backpressureFuture == null || backpressureFuture.isDone());
            } else if (iteration % 11 == 0) {
                if (channel.canRead()) {
                    outChannel.writable().write(channel.read());
                }
            }
            if (backpressureFuture != null && backpressureFuture.isDone()) {
                backpressureFuture = null;
            }
            iteration++;
            totalSize += chunk.length;
            // Write next chunk.
            final ListenableFuture<?> addVal = channel.addChunk(chunk);
            Assert.assertEquals(totalSize, channel.getBytesAdded());
            // Minimally-sized channel means backpressure is exerted as soon as a single frame is available.
            Assert.assertEquals(channel.canRead(), addVal != null);
            if (addVal != null) {
                if (backpressureFuture == null) {
                    backpressureFuture = addVal;
                } else {
                    Assert.assertSame(backpressureFuture, addVal);
                }
            }
        }
        channel.doneWriting();
        // Get all the remaining frames.
        while (channel.canRead()) {
            outChannel.writable().write(channel.read());
        }
        outChannel.writable().close();
    }
    FrameTestUtil.assertRowsEqual(FrameTestUtil.readRowsFromAdapter(adapter, null, false), FrameTestUtil.readRowsFromFrameChannel(outChannel.readable(), FrameReader.create(adapter.getRowSignature())));
}

@Test
public void testChannel() throws Exception {
    final QueryableIndexStorageAdapter adapter = new QueryableIndexStorageAdapter(TestIndex.getMMappedTestIndex());
    final List<Frame> frames = FrameSequenceBuilder.fromAdapter(adapter).frameType(FrameType.ROW_BASED).maxRowsPerFrame(11).frames().toList();
    final List<ReadableFrameChannel> channels = new ArrayList<>();
    for (final Frame frame : frames) {
        final BlockingQueueFrameChannel channel = BlockingQueueFrameChannel.minimal();
        channel.writable().write(frame);
        channel.writable().close();
        channels.add(channel.readable());
        // Sprinkle in some empty channels too, to make sure they work.
        channels.add(ReadableNilFrameChannel.INSTANCE);
    }
    final ReadableConcatFrameChannel concatChannel = ReadableConcatFrameChannel.open(channels.iterator());
    FrameTestUtil.assertRowsEqual(FrameTestUtil.readRowsFromAdapter(adapter, null, false), FrameTestUtil.readRowsFromFrameChannel(concatChannel, FrameReader.create(adapter.getRowSignature())));
}

