@Test
public void testTruncatedFrameFile() throws IOException {
    final int allocatorSize = 64000;
    // Holds two full frames + one partial frame, after compression.
    final int truncatedSize = 30000;
    final IncrementalIndexStorageAdapter adapter = new IncrementalIndexStorageAdapter(TestIndex.getIncrementalTestIndex());
    final File file = FrameTestUtil.writeFrameFile(FrameSequenceBuilder.fromAdapter(adapter).allocator(ArenaMemoryAllocator.create(ByteBuffer.allocate(allocatorSize))).frameType(FrameType.ROW_BASED).frames(), temporaryFolder.newFile());
    final byte[] truncatedFile = new byte[truncatedSize];
    try (final FileInputStream in = new FileInputStream(file)) {
        ByteStreams.readFully(in, truncatedFile);
    }
    ReadableInputStreamFrameChannel readableInputStreamFrameChannel = ReadableInputStreamFrameChannel.open(new ByteArrayInputStream(truncatedFile), "readTruncatedFrameFile", executorService, false);
    expectedException.expect(ISE.class);
    expectedException.expectMessage("Incomplete or missing frame at end of stream");
    Assert.assertEquals(FrameTestUtil.readRowsFromFrameChannel(readableInputStreamFrameChannel, FrameReader.create(adapter.getRowSignature())).toList().size(), 0);
    Assert.assertTrue(readableInputStreamFrameChannel.isFinished());
    readableInputStreamFrameChannel.close();
}

