public void test_abort_afterAllFrames() throws IOException {
    final Sequence<Frame> frames = FrameSequenceBuilder.fromAdapter(new IncrementalIndexStorageAdapter(TestIndex.getIncrementalTestIndex())).allocator(ArenaMemoryAllocator.createOnHeap(1000000)).frameType(FrameType.ROW_BASED).frames();
    final File file = temporaryFolder.newFile();
    final FrameFileWriter fileWriter = FrameFileWriter.open(Files.newByteChannel(file.toPath(), StandardOpenOption.WRITE), null, ByteTracker.unboundedTracker());
    frames.forEach(frame -> {
        try {
            fileWriter.writeFrame(frame, FrameFileWriter.NO_PARTITION);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    });
    fileWriter.abort();
    final IllegalStateException e = Assert.assertThrows(IllegalStateException.class, () -> FrameFile.open(file, null));
