@Test
public void testRunLengthsWithMultipleColumns() {
    final List<KeyColumn> keyColumns = ImmutableList.of(new KeyColumn("longAsc1", KeyOrder.ASCENDING), new KeyColumn("stringAsc1", KeyOrder.ASCENDING), new KeyColumn("stringDesc1", KeyOrder.DESCENDING), new KeyColumn("longDesc1", KeyOrder.DESCENDING), new KeyColumn("complexDesc1", KeyOrder.DESCENDING), new KeyColumn("complexAsc1", KeyOrder.ASCENDING), new KeyColumn("complexAsc2", KeyOrder.ASCENDING), new KeyColumn("stringAsc2", KeyOrder.ASCENDING));
    final RowSignature signature = RowSignature.builder().add("longAsc1", ColumnType.LONG).add("stringAsc1", ColumnType.STRING).add("stringDesc1", ColumnType.STRING).add("longDesc1", ColumnType.LONG).add("complexDesc1", ColumnType.NESTED_DATA).add("complexAsc1", ColumnType.NESTED_DATA).add("complexAsc2", ColumnType.NESTED_DATA).add("stringAsc2", ColumnType.STRING).build();
    final RunLengthEntry[] runLengthEntries = RowKeyComparisonRunLengths.create(keyColumns, signature).getRunLengthEntries();
    // Input keyColumns
    // long ASC, string ASC, string DESC, long DESC, complex DESC, complex ASC, complex ASC, string ASC
    // Output runLengthEntries would be
    // (long, string ASC) (string, long DESC) (complex DESC) (complex ASC) (complex ASC) (string ASC)
    Assert.assertEquals(6, runLengthEntries.length);
    Assert.assertTrue(runLengthEntries[0].isByteComparable());
    Assert.assertEquals(2, runLengthEntries[0].getRunLength());
    Assert.assertEquals(KeyOrder.ASCENDING, runLengthEntries[0].getOrder());
    Assert.assertTrue(runLengthEntries[1].isByteComparable());
    Assert.assertEquals(2, runLengthEntries[1].getRunLength());
    Assert.assertEquals(KeyOrder.DESCENDING, runLengthEntries[1].getOrder());
    Assert.assertFalse(runLengthEntries[2].isByteComparable());
    Assert.assertEquals(1, runLengthEntries[2].getRunLength());
    Assert.assertEquals(KeyOrder.DESCENDING, runLengthEntries[2].getOrder());
    Assert.assertFalse(runLengthEntries[3].isByteComparable());
    Assert.assertEquals(1, runLengthEntries[3].getRunLength());
    Assert.assertEquals(KeyOrder.ASCENDING, runLengthEntries[3].getOrder());
    Assert.assertFalse(runLengthEntries[4].isByteComparable());
    Assert.assertEquals(1, runLengthEntries[4].getRunLength());
    Assert.assertEquals(KeyOrder.ASCENDING, runLengthEntries[4].getOrder());
    Assert.assertTrue(runLengthEntries[5].isByteComparable());
    Assert.assertEquals(1, runLengthEntries[5].getRunLength());
    Assert.assertEquals(KeyOrder.ASCENDING, runLengthEntries[5].getOrder());
}

/**
 * This tests the creation of the run lengths with all the permutations of the key columns from the following space:
 * a. The KeyColumn can be either String or Complex (string is byte-comparable, nested data is not)
 * b. The KeyColumn can be either ASC or DESC
 *
 * Therefore, each key column can be one of (string ASC, string DESC, complex ASC, complex DESC). There are 64 test
 * case for all the permutations of the key columns, because there are 3 key columns, each of which can take one of
 * the 4 different configurations..
 *
 * Test cases are generated programatically. For index i from [0..64), we build the base-4 representation of the index,
 * and each digit in the representation corresponds to one of the key columns.
 */
@Test
public void testRunLengthsWithAllPermutationsOfThreeLengthKeyColumns() {
    ImmutableList.Builder<RunLengthEntry[]> expectedResultsBuilder = ImmutableList.builder();
    // index = 0; KeyColumns = STRING ASC, STRING ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(true, KeyOrder.ASCENDING, 3) });
    // index = 1; KeyColumns = STRING DESC, STRING ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(true, KeyOrder.DESCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 2) });
    // index = 2; KeyColumns = COMPLEX ASC, STRING ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(false, KeyOrder.ASCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 2) });
    // index = 3; KeyColumns = COMPLEX DESC, STRING ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(false, KeyOrder.DESCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 2) });
    // index = 4; KeyColumns = STRING ASC, STRING DESC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(true, KeyOrder.ASCENDING, 1), new RunLengthEntry(true, KeyOrder.DESCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 5; KeyColumns = STRING DESC, STRING DESC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(true, KeyOrder.DESCENDING, 2), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 6; KeyColumns = COMPLEX ASC, STRING DESC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(false, KeyOrder.ASCENDING, 1), new RunLengthEntry(true, KeyOrder.DESCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 7; KeyColumns = COMPLEX DESC, STRING DESC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(false, KeyOrder.DESCENDING, 1), new RunLengthEntry(true, KeyOrder.DESCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 8; KeyColumns = STRING ASC, COMPLEX ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(true, KeyOrder.ASCENDING, 1), new RunLengthEntry(false, KeyOrder.ASCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 9; KeyColumns = STRING DESC, COMPLEX ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(true, KeyOrder.DESCENDING, 1), new RunLengthEntry(false, KeyOrder.ASCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 10; KeyColumns = COMPLEX ASC, COMPLEX ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(false, KeyOrder.ASCENDING, 1), new RunLengthEntry(false, KeyOrder.ASCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 11; KeyColumns = COMPLEX DESC, COMPLEX ASC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(false, KeyOrder.DESCENDING, 1), new RunLengthEntry(false, KeyOrder.ASCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 12; KeyColumns = STRING ASC, COMPLEX DESC, STRING ASC
    expectedResultsBuilder.add(new RunLengthEntry[] { new RunLengthEntry(true, KeyOrder.ASCENDING, 1), new RunLengthEntry(false, KeyOrder.DESCENDING, 1), new RunLengthEntry(true, KeyOrder.ASCENDING, 1) });
    // index = 13; KeyColumns = STRING DESC, COMPLEX DESC, STRING ASC
