@Test
public void testEqualsAndHashCode() {
    // Can't use EqualsVerifier because it requires that cached hashcodes be computed in the constructor.
    final RowSignature signatureLong = RowSignature.builder().add("1", ColumnType.LONG).build();
    final RowSignature signatureLongString = RowSignature.builder().add("1", ColumnType.LONG).add("2", ColumnType.STRING).build();
    //noinspection AssertBetweenInconvertibleTypes: testing this case on purpose
    Assert.assertNotEquals("not a key", KeyTestUtils.createKey(signatureLong, 1L));
    Assert.assertEquals(KeyTestUtils.createKey(signatureLong, 1L), KeyTestUtils.createKey(signatureLong, 1L));
    Assert.assertEquals(KeyTestUtils.createKey(RowSignature.empty()), KeyTestUtils.createKey(RowSignature.empty()));
    Assert.assertNotEquals(KeyTestUtils.createKey(RowSignature.empty()), KeyTestUtils.createKey(signatureLong, 2L));
    Assert.assertNotEquals(KeyTestUtils.createKey(signatureLong, 1L), KeyTestUtils.createKey(signatureLong, 2L));
    Assert.assertEquals(KeyTestUtils.createKey(signatureLongString, 1L, "abc"), KeyTestUtils.createKey(signatureLongString, 1L, "abc"));
    Assert.assertNotEquals(KeyTestUtils.createKey(signatureLongString, 1L, "abc"), KeyTestUtils.createKey(signatureLongString, 1L, "def"));
    Assert.assertEquals(KeyTestUtils.createKey(signatureLong, 1L).hashCode(), KeyTestUtils.createKey(signatureLong, 1L).hashCode());
    Assert.assertNotEquals(KeyTestUtils.createKey(signatureLong, 1L).hashCode(), KeyTestUtils.createKey(signatureLong, 2L).hashCode());
    Assert.assertEquals(KeyTestUtils.createKey(signatureLongString, 1L, "abc").hashCode(), KeyTestUtils.createKey(signatureLongString, 1L, "abc").hashCode());
    Assert.assertNotEquals(KeyTestUtils.createKey(signatureLongString, 1L, "abc").hashCode(), KeyTestUtils.createKey(signatureLongString, 1L, "def").hashCode());
}

