public void test_runFully() throws Exception {
    // 3 input files blasted to 2 outputs (2 copies of the data), then muxed to one file.
    final IncrementalIndexStorageAdapter adapter = new IncrementalIndexStorageAdapter(TestIndex.getIncrementalTestIndex());
    final List<File> inFiles = writeToNFiles(adapter, 3);
    final File outFile = temporaryFolder.newFile();
    final BlockingQueueFrameChannel memoryChannel1 = BlockingQueueFrameChannel.minimal();
    final BlockingQueueFrameChannel memoryChannel2 = BlockingQueueFrameChannel.minimal();
    final SuperBlasterFrameProcessor blaster = new SuperBlasterFrameProcessor(inFiles.stream().map(FrameProcessorExecutorTest::openFileChannel).collect(Collectors.toList()), ImmutableList.of(memoryChannel1.writable(), memoryChannel2.writable()), awaitStyle);
    final FrameChannelMixer muxer = new FrameChannelMixer(ImmutableList.of(memoryChannel1.readable(), memoryChannel2.readable()), new WritableFrameFileChannel(FrameFileWriter.open(Channels.newChannel(Files.newOutputStream(outFile.toPath())), null, ByteTracker.unboundedTracker())));
    final ListenableFuture<Long> blasterFuture = exec.runFully(blaster, null);
    final ListenableFuture<Long> muxerFuture = exec.runFully(muxer, null);
    Assert.assertEquals(adapter.getNumRows(), (long) blasterFuture.get());
    Assert.assertEquals(adapter.getNumRows() * 2, (long) muxerFuture.get());
    Assert.assertEquals(adapter.getNumRows() * 2, FrameTestUtil.readRowsFromFrameChannel(new ReadableFileFrameChannel(FrameFile.open(outFile, null)), FrameReader.create(adapter.getRowSignature())).toList().size());
