    final AtomicLong closed = new AtomicLong();
    try (final SequenceProcessorManager<Unit, FrameProcessor<Unit>> manager = new SequenceProcessorManager<>(Sequences.<FrameProcessor<Unit>>simple(Collections.singleton(processor)).withBaggage(closed::getAndIncrement))) {
        // First element.
        ListenableFuture<Optional<ProcessorAndCallback<Unit>>> future = manager.next();
        Assert.assertTrue(future.isDone());
        Assert.assertTrue(future.get().isPresent());
        Assert.assertSame(processor, future.get().get().processor());
        // End of sequence.
        future = manager.next();
        Assert.assertTrue(future.isDone());
        Assert.assertFalse(future.get().isPresent());
    }
    Assert.assertEquals(1, closed.get());
}

@Test
public void test_two() throws Exception {
    final NilFrameProcessor processor0 = new NilFrameProcessor();
    final NilFrameProcessor processor1 = new NilFrameProcessor();
    final AtomicLong closed = new AtomicLong();
    try (final SequenceProcessorManager<Unit, FrameProcessor<Unit>> manager = new SequenceProcessorManager<>(Sequences.<FrameProcessor<Unit>>simple(ImmutableList.of(processor0, processor1)).withBaggage(closed::getAndIncrement))) {
        // First element.
        ListenableFuture<Optional<ProcessorAndCallback<Unit>>> future = manager.next();
        Assert.assertTrue(future.isDone());
        Assert.assertTrue(future.get().isPresent());
        Assert.assertSame(processor0, future.get().get().processor());
        // Second element.
        future = manager.next();
        Assert.assertTrue(future.isDone());
        Assert.assertTrue(future.get().isPresent());
        Assert.assertSame(processor1, future.get().get().processor());
        // End of sequence.
        future = manager.next();
        Assert.assertTrue(future.isDone());
        Assert.assertFalse(future.get().isPresent());
        // One more, should throw because there's nothing left.
        Assert.assertThrows(NoSuchElementException.class, manager::next);
    }
    Assert.assertEquals(1, closed.get());
}

@Test
public void test_empty_closeThenNext() {
    final AtomicLong closed = new AtomicLong();
    final SequenceProcessorManager<Object, FrameProcessor<Object>> manager = new SequenceProcessorManager<>(Sequences.<FrameProcessor<Object>>empty().withBaggage(closed::getAndIncrement));
    manager.close();
    // IllegalStateException instead of NoSuchElementException because the problem is that we are closed.
    Assert.assertThrows(IllegalStateException.class, manager::next);
    // Sequence is not closed because it never started iterating.
    Assert.assertEquals(0, closed.get());
}

