@Test
public void testEmptiesAndNonEmpty() throws IOException {
    // below min threshold, so will merge serially
    List<Sequence<IntPair>> input = new ArrayList<>();
    input.add(Sequences.empty());
    input.add(nonBlockingSequence(5));
