@Test
public void testFindOverlappingInterval() {
    final Interval[] sortedIntervals = new Interval[] { Intervals.of("2019/2020"), Intervals.of("2021/2022"), Intervals.of("2021-04-01/2021-05-01"), Intervals.of("2022/2023") };
    Arrays.sort(sortedIntervals, Comparators.intervalsByStartThenEnd());
    // Search interval outside the bounds of the sorted intervals
    Assert.assertNull(Intervals.findOverlappingInterval(Intervals.of("2018/2019"), sortedIntervals));
    Assert.assertNull(Intervals.findOverlappingInterval(Intervals.of("2023/2024"), sortedIntervals));
    // Search interval within bounds, overlap exists
    // Fully overlapping interval
    Assert.assertEquals(Intervals.of("2021/2022"), Intervals.findOverlappingInterval(Intervals.of("2021/2022"), sortedIntervals));
    // Partially overlapping interval
    Assert.assertEquals(Intervals.of("2022/2023"), Intervals.findOverlappingInterval(Intervals.of("2022-01-01/2022-01-02"), sortedIntervals));
    Assert.assertEquals(Intervals.of("2021/2022"), Intervals.findOverlappingInterval(Intervals.of("2021-06-01/2021-07-01"), sortedIntervals));
    // Overlap with multiple intervals, "smallest" one is returned
    Assert.assertEquals(Intervals.of("2021/2022"), Intervals.findOverlappingInterval(Intervals.of("2021-03-01/2021-04-01"), sortedIntervals));
    // Search interval within bounds, no overlap
    Assert.assertNull(Intervals.findOverlappingInterval(Intervals.of("2020-01-02/2020-03-03"), sortedIntervals));
}

