    final Iterator<Integer> expected = IntStream.range(0, numIterations).flatMap(i -> IntStream.range(0, i)).iterator();
    // burn through the first few iterators
    int cnt = 0;
    int numFlatIterations = 5;
    while (expected.hasNext() && actual.hasNext() && cnt++ < numFlatIterations) {
        Assert.assertEquals(expected.next(), actual.next());
    }
    // but stop while we still have an open current inner iterator and a few remaining inner iterators
    Assert.assertTrue(actual.hasNext());
    Assert.assertTrue(expected.hasNext());
    Assert.assertEquals(4, innerIterators.size());
    Assert.assertTrue(innerIterators.get(innerIterators.size() - 1).hasNext());
    actual.close();
    Assert.assertEquals(1, actual.closeCount);
    for (CloseTrackingCloseableIterator iter : innerIterators) {
        Assert.assertEquals(1, iter.closeCount);
    }
}

@Test
public void testFlatMapInnerClose() throws IOException {
    List<CloseTrackingCloseableIterator<Integer>> innerIterators = new ArrayList<>();
    // the nested iterators is : [ [], [0], [0, 1] ]
    try (final CloseTrackingCloseableIterator<Integer> actual = new CloseTrackingCloseableIterator<>(generateTestIterator(3).flatMap(list -> {
        CloseTrackingCloseableIterator<Integer> inner = new CloseTrackingCloseableIterator<>(CloseableIterators.withEmptyBaggage(list.iterator()));
        innerIterators.add(inner);
        return inner;
    }))) {
        final Iterator<Integer> expected = IntStream.range(0, 3).flatMap(i -> IntStream.range(0, i)).iterator();
        int iterCount = 0, innerIteratorIdx = 0;
        while (actual.hasNext()) {
            iterCount++;
            if (iterCount == 1) {
                //empty iterator and single element iterator
                Assert.assertEquals(2, innerIterators.size());
                innerIteratorIdx++;
            } else if (iterCount == 2) {
                //empty iterator + single element iterator + double element iterator
                Assert.assertEquals(3, innerIterators.size());
                innerIteratorIdx++;
            }
            // assert expected value to the iterator's value
            Assert.assertEquals(expected.next(), actual.next());
            for (int i = 0; i < innerIteratorIdx; i++) {
                // expect all previous iterators to be closed
                Assert.assertEquals(1, innerIterators.get(i).closeCount);
            }
            // never expect the current iterator to be closed, even after doing the last next call on it
            Assert.assertEquals(0, innerIterators.get(innerIteratorIdx).closeCount);
        }
    }
    // check the last inner iterator is closed
    Assert.assertEquals(1, innerIterators.get(2).closeCount);
}

