    Map<String, Object> theMap = ImmutableMap.<String, Object>builder().put("bool", true).put("int", 1).put("long", 1L).put("float", 0.11f).put("double", 0.33).put("binary", new byte[] { 0x01, 0x02, 0x03 }).put("list", ImmutableList.of("foo", "bar", "baz")).put("anotherList", intArray).build();
    Map<String, Object> expectedMap = ImmutableMap.<String, Object>builder().put("bool", true).put("int", 1L).put("long", 1L).put("float", 0.11).put("double", 0.33).put("binary", StringUtils.encodeBase64String(new byte[] { 0x01, 0x02, 0x03 })).put("list", ImmutableList.of("foo", "bar", "baz")).put("anotherList", expectedIntArray).build();
    node = OBJECT_MAPPER.readTree(OBJECT_MAPPER.writeValueAsString(theMap));
    Assert.assertTrue(node.isObject());
    result = FLATTENER_MAKER.finalizeConversionForMap(node);
    Assert.assertEquals(expectedMap, result);
    List<?> theList = ImmutableList.of(theMap, theMap);
    List<?> expectedList = ImmutableList.of(expectedMap, expectedMap);
    node = OBJECT_MAPPER.readTree(OBJECT_MAPPER.writeValueAsString(theList));
    Assert.assertTrue(node.isArray());
    result = FLATTENER_MAKER.finalizeConversionForMap(node);
    Assert.assertEquals(expectedList, result);
}

