    Assert.assertEquals(0.8165, (double) jsonMap.get("met-array-stddev"), 0.00001);
    Assert.assertEquals(ImmutableList.of(7L, 8L, 9L, 10L), jsonMap.get("met-array-append"));
    Assert.assertEquals("aaabbb", jsonMap.get("concat"));
}

