        Assert.assertEquals(contents(AlertBuilder.create(desc).severity(severity).addData("a", "1").addData("b", "2").build(service, host)), contents(new AlertEvent(service, host, severity, desc, data)));
        Assert.assertEquals(contents(AlertBuilder.create(desc).severity(severity).addData(data).build(service, host)), contents(new AlertEvent(service, host, severity, desc, data)));
