    pool = new ResourcePool<String, String>(resourceFactory, new ResourcePoolConfig(2, TimeUnit.MILLISECONDS.toMillis(10)), true);
    EasyMock.expect(resourceFactory.generate("billy")).andAnswer(new StringIncrementingAnswer("billy")).times(2);
