    Assert.assertArrayEquals(new Object[] { 1L, 2L, 3L }, (Object[]) eval.value());
    eval = ExprEval.ofType(ExpressionType.LONG_ARRAY, new Long[] { 1L, 2L, 3L });
    Assert.assertEquals(ExpressionType.LONG_ARRAY, eval.type());
    Assert.assertArrayEquals(new Object[] { 1L, 2L, 3L }, (Object[]) eval.value());
