    // nested arrays
    ExpressionType nestedLongArray = ExpressionTypeFactory.getInstance().ofArray(ExpressionType.LONG_ARRAY);
    final Object[] expectedLongArray = new Object[] { new Object[] { 1L, 2L, 3L }, new Object[] { 5L, null, 9L }, null, new Object[] { 2L, 4L, 6L } };
