    List<List<Map<String, Object>>> nestedListsComplex = ImmutableList.of(ImmutableList.of(nested1, nested2), ImmutableList.of(nested3, nested4));
    coerced = ExprEval.coerceListToArray(nestedListsComplex, false);
    Assert.assertEquals(ExpressionTypeFactory.getInstance().ofArray(ExpressionTypeFactory.getInstance().ofArray(ExpressionType.NESTED_DATA)), coerced.lhs);
    Assert.assertArrayEquals(new Object[] { new Object[] { nested1, nested2 }, new Object[] { nested3, nested4 } }, coerced.rhs);
    List<List<Object>> mixed = ImmutableList.of(ImmutableList.of("a", "b", "c"), ImmutableList.of(1L, 2L, 3L), ImmutableList.of(3.0, 4.0, 5.0), ImmutableList.of("a", 2L, 3.0));
