    Assert.assertArrayEquals(new Object[] { new Object[] { "a", "b", "c" }, new Object[] { "1", "2", "3" }, new Object[] { "3.0", "4.0", "5.0" }, new Object[] { "a", "2", "3.0" } }, coerced.rhs);
    List<List<Object>> mixedNested = ImmutableList.of(ImmutableList.of("a", "b", "c"), ImmutableList.of(1L, 2L, 3L), ImmutableList.of(3.0, 4.0, 5.0), ImmutableList.of("a", 2L, 3.0, nested1));
    coerced = ExprEval.coerceListToArray(mixedNested, false);
    Assert.assertEquals(ExpressionTypeFactory.getInstance().ofArray(ExpressionTypeFactory.getInstance().ofArray(ExpressionType.NESTED_DATA)), coerced.lhs);
    Assert.assertArrayEquals(new Object[] { new Object[] { "a", "b", "c" }, new Object[] { 1L, 2L, 3L }, new Object[] { 3.0, 4.0, 5.0 }, new Object[] { "a", 2L, 3.0, nested1 } }, coerced.rhs);
    List<Object> mixedNested2 = ImmutableList.of("a", 1L, 3.0, ImmutableList.of("a", "b", "c"), ImmutableList.of(1L, 2L, 3L), ImmutableList.of(3.0, 4.0, 5.0), ImmutableList.of(nested1, nested2, nested3));
    coerced = ExprEval.coerceListToArray(mixedNested2, false);
    Assert.assertEquals(ExpressionTypeFactory.getInstance().ofArray(ExpressionTypeFactory.getInstance().ofArray(ExpressionType.NESTED_DATA)), coerced.lhs);
    Assert.assertArrayEquals(new Object[] { new Object[] { "a" }, new Object[] { 1L }, new Object[] { 3.0 }, new Object[] { "a", "b", "c" }, new Object[] { 1L, 2L, 3L }, new Object[] { 3.0, 4.0, 5.0 }, new Object[] { nested1, nested2, nested3 } }, coerced.rhs);
    List<Object> mixedNested3 = ImmutableList.of("a", 1L, 3.0, nested1, ImmutableList.of("a", "b", "c"), ImmutableList.of(1L, 2L, 3L), ImmutableList.of(3.0, 4.0, 5.0), ImmutableList.of(nested1, nested2, nested3));
    coerced = ExprEval.coerceListToArray(mixedNested3, false);
    // this one is only ARRAY<COMPLEX<json>> instead of ARRAY<ARRAY<COMPLEX<json>> because of a COMPLEX<json> element..
    Assert.assertEquals(ExpressionTypeFactory.getInstance().ofArray(ExpressionType.NESTED_DATA), coerced.lhs);
    Assert.assertArrayEquals(new Object[] { "a", 1L, 3.0, nested1, new Object[] { "a", "b", "c" }, new Object[] { 1L, 2L, 3L }, new Object[] { 3.0, 4.0, 5.0 }, new Object[] { nested1, nested2, nested3 } }, coerced.rhs);
    List<List<Object>> mixedUnknown = ImmutableList.of(ImmutableList.of("a", "b", "c"), ImmutableList.of(1L, 2L, 3L), ImmutableList.of(3.0, 4.0, 5.0, new SerializablePair<>("hello", 1234L)), ImmutableList.of("a", 2L, 3.0, nested1));
    Throwable t = Assert.assertThrows(Types.IncompatibleTypeException.class, () -> ExprEval.coerceListToArray(mixedUnknown, false));
    Assert.assertEquals("Cannot implicitly cast [DOUBLE] to [COMPLEX]", t.getMessage());
}

