public void testApplyFunctions() {
    validateParser("map((x) -> 1, x)", "(map ([x] -> 1), [x])", ImmutableList.of("x"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("map((x) -> x + 1, x)", "(map ([x] -> (+ x 1)), [x])", ImmutableList.of("x"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("x + map((x) -> x + 1, y)", "(+ x (map ([x] -> (+ x 1)), [y]))", ImmutableList.of("x", "y"), ImmutableSet.of("x"), ImmutableSet.of("y"));
    validateParser("x + map((x) -> x + 1, x)", "(+ x (map ([x] -> (+ x 1)), [x]))", ImmutableList.of("x"), ImmutableSet.of("x"), ImmutableSet.of("x_0"));
    validateParser("map((x) -> concat(x, y), z)", "(map ([x] -> (concat [x, y])), [z])", ImmutableList.of("y", "z"), ImmutableSet.of("y"), ImmutableSet.of("z"));
    // 'y' is accumulator, and currently unknown
    validateParser("fold((x, acc) -> acc + x, x, y)", "(fold ([x, acc] -> (+ acc x)), [x, y])", ImmutableList.of("x", "y"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("fold((x, acc) -> acc + x, map((x) -> x + 1, x), y)", "(fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])", ImmutableList.of("x", "y"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("array_append(z, fold((x, acc) -> acc + x, map((x) -> x + 1, x), y))", "(array_append [z, (fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])])", ImmutableList.of("x", "y", "z"), ImmutableSet.of(), ImmutableSet.of("x", "z"));
    validateParser("map(z -> z + 1, array_append(z, fold((x, acc) -> acc + x, map((x) -> x + 1, x), y)))", "(map ([z] -> (+ z 1)), [(array_append [z, (fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])])])", ImmutableList.of("x", "y", "z"), ImmutableSet.of(), ImmutableSet.of("x", "z"));
    validateParser("array_append(map(z -> z + 1, array_append(z, fold((x, acc) -> acc + x, map((x) -> x + 1, x), y))), a)", "(array_append [(map ([z] -> (+ z 1)), [(array_append [z, (fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])])]), a])", ImmutableList.of("x", "y", "a", "z"), ImmutableSet.of("a"), ImmutableSet.of("x", "z"));
    validateFlatten("map((x) -> x + 1, [1, 2, 3, 4])", "(map ([x] -> (+ x 1)), [[1, 2, 3, 4]])", "[2, 3, 4, 5]");
    validateFlatten("map((x) -> x + z, [1, 2, 3, 4])", "(map ([x] -> (+ x z)), [[1, 2, 3, 4]])", "(map ([x] -> (+ x z)), [[1, 2, 3, 4]])");
}

@Test
public void testApplyUnapplied() {
    validateApplyUnapplied("x + 1", "(+ x 1)", "(+ x 1)", ImmutableList.of());
    validateApplyUnapplied("x + 1", "(+ x 1)", "(+ x 1)", ImmutableList.of("z"));
    validateApplyUnapplied("x + y", "(+ x y)", "(map ([x] -> (+ x y)), [x])", ImmutableList.of("x"));
    validateApplyUnapplied("x + y", "(+ x y)", "(cartesian_map ([x, y] -> (+ x y)), [x, y])", ImmutableList.of("x", "y"));
    validateApplyUnapplied("map(x -> x + y, x)", "(map ([x] -> (+ x y)), [x])", "(cartesian_map ([x, y] -> (+ x y)), [x, y])", ImmutableList.of("y"));
    validateApplyUnapplied("map(x -> x + 1, x + 1)", "(map ([x] -> (+ x 1)), [(+ x 1)])", "(map ([x] -> (+ x 1)), [(map ([x] -> (+ x 1)), [x])])", ImmutableList.of("x"));
    validateApplyUnapplied("fold((x, acc) -> acc + x + y, x, 0)", "(fold ([x, acc] -> (+ (+ acc x) y)), [x, 0])", "(cartesian_fold ([x, y, acc] -> (+ (+ acc x) y)), [x, y, 0])", ImmutableList.of("y"));
    validateApplyUnapplied("z + fold((x, acc) -> acc + x + y, x, 0)", "(+ z (fold ([x, acc] -> (+ (+ acc x) y)), [x, 0]))", "(+ z (cartesian_fold ([x, y, acc] -> (+ (+ acc x) y)), [x, y, 0]))", ImmutableList.of("y"));
    validateApplyUnapplied("z + fold((x, acc) -> acc + x + y, x, 0)", "(+ z (fold ([x, acc] -> (+ (+ acc x) y)), [x, 0]))", "(map ([z] -> (+ z (cartesian_fold ([x, y, acc] -> (+ (+ acc x) y)), [x, y, 0]))), [z])", ImmutableList.of("y", "z"));
    validateApplyUnapplied("array_to_string(concat(x, 'hello'), ',')", "(array_to_string [(concat [x, hello]), ,])", "(array_to_string [(map ([x] -> (concat [x, hello])), [x]), ,])", ImmutableList.of("x", "y"));
    validateApplyUnapplied("cast(x, 'LONG')", "(cast [x, LONG])", "(map ([x] -> (cast [x, LONG])), [x])", ImmutableList.of("x"));
    validateApplyUnapplied("cartesian_map((x,y) -> x + y, x, y)", "(cartesian_map ([x, y] -> (+ x y)), [x, y])", "(cartesian_map ([x, y] -> (+ x y)), [x, y])", ImmutableList.of("y"));
    validateApplyUnapplied("cast(x, 'LONG_ARRAY')", "(cast [x, LONG_ARRAY])", "(cast [x, LONG_ARRAY])", ImmutableList.of("x"));
    validateApplyUnapplied("case_searched((x == 'b'),'b',(x == 'g'),'g','Other')", "(case_searched [(== x b), b, (== x g), g, Other])", "(map ([x] -> (case_searched [(== x b), b, (== x g), g, Other])), [x])", ImmutableList.of("x"));
    validateApplyUnapplied("array_overlap(nvl(x, 'other'), ['a', 'b', 'other'])", "(array_overlap [(nvl [x, other]), [a, b, other]])", "(array_overlap [(map ([x] -> (nvl [x, other])), [x]), [a, b, other]])", ImmutableList.of("x"));
}

@Test
public void testFoldUnapplied() {
    validateFoldUnapplied("x + __acc", "(+ x __acc)", "(+ x __acc)", ImmutableList.of(), "__acc");
    validateFoldUnapplied("x + __acc", "(+ x __acc)", "(+ x __acc)", ImmutableList.of("z"), "__acc");
    validateFoldUnapplied("x + __acc", "(+ x __acc)", "(fold ([x, __acc] -> (+ x __acc)), [x, __acc])", ImmutableList.of("x"), "__acc");
    validateFoldUnapplied("x + y + __acc", "(+ (+ x y) __acc)", "(cartesian_fold ([x, y, __acc] -> (+ (+ x y) __acc)), [x, y, __acc])", ImmutableList.of("x", "y"), "__acc");
    validateFoldUnapplied("__acc + z + fold((x, acc) -> acc + x + y, x, 0)", "(+ (+ __acc z) (fold ([x, acc] -> (+ (+ acc x) y)), [x, 0]))", "(fold ([z, __acc] -> (+ (+ __acc z) (fold ([x, acc] -> (+ (+ acc x) y)), [x, 0]))), [z, __acc])", ImmutableList.of("z"), "__acc");
    validateFoldUnapplied("__acc + z + fold((x, acc) -> acc + x + y, x, 0)", "(+ (+ __acc z) (fold ([x, acc] -> (+ (+ acc x) y)), [x, 0]))", "(fold ([z, __acc] -> (+ (+ __acc z) (cartesian_fold ([x, y, acc] -> (+ (+ acc x) y)), [x, y, 0]))), [z, __acc])", ImmutableList.of("y", "z"), "__acc");
    validateFoldUnapplied("__acc + fold((x, acc) -> x + y + acc, x, __acc)", "(+ __acc (fold ([x, acc] -> (+ (+ x y) acc)), [x, __acc]))", "(+ __acc (cartesian_fold ([x, y, acc] -> (+ (+ x y) acc)), [x, y, __acc]))", ImmutableList.of("y"), "__acc");
}

