@Test
public void test_case_long_double() {
    final FallbackVectorProcessor<Object[]> processor = FallbackVectorProcessor.create(new Function.CaseSimpleFunc(), ImmutableList.of(Parser.parse("long + double", ExprMacroTable.nil()), Parser.parse("102.1", ExprMacroTable.nil()), Parser.parse("long", ExprMacroTable.nil()), Parser.parse("double", ExprMacroTable.nil())), binding);
    final ExprEvalVector<Object[]> eval = processor.evalVector(binding);
    Assert.assertEquals(ExpressionType.DOUBLE, eval.getType());
    Assert.assertArrayEquals(new Object[] { 101.0, NullHandling.defaultDoubleValue(), 1.3 }, eval.getObjectVector());
    Assert.assertArrayEquals(new double[] { 101.0, 0L, 1.3 }, eval.getDoubleVector(), 0);
    Assert.assertArrayEquals(NullHandling.sqlCompatible() ? new boolean[] { false, true, false } : null, eval.getNullVector());
}

