@Test
public void test_array_length() {
    final FallbackVectorProcessor<Object[]> processor = FallbackVectorProcessor.create(new Function.ArrayLengthFunction(), ImmutableList.of(Parser.parse("arr", ExprMacroTable.nil())), binding);
    final ExprEvalVector<Object[]> eval = processor.evalVector(binding);
    Assert.assertEquals(ExpressionType.LONG, eval.getType());
    Assert.assertArrayEquals(new Object[] { 3L, null, 3L }, eval.getObjectVector());
    Assert.assertArrayEquals(new long[] { 3L, 0L, 3L }, eval.getLongVector());
    Assert.assertArrayEquals(new boolean[] { false, true, false }, eval.getNullVector());
}

@Test
public void test_array_concat() {
    final FallbackVectorProcessor<Object[]> processor = FallbackVectorProcessor.create(new Function.ArrayConcatFunction(), ImmutableList.of(Parser.parse("arr", ExprMacroTable.nil()), Parser.parse("long", ExprMacroTable.nil())), binding);
    final ExprEvalVector<Object[]> eval = processor.evalVector(binding);
    Assert.assertEquals(ExpressionType.LONG_ARRAY, eval.getType());
    Assert.assertArrayEquals(new Object[] { 201L, null, 203L, 101L }, (Object[]) eval.getObjectVector()[0]);
    Assert.assertNull(eval.getObjectVector()[1]);
    Assert.assertArrayEquals(new Object[] { 301L, null, 303L, 103L }, (Object[]) eval.getObjectVector()[2]);
}

