@Test
public void testNullString() {
    SerializablePairLongString value = new SerializablePairLongString(TIMESTAMP, null);
    // Write using the older serde, read using the newer serde
    Assert.assertEquals(new SerializablePairLongString(TIMESTAMP, null), readUsingSerde(writeUsingSerde(value, OLDER_INTEGER_SERDE), INTEGER_SERDE));
    Assert.assertEquals(new SerializablePairLongString(TIMESTAMP, null), readUsingSerde(writeUsingSerde(value, OLDER_LONG_SERDE), LONG_SERDE));
    // Write using the newer serde, read using the older serde
    Assert.assertEquals(new SerializablePairLongString(TIMESTAMP, null), readUsingSerde(writeUsingSerde(value, INTEGER_SERDE), OLDER_INTEGER_SERDE));
    Assert.assertEquals(new SerializablePairLongString(TIMESTAMP, null), readUsingSerde(writeUsingSerde(value, LONG_SERDE), OLDER_LONG_SERDE));
    // Compare the length of the serialized bytes for the value
    Assert.assertEquals(writeUsingSerde(value, OLDER_INTEGER_SERDE).length, writeUsingSerde(value, INTEGER_SERDE).length);
    Assert.assertEquals(writeUsingSerde(value, OLDER_LONG_SERDE).length, writeUsingSerde(value, LONG_SERDE).length);
}

