    RowSignature signature = RowSignature.builder().add("x", ColumnType.LONG).add("y", ColumnType.LONG).build();
    SettableObjectBinding binding = new SettableObjectBinding().withBinding("x", 2L).withBinding("y", 3L);
    SettableObjectBinding binding2 = new SettableObjectBinding().withBinding("x", 3L).withBinding("y", 4L);
