    Assert.assertArrayEquals(new Object[] { 2L, 3L }, (Object[]) postAgg.compute(binding.asMap()));
    Assert.assertArrayEquals(new Object[] { 3L, 4L }, (Object[]) postAgg.compute(binding2.asMap()));
