    Assert.assertEquals(expected, extracted);
    byte[] cacheKey = extractionFn.getCacheKey();
    byte[] expectedCacheKey = new byte[] { // expr
    0x01, // expr
    0x28, // expr
    0x61, // expr
    0x5C, // expr
    0x77, // expr
    0x2A, // expr
    0x29, // expr
    (byte) 0xFF, // index
    0x00, // index
    0x00, // index
    0x00, // index
    0x01, // replaceMissingValueWith
    0x66, // replaceMissingValueWith
    0x6F, // replaceMissingValueWith
    0x6F, // replaceMissingValueWith
    0x62, // replaceMissingValueWith
    0x61, // replaceMissingValueWith
    0x72, // replaceMissingValueWith
    (byte) 0xFF, // replaceMissingValue
    0x01 };
    Assert.assertArrayEquals(expectedCacheKey, cacheKey);
    ExtractionFn nullExtractionFn = new RegexDimExtractionFn(regex, true, null);
    Set<String> extracted2 = new LinkedHashSet<>();
    for (String testString : TEST_STRINGS) {
        extracted2.add(nullExtractionFn.apply(testString));
    }
    Set<String> expected2 = Sets.newLinkedHashSet(ImmutableList.of("apple", "awesome", "asylum"));
    expected2.add(null);
    Assert.assertEquals(expected2, extracted2);
    cacheKey = nullExtractionFn.getCacheKey();
    expectedCacheKey = new byte[] { // expr
    0x01, // expr
    0x28, // expr
    0x61, // expr
    0x5C, // expr
    0x77, // expr
    0x2A, // expr
    0x29, // expr
    (byte) 0xFF, // index
    0x00, // index
    0x00, // index
    0x00, // index
    0x01, // replaceMissingValueWith
    (byte) 0xFF, // replaceMissingValue
    0x01 };
    Assert.assertArrayEquals(expectedCacheKey, cacheKey);
}

