@Test
public void testOptimizeLookup_simple() {
    final Map<String, String> lookupMap = new HashMap<>();
    lookupMap.put("abc", "def");
    lookupMap.put("foo", "bar");
    final LookupExtractor lookup = ImmutableLookupMap.fromMap(lookupMap).asLookupExtractor(false, () -> new byte[0]);
    final LookupExtractionFn extractionFn = new LookupExtractionFn(lookup, false, null, null, true);
    Assert.assertEquals("reverse lookup bar", Sets.newHashSet("foo"), InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton("bar"), extractionFn), false));
    Assert.assertNull("reverse lookup bar (includeUnknown)", InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton("bar"), extractionFn), true));
    Assert.assertEquals("reverse lookup baz", Collections.emptySet(), InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton("baz"), extractionFn), false));
    Assert.assertNull("reverse lookup baz (includeUnknown)", InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton("baz"), extractionFn), true));
    Assert.assertEquals("reverse lookup [def, bar, baz]", Sets.newHashSet("abc", "foo"), InDimFilter.optimizeLookup(new InDimFilter("dim", Arrays.asList("def", "bar", "baz"), extractionFn), false));
    Assert.assertNull("reverse lookup [def, bar, baz] (includeUnknown)", InDimFilter.optimizeLookup(new InDimFilter("dim", Arrays.asList("def", "bar", "baz"), extractionFn), true));
    Assert.assertNull("reverse lookup null", InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton(null), extractionFn), false));
    Assert.assertNull("reverse lookup null (includeUnknown)", InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton(null), extractionFn), true));
    Assert.assertEquals("reverse lookup empty string", NullHandling.sqlCompatible() ? Collections.emptySet() : null, InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton(""), extractionFn), false));
    Assert.assertNull("reverse lookup empty string (includeUnknown)", InDimFilter.optimizeLookup(new InDimFilter("dim", Collections.singleton(""), extractionFn), true));
}

