    assertCompilation("%_%_%%__", ":[., ., ..$]");
    assertCompilation("%_%a_%bc%_d_", ":[., a., bc, .d.$]");
    assertCompilation("%1 _ 5%6", ":[1 . 5, 6$]");
    assertCompilation("\\%_%a_\\%b\\\\c\\___%_%_d_w%x_y_z", "%:[^\\u0025., a.\\u0025b\\u005Cc_.., ., .d.w, x.y.z$]");
}

