@Test
public void testCombine() throws IOException {
    final ParallelCombiner<ConcurrentGrouperTest.LongKey> combiner = new ParallelCombiner<>(TEST_RESOURCE_HOLDER, new AggregatorFactory[] { new CountAggregatorFactory("cnt").getCombiningFactory() }, KEY_SERDE_FACTORY, MoreExecutors.listeningDecorator(SERVICE), false, THREAD_NUM, // default priority
    0, // default timeout
    0, 4);
    final int numRows = 1000;
    final List<Entry<ConcurrentGrouperTest.LongKey>> baseIterator = new ArrayList<>(numRows);
    for (long i = 0; i < numRows; i++) {
        baseIterator.add(new ReusableEntry<>(new ConcurrentGrouperTest.LongKey(i), new Object[] { i * 10 }));
    }
    final int leafNum = 8;
    final List<TestIterator> iterators = new ArrayList<>(leafNum);
    for (int i = 0; i < leafNum; i++) {
        iterators.add(new TestIterator(baseIterator.iterator()));
    }
    try (final CloseableIterator<Entry<ConcurrentGrouperTest.LongKey>> iterator = combiner.combine(iterators, new ArrayList<>())) {
        long expectedKey = 0;
        while (iterator.hasNext()) {
            final Entry<ConcurrentGrouperTest.LongKey> expectedEntry = new ReusableEntry<>(new ConcurrentGrouperTest.LongKey(expectedKey), new Object[] { expectedKey * leafNum * 10 });
            final Entry<ConcurrentGrouperTest.LongKey> actualEntry = iterator.next();
            GrouperTestUtil.assertEntriesEqual(expectedEntry, actualEntry);
            expectedKey++;
        }
    }
    iterators.forEach(it -> Assert.assertTrue(it.isClosed()));
}

