@Test
public void testComplexDimensionCacheStrategy() throws IOException {
    final GroupByQuery query1 = GroupByQuery.builder().setDataSource(QueryRunnerTestHelper.DATA_SOURCE).setQuerySegmentSpec(QueryRunnerTestHelper.FIRST_TO_THIRD).setDimensions(ImmutableList.of(new DefaultDimensionSpec("test", "test", ColumnType.ofComplex(SerializablePairLongStringComplexMetricSerde.TYPE_NAME)))).setAggregatorSpecs(QueryRunnerTestHelper.ROWS_COUNT).setGranularity(QueryRunnerTestHelper.DAY_GRAN).build();
    ObjectMapper objectMapper = TestHelper.makeJsonMapper();
    CacheStrategy<ResultRow, Object, GroupByQuery> strategy = new GroupByQueryQueryToolChest(null, null).getCacheStrategy(query1, objectMapper);
    // test timestamps that result in integer size millis
    final ResultRow result1 = ResultRow.of(123L, new SerializablePairLongString(123L, "abc"), 1);
    Object preparedValue = strategy.prepareForSegmentLevelCache().apply(result1);
    Object fromCacheValue = objectMapper.readValue(objectMapper.writeValueAsBytes(preparedValue), strategy.getCacheObjectClazz());
    ResultRow fromCacheResult = strategy.pullFromSegmentLevelCache().apply(fromCacheValue);
    Assert.assertEquals(result1, fromCacheResult);
}

