@Test
public void testResultSerde() throws Exception {
    final GroupByQuery query = GroupByQuery.builder().setDataSource(QueryRunnerTestHelper.DATA_SOURCE).setQuerySegmentSpec(QueryRunnerTestHelper.FIRST_TO_THIRD).setDimensions(Collections.singletonList(DefaultDimensionSpec.of("test"))).setAggregatorSpecs(Collections.singletonList(QueryRunnerTestHelper.ROWS_COUNT)).setPostAggregatorSpecs(Collections.singletonList(new ConstantPostAggregator("post", 10))).setGranularity(QueryRunnerTestHelper.DAY_GRAN).build();
    final GroupByQueryQueryToolChest toolChest = new GroupByQueryQueryToolChest(null, null);
    final ObjectMapper objectMapper = TestHelper.makeJsonMapper();
    final ObjectMapper arraysObjectMapper = toolChest.decorateObjectMapper(objectMapper, query.withOverriddenContext(ImmutableMap.of(GroupByQueryConfig.CTX_KEY_ARRAY_RESULT_ROWS, true)));
    final ObjectMapper mapsObjectMapper = toolChest.decorateObjectMapper(objectMapper, query.withOverriddenContext(ImmutableMap.of(GroupByQueryConfig.CTX_KEY_ARRAY_RESULT_ROWS, false)));
    final Object[] rowObjects = { DateTimes.of("2000").getMillis(), "foo", 100, 10.0 };
    final ResultRow resultRow = ResultRow.of(rowObjects);
    Assert.assertArrayEquals("standard mapper reads ResultRows", rowObjects, objectMapper.readValue(arraysObjectMapper.writeValueAsBytes(resultRow), Object[].class));
    Assert.assertEquals("standard mapper reads MapBasedRows", resultRow.toMapBasedRow(query), objectMapper.readValue(mapsObjectMapper.writeValueAsBytes(resultRow), Row.class));
    Assert.assertEquals("array mapper reads arrays", resultRow, arraysObjectMapper.readValue(arraysObjectMapper.writeValueAsBytes(resultRow), ResultRow.class));
    Assert.assertEquals("array mapper reads arrays (2)", resultRow, arraysObjectMapper.readValue(StringUtils.format("[%s, \"foo\", 100, 10.0]", DateTimes.of("2000").getMillis()), ResultRow.class));
    Assert.assertEquals("map mapper reads arrays", resultRow, mapsObjectMapper.readValue(arraysObjectMapper.writeValueAsBytes(resultRow), ResultRow.class));
    Assert.assertEquals("map mapper reads maps", resultRow, mapsObjectMapper.readValue(mapsObjectMapper.writeValueAsBytes(resultRow), ResultRow.class));
}

