@Test
public void testMultiValueDimensionNotAllowed() {
    final String dimName = "placementish";
    if (!vectorize) {
        expectedException.expect(RuntimeException.class);
        expectedException.expectCause(CoreMatchers.instanceOf(ExecutionException.class));
        expectedException.expectCause(ThrowableCauseMatcher.hasCause(CoreMatchers.instanceOf(UnexpectedMultiValueDimensionException.class)));
        expectedException.expect(new BaseMatcher<Throwable>() {

            @Override
            public boolean matches(Object o) {
                final UnexpectedMultiValueDimensionException cause = (UnexpectedMultiValueDimensionException) ((Throwable) o).getCause().getCause();
                return dimName.equals(cause.getDimensionName());
            }

            @Override
            public void describeTo(Description description) {
                description.appendText("an UnexpectedMultiValueDimensionException with dimension [placementish]");
            }
        });
        expectedException.expectMessage(StringUtils.format("Encountered multi-value dimension [%s] that cannot be processed with '%s' set to false." + " Consider setting '%s' to true in your query context.", dimName, GroupByQueryConfig.CTX_KEY_ENABLE_MULTI_VALUE_UNNESTING, GroupByQueryConfig.CTX_KEY_ENABLE_MULTI_VALUE_UNNESTING));
    } else {
        cannotVectorize();
    }
    GroupByQuery query = makeQueryBuilder().setDataSource(QueryRunnerTestHelper.DATA_SOURCE).setQuerySegmentSpec(QueryRunnerTestHelper.FIRST_TO_THIRD).setDimensions(new DefaultDimensionSpec(dimName, "alias")).setAggregatorSpecs(QueryRunnerTestHelper.ROWS_COUNT, new LongSumAggregatorFactory("idx", "index")).setGranularity(QueryRunnerTestHelper.ALL_GRAN).overrideContext(ImmutableMap.of(GroupByQueryConfig.CTX_KEY_ENABLE_MULTI_VALUE_UNNESTING, false)).build();
    GroupByQueryRunnerTestHelper.runQuery(factory, runner, query);
}

