@Test(timeout = 60_000L)
// Doesn't always pass. The check in "eval" is best effort and not guaranteed to detect concurrent usage.
@Ignore
public void testConcurrentUsage() throws Exception {
    final ExecutorService exec = MoreExecutors.listeningDecorator(Execs.multiThreaded(2, "DimFilterHavingSpecTest-%d"));
    final DimFilterHavingSpec havingSpec = new DimFilterHavingSpec(new SelectorDimFilter("foo", "1", null), null);
    final List<Future<?>> futures = new ArrayList<>();
    for (int i = 0; i < 2; i++) {
        final ResultRow row = ResultRow.of(String.valueOf(i));
        futures.add(exec.submit(() -> {
            havingSpec.setQuery(GroupByQuery.builder().setDimensions(DefaultDimensionSpec.of("foo")).build());
            while (!Thread.interrupted()) {
                havingSpec.eval(row);
            }
        }));
    }
    expectedException.expect(ExecutionException.class);
    expectedException.expectCause(CoreMatchers.<IllegalStateException>instanceOf(IllegalStateException.class));
    expectedException.expectCause(ThrowableMessageMatcher.hasMessage(CoreMatchers.containsString("concurrent 'eval' calls not permitted")));
    try {
        for (Future<?> future : futures) {
            future.get();
        }
    } finally {
        exec.shutdownNow();
    }
    // Not reached
    Assert.assertTrue(false);
}

