    columns.put("c", new ColumnAnalysis(ColumnType.DOUBLE, ColumnType.DOUBLE.asTypeString(), true, true, 0, null, null, null, null));
    final SegmentAnalysis analysis = new SegmentAnalysis("id", Intervals.ONLY_ETERNITY, columns, 1, 2, ImmutableMap.of("cnt", new CountAggregatorFactory("cnt")), new TimestampSpec(null, null, null), Granularities.SECOND, true);
    final ObjectMapper jsonMapper = TestHelper.makeJsonMapper();
