@Test
public void testAnalysisImproperComplex() throws IOException {
    QueryableIndex mockIndex = EasyMock.createMock(QueryableIndex.class);
    EasyMock.expect(mockIndex.getNumRows()).andReturn(100).atLeastOnce();
    EasyMock.expect(mockIndex.getColumnNames()).andReturn(Collections.singletonList("x")).atLeastOnce();
    EasyMock.expect(mockIndex.getAvailableDimensions()).andReturn(new ListIndexed<>(Collections.singletonList("x"))).atLeastOnce();
    EasyMock.expect(mockIndex.getColumnCapabilities(ColumnHolder.TIME_COLUMN_NAME)).andReturn(ColumnCapabilitiesImpl.createDefault().setType(ColumnType.LONG)).atLeastOnce();
    EasyMock.expect(mockIndex.getColumnCapabilities("x")).andReturn(ColumnCapabilitiesImpl.createDefault().setType(ColumnType.UNKNOWN_COMPLEX)).atLeastOnce();
    ColumnHolder holder = EasyMock.createMock(ColumnHolder.class);
    EasyMock.expect(mockIndex.getColumnHolder("x")).andReturn(holder).atLeastOnce();
    StringUtf8DictionaryEncodedColumn dictionaryEncodedColumn = EasyMock.createMock(StringUtf8DictionaryEncodedColumn.class);
    EasyMock.expect(holder.getColumn()).andReturn(dictionaryEncodedColumn).atLeastOnce();
    dictionaryEncodedColumn.close();
    EasyMock.expectLastCall();
    EasyMock.replay(mockIndex, holder, dictionaryEncodedColumn);
    Segment s = new QueryableIndexSegment(mockIndex, SegmentId.dummy("test"));
    SegmentAnalyzer analyzer = new SegmentAnalyzer(EMPTY_ANALYSES);
    Map<String, ColumnAnalysis> analysis = analyzer.analyze(s);
    Assert.assertEquals(ColumnType.UNKNOWN_COMPLEX, analysis.get("x").getTypeSignature());
    Assert.assertTrue(analysis.get("x").isError());
    Assert.assertTrue(analysis.get("x").getErrorMessage().contains("is not a [org.apache.druid.segment.column.ComplexColumn]"));
    EasyMock.verify(mockIndex, holder, dictionaryEncodedColumn);
}

@Test
public void testCacheStrategy() throws Exception {
    SegmentMetadataQuery query = new SegmentMetadataQuery(TEST_DATASOURCE, new LegacySegmentSpec("2015-01-01/2015-01-02"), null, null, null, null, false, null, AggregatorMergeStrategy.STRICT);
    CacheStrategy<SegmentAnalysis, SegmentAnalysis, SegmentMetadataQuery> strategy = new SegmentMetadataQueryQueryToolChest(new SegmentMetadataQueryConfig()).getCacheStrategy(query);
    // Test cache key generation
    byte[] expectedKey = { 0x04, 0x09, 0x01, 0x0A, 0x00, 0x00, 0x00, 0x03, 0x00, 0x02, 0x04 };
    byte[] actualKey = strategy.computeCacheKey(query);
    Assert.assertArrayEquals(expectedKey, actualKey);
    SegmentAnalysis result = new SegmentAnalysis(TEST_SEGMENT_ID1.toString(), ImmutableList.of(Intervals.of("2011-01-12T00:00:00.000Z/2011-04-15T00:00:00.001Z")), new LinkedHashMap<>(ImmutableMap.of("placement", new ColumnAnalysis(ColumnType.STRING, ValueType.STRING.name(), true, false, 10881, 1, "preferred", "preferred", null))), 71982, 100, null, null, null, null);
    Object preparedValue = strategy.prepareForSegmentLevelCache().apply(result);
    ObjectMapper objectMapper = new DefaultObjectMapper();
    SegmentAnalysis fromCacheValue = objectMapper.readValue(objectMapper.writeValueAsBytes(preparedValue), strategy.getCacheObjectClazz());
    SegmentAnalysis fromCacheResult = strategy.pullFromSegmentLevelCache().apply(fromCacheValue);
    Assert.assertEquals(result, fromCacheResult);
}

