@Test
public void testAccumulateAndYielderMultiple() {
    OperatorSequence seq = new OperatorSequence(() -> InlineScanOperator.make(MapOfColumnsRowsAndColumns.of("hi", new IntArrayColumn(new int[] { 1 })), MapOfColumnsRowsAndColumns.of("hi", new IntArrayColumn(new int[] { 2 })), MapOfColumnsRowsAndColumns.of("hi", new IntArrayColumn(new int[] { 3, 4 })), MapOfColumnsRowsAndColumns.of("hi", new IntArrayColumn(new int[] { 5, 6, 7, 8 })), MapOfColumnsRowsAndColumns.of("hi", new IntArrayColumn(new int[] { 9, 10, 11 })), MapOfColumnsRowsAndColumns.of("hi", new IntArrayColumn(new int[] { 12, 13, 14, 15 }))));
    Assert.assertEquals(120, seq.accumulate(0, (accumulated, in) -> {
        final ColumnAccessor col = in.findColumn("hi").toAccessor();
        for (int i = 0; i < col.numRows(); ++i) {
            accumulated += col.getInt(i);
        }
        return accumulated;
    }).intValue());
    // Never yield
    Yielder<Integer> yielder = seq.toYielder(0, new YieldingAccumulator<Integer, RowsAndColumns>() {

        @Override
        public Integer accumulate(Integer accumulated, RowsAndColumns in) {
            final ColumnAccessor col = in.findColumn("hi").toAccessor();
            for (int i = 0; i < col.numRows(); ++i) {
                accumulated += col.getInt(i);
            }
            return accumulated;
        }
    });
    Assert.assertEquals(120, yielder.get().intValue());
    Assert.assertTrue(yielder.isDone());
    // Yield at the very end...
    yielder = seq.toYielder(0, new YieldingAccumulator<Integer, RowsAndColumns>() {

        @Override
        public Integer accumulate(Integer accumulated, RowsAndColumns in) {
            final ColumnAccessor col = in.findColumn("hi").toAccessor();
            for (int i = 0; i < col.numRows(); ++i) {
                accumulated += col.getInt(i);
            }
            if (accumulated == 120) {
                this.yield();
            }
            return accumulated;
        }
    });
    Assert.assertEquals(120, yielder.get().intValue());
    Assert.assertFalse(yielder.isDone());
    yielder = yielder.next(0);
    Assert.assertTrue(yielder.isDone());
    // Aggregate each RAC and yield every other.
    yielder = seq.toYielder(0, new YieldingAccumulator<Integer, RowsAndColumns>() {

        @Override
        public Integer accumulate(Integer accumulated, RowsAndColumns in) {
            if (accumulated != 0) {
                this.yield();
            }
            final ColumnAccessor col = in.findColumn("hi").toAccessor();
            for (int i = 0; i < col.numRows(); ++i) {
                accumulated += col.getInt(i);
            }
            return accumulated;
        }
    });
    int[] expectedTotals = new int[] { 3, 33, 84 };
    for (int expectedTotal : expectedTotals) {
        Assert.assertEquals(expectedTotal, yielder.get().intValue());
        Assert.assertFalse(yielder.isDone());
        yielder = yielder.next(0);
    }
    Assert.assertTrue(yielder.isDone());
}

