@Test
public void testWrappedOperatorCarriesThroughValues() throws JsonProcessingException {
    ObjectMapper mapper = new DefaultObjectMapper();
    mapper.setInjectableValues(new InjectableValues.Std().addValue(ExprMacroTable.class, TestExprMacroTable.INSTANCE));
    Interval[] intervals = new Interval[] { Intervals.utc(0, 6), Intervals.utc(6, 13), Intervals.utc(4, 8) };
    DimFilter[] filters = new DimFilter[] { new InDimFilter("dim", ImmutableSet.of("a", "b", "c", "e", "g")), DimFilters.and(new InDimFilter("dim", ImmutableSet.of("a", "b", "g")), DimFilters.dimEquals("val", "789")), DimFilters.or(DimFilters.dimEquals("dim", "b"), DimFilters.dimEquals("val", "789")), DimFilters.dimEquals("dim", "f") };
    int[] limits = new int[] { 100, 1000 };
    List<ColumnWithDirection>[] orderings = new List[] { Arrays.asList(ColumnWithDirection.descending("__time"), ColumnWithDirection.ascending("dim")), Collections.singletonList(ColumnWithDirection.ascending("val")), Collections.emptyList() };
    List<String>[] projections = new List[] { Arrays.asList("dim", "val"), Collections.singletonList("dim"), Collections.emptyList() };
    VirtualColumns[] virtualCols = new VirtualColumns[] { VirtualColumns.create(Collections.singletonList(new ExpressionVirtualColumn("test", "2", null, TestExprMacroTable.INSTANCE))) };
    for (int i = 0; i <= intervals.length; ++i) {
        Interval interval = (i == 0 ? null : intervals[i - 1]);
        for (int j = 0; j <= filters.length; ++j) {
            DimFilter filter = (j == 0 ? null : filters[j - 1]);
            for (int k = 0; k <= limits.length; ++k) {
                int limit = (k == 0 ? -1 : limits[k - 1]);
                for (int l = 0; l <= orderings.length; ++l) {
                    List<ColumnWithDirection> ordering = (l == 0) ? null : orderings[l - 1];
                    for (int m = 0; m <= projections.length; ++m) {
                        List<String> projection = (m == 0) ? null : projections[m - 1];
                        for (int n = 0; n <= virtualCols.length; ++n) {
                            VirtualColumns virtual = (n == 0) ? VirtualColumns.EMPTY : virtualCols[n - 1];
                            String msg = StringUtils.format("interval[%s], filter[%s], limit[%s], ordering[%s], projection[%s], virtual[%s]", interval, filter, OffsetLimit.limit(limit), ordering, projection, virtual);
                            ScanOperatorFactory factory = new ScanOperatorFactory(interval, filter, OffsetLimit.limit(limit), projection, virtual, ordering);
                            final String asString = mapper.writeValueAsString(factory);
                            final ScanOperatorFactory deserialized = mapper.readValue(asString, ScanOperatorFactory.class);
                            Assert.assertEquals(msg, factory, deserialized);
                            Assert.assertEquals(msg, factory.hashCode(), deserialized.hashCode());
                            final ScanOperator wrapped = (ScanOperator) factory.wrap(new Operator() {

                                @Nullable
                                @Override
                                public Closeable goOrContinue(Closeable continuationObject, Receiver receiver) {
                                    receiver.push(new TestRowsAndColumns().withAsImpl(RowsAndColumnsDecorator.class, TestRowsAndColumnsDecorator::new));
                                    receiver.completed();
                                    return null;
                                }
                            });
                            Operator.go(wrapped, new Operator.Receiver() {

                                @Override
                                public Operator.Signal push(RowsAndColumns inRac) {
                                    TestRowsAndColumnsDecorator.DecoratedRowsAndColumns rac = (TestRowsAndColumnsDecorator.DecoratedRowsAndColumns) inRac;
                                    Assert.assertEquals(msg, factory.getTimeRange(), rac.getTimeRange());
                                    Assert.assertEquals(msg, factory.getOffsetLimit(), rac.getOffsetLimit());
                                    Assert.assertEquals(msg, factory.getVirtualColumns(), rac.getVirtualColumns());
                                    validateList(msg, factory.getOrdering(), rac.getOrdering());
                                    validateList(msg, factory.getProjectedColumns(), rac.getProjectedColumns());
                                    Assert.assertEquals(msg, factory.getFilter() == null ? null : factory.getFilter().toFilter(), rac.getFilter());
                                    return Operator.Signal.GO;
                                }

                                @Override
                                public void completed() {
                                }
                            });
                        }
                    }
                }
            }
        }
    }
}

