    final RowsAndColumns first = make(MapOfColumnsRowsAndColumns.of("ints", new IntArrayColumn(new int[] { 1, 7, 13, 0, 19 }), "strs", new ObjectArrayColumn(new Object[] { "b", "h", "n", "a", "t" }, ColumnType.STRING)));
    NaiveSortMaker maker = first.as(NaiveSortMaker.class);
    if (maker == null) {
        maker = new DefaultNaiveSortMaker(first);
    }
    final NaiveSortMaker.NaiveSorter sorter = maker.make(ColumnWithDirection.ascending("ints"));
    final NaiveSortMaker.NaiveSorter stringSorter = maker.make(ColumnWithDirection.ascending("strs"));
    final NaiveSortMaker.NaiveSorter sorterDesc = maker.make(ColumnWithDirection.descending("ints"));
    final NaiveSortMaker.NaiveSorter stringSorterDesc = maker.make(ColumnWithDirection.descending("strs"));
    final RowsAndColumnsHelper helper = new RowsAndColumnsHelper().expectColumn("ints", new int[] { 0, 1, 7, 13, 19 }).expectColumn("strs", new Object[] { "a", "b", "h", "n", "t" }, ColumnType.STRING).allColumnsRegistered();
    final RowsAndColumns sorted = sorter.complete();
    helper.validate(sorted);
    final RowsAndColumns stringSorted = stringSorter.complete();
    helper.validate(stringSorted);
    final RowsAndColumnsHelper descendingHelper = new RowsAndColumnsHelper().expectColumn("ints", new int[] { 19, 13, 7, 1, 0 }).expectColumn("strs", new Object[] { "t", "n", "h", "b", "a" }, ColumnType.STRING).allColumnsRegistered();
    final RowsAndColumns sortedDesc = sorterDesc.complete();
    descendingHelper.validate(sortedDesc);
    final RowsAndColumns stringSortedDesc = stringSorterDesc.complete();
    descendingHelper.validate(stringSortedDesc);
}

@Test
public void testDecoration() {
    Object[][] vals = new Object[][] { { 1L, "a", 123L, 0L }, { 2L, "a", 456L, 1L }, { 3L, "b", 789L, 2L }, { 4L, "b", 123L, 3L }, { 5L, "c", 456L, 4L }, { 6L, "c", 789L, 5L }, { 7L, "c", 123L, 6L }, { 8L, "d", 456L, 7L }, { 9L, "e", 789L, 8L }, { 10L, "f", 123L, 9L }, { 11L, "f", 456L, 10L }, { 12L, "g", 789L, 11L } };
    RowSignature siggy = RowSignature.builder().add("__time", ColumnType.LONG).add("dim", ColumnType.STRING).add("val", ColumnType.LONG).add("arrayIndex", ColumnType.LONG).build();
    final RowsAndColumns base = make(MapOfColumnsRowsAndColumns.fromRowObjects(vals, siggy));
    Interval[] intervals = new Interval[] { Intervals.utc(0, 6), Intervals.utc(6, 13), Intervals.utc(4, 8) };
    Filter[] filters = new Filter[] { new InDimFilter("dim", ImmutableSet.of("a", "b", "c", "e", "g")), new AndFilter(Arrays.asList(new InDimFilter("dim", ImmutableSet.of("a", "b", "g")), new SelectorFilter("val", "789"))), new OrFilter(Arrays.asList(new SelectorFilter("dim", "b"), new SelectorFilter("val", "789"))), new SelectorFilter("dim", "f") };
    int[] limits = new int[] { 3, 6, 100 };
    List<ColumnWithDirection>[] orderings = new List[] { Arrays.asList(ColumnWithDirection.descending("__time"), ColumnWithDirection.ascending("dim")), Collections.singletonList(ColumnWithDirection.ascending("val")) };
    // call the same method multiple times
    for (int i = 0; i <= intervals.length; ++i) {
        Interval interval = (i == 0 ? null : intervals[i - 1]);
        for (int j = 0; j <= filters.length; ++j) {
            Filter filter = (j == 0 ? null : filters[j - 1]);
            for (int k = 0; k <= limits.length; ++k) {
                int limit = (k == 0 ? -1 : limits[k - 1]);
                for (int l = 0; l <= orderings.length; ++l) {
                    validateDecorated(base, siggy, vals, interval, filter, OffsetLimit.limit(limit), l == 0 ? null : orderings[l - 1]);
                }
            }
        }
    }
}

