@Test
public void testArrayComparator() {
    TypeStrategy<Object[]> strategy = ColumnType.LONG_ARRAY.getStrategy();
    Assert.assertEquals(-1, strategy.compare(new Long[] { 1L, 1L, 2L }, new Long[] { 1L, 2L, 3L }));
    Assert.assertEquals(-1, strategy.compare(new Long[] { 1L, 2L }, new Long[] { 1L, 2L, 3L }));
    Assert.assertEquals(-1, strategy.compare(new Long[] {}, new Long[] { 1L }));
    Assert.assertEquals(-1, strategy.compare(null, new Long[] {}));
    //noinspection EqualsWithItself
    Assert.assertEquals(0, strategy.compare(new Long[] { 1L, 2L, 3L }, new Long[] { 1L, 2L, 3L }));
    Assert.assertEquals(1, strategy.compare(new Long[] { 1L, 1L, 2L }, new Long[] { -1L, 2L, 3L }));
    Assert.assertEquals(1, strategy.compare(new Long[] { 1L, 2L, 2L }, new Long[] { 1L, 2L, -3L }));
    Assert.assertEquals(1, strategy.compare(new Long[] { 1L, 2L }, new Long[] { -1L, 2L, 3L }));
    Assert.assertEquals(1, strategy.compare(new Long[] { 1L, 2L }, null));
    NullableTypeStrategy<Object[]> nullableTypeStrategy = ColumnType.LONG_ARRAY.getNullableStrategy();
    Assert.assertEquals(-1, nullableTypeStrategy.compare(new Long[] { 1L, 1L, 2L }, new Long[] { 1L, 2L, 3L }));
    Assert.assertEquals(-1, nullableTypeStrategy.compare(new Long[] { 1L, 2L }, new Long[] { 1L, 2L, 3L }));
    Assert.assertEquals(-1, nullableTypeStrategy.compare(new Long[] {}, new Long[] { 1L }));
    Assert.assertEquals(-1, nullableTypeStrategy.compare(null, new Long[] {}));
    //noinspection EqualsWithItself
    Assert.assertEquals(0, nullableTypeStrategy.compare(new Long[] { 1L, 2L, 3L }, new Long[] { 1L, 2L, 3L }));
    Assert.assertEquals(1, nullableTypeStrategy.compare(new Long[] { 1L, 1L, 2L }, new Long[] { -1L, 2L, 3L }));
    Assert.assertEquals(1, nullableTypeStrategy.compare(new Long[] { 1L, 2L, 2L }, new Long[] { 1L, 2L, -3L }));
    Assert.assertEquals(1, nullableTypeStrategy.compare(new Long[] { 1L, 2L }, new Long[] { -1L, 2L, 3L }));
    Assert.assertEquals(1, nullableTypeStrategy.compare(new Long[] { 1L, 2L }, null));
    strategy = ColumnType.ofArray(ColumnType.ofArray(ColumnType.DOUBLE)).getStrategy();
    Assert.assertEquals(-1, strategy.compare(new Object[] { new Object[] { 1.0, 2.0 } }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(-1, strategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -23.456 } }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(-1, strategy.compare(null, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(-1, strategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, null }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    //noinspection EqualsWithItself
    Assert.assertEquals(0, strategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, null }, new Object[] { new Object[] { 1.0, 2.0 }, null }));
    Assert.assertEquals(1, strategy.compare(new Object[] { new Object[] { 1.0, 2.1 } }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(1, strategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -23.456 } }, new Object[] { new Object[] { 1.0, 2.0 }, null }));
    nullableTypeStrategy = ColumnType.ofArray(ColumnType.ofArray(ColumnType.DOUBLE)).getNullableStrategy();
    Assert.assertEquals(-1, nullableTypeStrategy.compare(new Object[] { new Object[] { 1.0, 2.0 } }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(-1, nullableTypeStrategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -23.456 } }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(-1, nullableTypeStrategy.compare(null, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(-1, nullableTypeStrategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, null }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    //noinspection EqualsWithItself
    Assert.assertEquals(0, nullableTypeStrategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, null }, new Object[] { new Object[] { 1.0, 2.0 }, null }));
    Assert.assertEquals(1, nullableTypeStrategy.compare(new Object[] { new Object[] { 1.0, 2.1 } }, new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -12.345 } }));
    Assert.assertEquals(1, nullableTypeStrategy.compare(new Object[] { new Object[] { 1.0, 2.0 }, new Object[] { 1.1, -23.456 } }, new Object[] { new Object[] { 1.0, 2.0 }, null }));
}

