    // nested string array
    strategy = new TypeStrategies.ArrayTypeStrategy(ColumnType.ofArray(ColumnType.STRING_ARRAY));
    final Object[] nester = new Object[] { someStringArray, someObjectStringArray };
    assertArrayStrategy(strategy, empty);
