@Test
public void testArrayContainsMvd() {
    assertFilterMatches(new ArrayContainsElementFilter("dim2", ColumnType.STRING, "a", null), ImmutableList.of("0", "3"));
    if (isAutoSchema()) {
        assertFilterMatches(NotDimFilter.of(new ArrayContainsElementFilter("dim2", ColumnType.STRING, "a", null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "2", "4") : ImmutableList.of("1", "2", "4", "5"));
        // [""] becomes [null] in default value mode
        assertFilterMatches(new ArrayContainsElementFilter("dim2", ColumnType.STRING, null, null), NullHandling.sqlCompatible() ? ImmutableList.of() : ImmutableList.of("2"));
    } else {
        // multi-value dimension treats [] as null, so in sql compatible mode row 1 ends up as not matching
        assertFilterMatches(NotDimFilter.of(new ArrayContainsElementFilter("dim2", ColumnType.STRING, "a", null)), NullHandling.sqlCompatible() ? ImmutableList.of("2", "4") : ImmutableList.of("1", "2", "4", "5"));
        assertFilterMatches(new ArrayContainsElementFilter("dim2", ColumnType.STRING, null, null), ImmutableList.of());
    }
}

