@Test
public void testListFilteredVirtualColumn() {
    assertFilterMatchesSkipVectorize(new BoundDimFilter("allow-dim0", "0", "2", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of());
    assertFilterMatchesSkipVectorize(new BoundDimFilter("allow-dim0", "0", "6", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("3", "4"));
    // the bound filter matches null, so it is what it is...
    assertFilterMatchesSkipVectorize(new BoundDimFilter("allow-dim0", null, "6", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
    assertFilterMatchesSkipVectorize(new BoundDimFilter("deny-dim0", "0", "6", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("0", "1", "2", "5", "6"));
    assertFilterMatchesSkipVectorize(new BoundDimFilter("deny-dim0", "3", "4", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of());
    // the bound filter matches null, so it is what it is...
    assertFilterMatchesSkipVectorize(new BoundDimFilter("deny-dim0", null, "6", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("0", "1", "2", "3", "4", "5", "6"));
    if (isAutoSchema()) {
        // bail out, auto ingests arrays instead of mvds and this virtual column is for mvd stuff
        return;
    }
    assertFilterMatchesSkipVectorize(new BoundDimFilter("allow-dim2", "a", "c", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("0", "3", "6"));
    assertFilterMatchesSkipVectorize(new BoundDimFilter("allow-dim2", "c", "z", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of());
    // the bound filter matches null, so it is what it is...
    assertFilterMatchesSkipVectorize(new BoundDimFilter("allow-dim2", null, "z", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
    assertFilterMatchesSkipVectorize(new BoundDimFilter("deny-dim2", "a", "b", false, true, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of());
    assertFilterMatchesSkipVectorize(new BoundDimFilter("deny-dim2", "c", "z", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("4", "7"));
    // the bound filter matches null, so it is what it is...
    assertFilterMatchesSkipVectorize(new BoundDimFilter("deny-dim2", null, "z", false, false, false, null, StringComparators.LEXICOGRAPHIC), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
}

