        assertFilterMatchesSkipVectorize(NotDimFilter.of(new EqualityFilter("allow-dim2", ColumnType.STRING, "a", null)), NullHandling.sqlCompatible() ? ImmutableList.of() : ImmutableList.of("1", "2", "4", "5"));
