@Test
public void testSingleValueStringColumnWithNulls() {
    if (NullHandling.sqlCompatible()) {
        assertFilterMatches(new EqualityFilter("dim1", ColumnType.STRING, "", null), ImmutableList.of("0"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("dim1", ColumnType.STRING, "", null)), ImmutableList.of("1", "2", "3", "4", "5"));
        assertFilterMatches(new EqualityFilter("s0", ColumnType.STRING, "", null), ImmutableList.of("0"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "", null)), ImmutableList.of("1", "2", "4", "5"));
    }
    assertFilterMatches(new EqualityFilter("dim1", ColumnType.STRING, "10", null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("dim1", ColumnType.STRING, "2", null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("dim1", ColumnType.STRING, "1", null), ImmutableList.of("3"));
    assertFilterMatches(new EqualityFilter("dim1", ColumnType.STRING, "abdef", null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("dim1", ColumnType.STRING, "abc", null), ImmutableList.of("5"));
    assertFilterMatches(new EqualityFilter("dim1", ColumnType.STRING, "noexist", null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("s0", ColumnType.STRING, "a", null), ImmutableList.of("1", "5"));
    assertFilterMatches(new EqualityFilter("s0", ColumnType.STRING, "b", null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("s0", ColumnType.STRING, "c", null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("s0", ColumnType.STRING, "noexist", null), ImmutableList.of());
    if (NullHandling.sqlCompatible()) {
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("dim1", ColumnType.STRING, "10", null)), ImmutableList.of("0", "2", "3", "4", "5"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("dim1", ColumnType.STRING, "noexist", null)), ImmutableList.of("0", "1", "2", "3", "4", "5"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "4"));
        // "(s0 = 'a') is not true", same rows as "s0 <> 'a'", but also with null rows
        assertFilterMatches(NotDimFilter.of(IsTrueDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null))), ImmutableList.of("0", "2", "3", "4"));
        // "(s0 = 'a') is true", equivalent to "s0 = 'a'"
        assertFilterMatches(IsTrueDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null)), ImmutableList.of("1", "5"));
        // "(s0 = 'a') is false", equivalent results to "s0 <> 'a'"
        assertFilterMatches(IsFalseDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "4"));
        // "(s0 = 'a') is not false", same rows as "s0 = 'a'", but also with null rows
        assertFilterMatches(NotDimFilter.of(IsFalseDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null))), ImmutableList.of("1", "3", "5"));
        try {
            // make sure if 3vl is disabled with behave with 2vl
            NullHandling.initializeForTestsWithValues(false, false, null);
            assertFilterMatches(NotDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "3", "4"));
        } finally {
            NullHandling.initializeForTests();
        }
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "noexist", null)), ImmutableList.of("0", "1", "2", "4", "5"));
    } else {
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("dim1", ColumnType.STRING, "10", null)), ImmutableList.of("0", "2", "3", "4", "5"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("dim1", ColumnType.STRING, "noexist", null)), ImmutableList.of("0", "1", "2", "3", "4", "5"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "3", "4"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "noexist", null)), ImmutableList.of("0", "1", "2", "3", "4", "5"));
        // in default value mode, is true/is false are basically pointless since they have the same behavior as = and <>
        // "(s0 = 'a') is not true" equivalent to "s0 <> 'a'"
        assertFilterMatches(NotDimFilter.of(IsTrueDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null))), ImmutableList.of("0", "2", "3", "4"));
        // "(s0 = 'a') is true", equivalent to "s0 = 'a'"
        assertFilterMatches(IsTrueDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null)), ImmutableList.of("1", "5"));
        // "(s0 = 'a') is false" equivalent to "s0 <> 'a'"
        assertFilterMatches(IsFalseDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "3", "4"));
        // "(s0 = 'a') is not false", equivalent to "s0 = 'a'"
        assertFilterMatches(NotDimFilter.of(IsFalseDimFilter.of(new EqualityFilter("s0", ColumnType.STRING, "a", null))), ImmutableList.of("1", "5"));
    }
}

