        assertFilterMatches(new EqualityFilter("dim2", ColumnType.STRING_ARRAY, new Object[] { "b" }, null), ImmutableList.of());
        assertFilterMatches(new EqualityFilter("dim2", ColumnType.STRING_ARRAY, new Object[] { "c" }, null), ImmutableList.of("4"));
        assertFilterMatches(new EqualityFilter("dim2", ColumnType.STRING_ARRAY, new Object[] { "d" }, null), ImmutableList.of());
    } else {
        if (NullHandling.sqlCompatible()) {
            assertFilterMatches(new EqualityFilter("dim2", ColumnType.STRING, "", null), ImmutableList.of("2"));
            assertFilterMatches(NotDimFilter.of(new EqualityFilter("dim2", ColumnType.STRING, "", null)), ImmutableList.of("0", "3", "4"));
