        assertFilterMatches(new EqualityFilter("dim2", ColumnType.STRING, "a", null), ImmutableList.of("0", "3"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("dim2", ColumnType.STRING, "a", null)), NullHandling.replaceWithDefault() ? ImmutableList.of("1", "2", "4", "5") : ImmutableList.of("2", "4"));
