@Test
public void testNumeric() {
    /*
        dim0   d0         f0        l0
        "0" .. 0.0,       0.0f,     0L
        "1" .. 10.1,      10.1f,    100L
        "2" .. null,      5.5f,     40L
        "3" .. 120.0245,  110.0f,   null
        "4" .. 60.0,      null,     9001L
        "5" .. 765.432,   123.45f,  12345L
     */
    assertFilterMatches(new EqualityFilter("d0", ColumnType.DOUBLE, 10.1, null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("d0", ColumnType.DOUBLE, 120.0245, null), ImmutableList.of("3"));
    assertFilterMatches(new EqualityFilter("d0", ColumnType.DOUBLE, 765.432, null), ImmutableList.of("5"));
    assertFilterMatches(new EqualityFilter("d0", ColumnType.DOUBLE, 765.431, null), ImmutableList.of());
    // different type matcher
    assertFilterMatches(new EqualityFilter("d0", ColumnType.LONG, 0L, null), canTestNumericNullsAsDefaultValues ? ImmutableList.of("0", "2") : ImmutableList.of("0"));
    assertFilterMatches(new EqualityFilter("d0", ColumnType.LONG, 60L, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("l0", ColumnType.LONG, 100L, null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("l0", ColumnType.LONG, 40L, null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("l0", ColumnType.LONG, 9001L, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("l0", ColumnType.LONG, 9000L, null), ImmutableList.of());
    // test loss of precision
    assertFilterMatches(new EqualityFilter("l0", ColumnType.DOUBLE, 100.1, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("l0", ColumnType.DOUBLE, 100.0, null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("l0", ColumnType.DOUBLE, 40.1, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("l0", ColumnType.DOUBLE, 40.0, null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("l0", ColumnType.DOUBLE, 9001.1, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("l0", ColumnType.DOUBLE, 9001.0, null), ImmutableList.of("4"));
    if (!isAutoSchema()) {
        // auto schema doesn't store float columns as floats, rather they are stored as doubles... the predicate matcher
        // matches fine, but the string value set index does not match correctly if we expect the input float values
        assertFilterMatches(new EqualityFilter("f0", ColumnType.FLOAT, 10.1f, null), ImmutableList.of("1"));
        assertFilterMatches(new EqualityFilter("f0", ColumnType.FLOAT, 110.0f, null), ImmutableList.of("3"));
        assertFilterMatches(new EqualityFilter("f0", ColumnType.FLOAT, 123.45f, null), ImmutableList.of("5"));
        assertFilterMatches(new EqualityFilter("f0", ColumnType.FLOAT, 123.46f, null), ImmutableList.of());
    } else {
        // .. so we need to cast them instead
        assertFilterMatches(new EqualityFilter("f0", ColumnType.DOUBLE, (double) 10.1f, null), ImmutableList.of("1"));
        assertFilterMatches(new EqualityFilter("f0", ColumnType.DOUBLE, (double) 110.0f, null), ImmutableList.of("3"));
        assertFilterMatches(new EqualityFilter("f0", ColumnType.DOUBLE, (double) 123.45f, null), ImmutableList.of("5"));
        assertFilterMatches(new EqualityFilter("f0", ColumnType.DOUBLE, (double) 123.46f, null), ImmutableList.of());
    }
}

@Test
public void testArrays() {
    Assume.assumeTrue(canTestArrayColumns());
    /*
          dim0 .. arrayString               arrayLong             arrayDouble
          "0", .. ["a", "b", "c"],          [1L, 2L, 3L],         [1.1, 2.2, 3.3]
          "1", .. [],                       [],                   [1.1, 2.2, 3.3]
          "2", .. null,                     [1L, 2L, 3L],         [null]
          "3", .. ["a", "b", "c"],          null,                 []
          "4", .. ["c", "d"],               [null],               [-1.1, -333.3]
          "5", .. [null],                   [123L, 345L],         null
       */
    assertFilterMatches(new EqualityFilter("arrayString", ColumnType.STRING_ARRAY, ImmutableList.of("a", "b", "c"), null), ImmutableList.of("0", "3"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("arrayString", ColumnType.STRING_ARRAY, ImmutableList.of("a", "b", "c"), null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "4", "5") : ImmutableList.of("1", "2", "4", "5"));
    assertFilterMatches(new EqualityFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { "a", "b", "c" }, null), ImmutableList.of("0", "3"));
    assertFilterMatches(new EqualityFilter("arrayString", ColumnType.STRING_ARRAY, ImmutableList.of(), null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { null }, null), ImmutableList.of("5"));
    assertFilterMatches(new EqualityFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { null, null }, null), ImmutableList.of());
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { null, null }, null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "1", "3", "4", "5") : ImmutableList.of("0", "1", "2", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.LONG_ARRAY, ImmutableList.of(1L, 2L, 3L), null), ImmutableList.of("0", "2"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("arrayLong", ColumnType.LONG_ARRAY, ImmutableList.of(1L, 2L, 3L), null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "4", "5") : ImmutableList.of("1", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.LONG_ARRAY, new Object[] { 1L, 2L, 3L }, null), ImmutableList.of("0", "2"));
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.LONG_ARRAY, ImmutableList.of(), null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.LONG_ARRAY, new Object[] { null }, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.LONG_ARRAY, new Object[] { null, null }, null), ImmutableList.of());
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("arrayLong", ColumnType.LONG_ARRAY, new Object[] { null, null }, null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "1", "2", "4", "5") : ImmutableList.of("0", "1", "2", "3", "4", "5"));
    // test loss of precision matching long arrays with double array match values
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.DOUBLE_ARRAY, new Object[] { 1.0, 2.0, 3.0 }, null), ImmutableList.of("0", "2"));
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 2.2, 3.3 }, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("arrayLong", ColumnType.DOUBLE_ARRAY, new Object[] { null }, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.3), null), ImmutableList.of("0", "1"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.3), null)), NullHandling.sqlCompatible() ? ImmutableList.of("2", "3", "4") : ImmutableList.of("2", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 2.2, 3.3 }, null), ImmutableList.of("0", "1"));
    assertFilterMatches(new EqualityFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(), null), ImmutableList.of("3"));
    assertFilterMatches(new EqualityFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, new Object[] { null }, null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.4), null), ImmutableList.of());
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.4), null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "1", "2", "3", "4") : ImmutableList.of("0", "1", "2", "3", "4", "5"));
}

@Test
public void testVariant() {
    /*
      dim0 .. variant
      "0", .. "abc"
      "1", .. 100L
      "2", .. "100"
      "3", .. [1.1, 2.2, 3.3]
      "4", .. 12.34
      "5", .. [100, 200, 300]

       */
    // only auto well supports variant types
    Assume.assumeTrue(isAutoSchema());
    assertFilterMatches(new EqualityFilter("variant", ColumnType.STRING_ARRAY, ImmutableList.of("a", "b", "c"), null), ImmutableList.of());
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("variant", ColumnType.STRING_ARRAY, ImmutableList.of("a", "b", "c"), null)), ImmutableList.of("0", "1", "2", "3", "4", "5"));
    // variant columns must be matched as arrays if they contain any arrays
    assertFilterMatches(new EqualityFilter("variant", ColumnType.STRING, "abc", null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("variant", ColumnType.STRING_ARRAY, ImmutableList.of("abc"), null), ImmutableList.of("0"));
    assertFilterMatches(new EqualityFilter("variant", ColumnType.LONG, 100L, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("variant", ColumnType.LONG_ARRAY, ImmutableList.of(100L), null), ImmutableList.of("1", "2"));
    assertFilterMatches(new EqualityFilter("variant", ColumnType.STRING, "100", null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("variant", ColumnType.STRING_ARRAY, new Object[] { "100" }, null), ImmutableList.of("1", "2"));
    assertFilterMatches(new EqualityFilter("variant", ColumnType.LONG_ARRAY, Arrays.asList(100, 200, 300), null), ImmutableList.of("5"));
}

@Test
public void testNestedColumnEquality() {
    // nested column mirrors the top level columns, so these cases are copied from other tests
    Assume.assumeTrue(canTestArrayColumns());
    if (NullHandling.sqlCompatible()) {
        assertFilterMatches(new EqualityFilter("nested.s0", ColumnType.STRING, "", null), ImmutableList.of("0"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "", null)), ImmutableList.of("1", "2", "4", "5"));
    }
    assertFilterMatches(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null), ImmutableList.of("1", "5"));
    assertFilterMatches(new EqualityFilter("nested.s0", ColumnType.STRING, "b", null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("nested.s0", ColumnType.STRING, "c", null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("nested.s0", ColumnType.STRING, "noexist", null), ImmutableList.of());
    if (NullHandling.sqlCompatible()) {
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "4"));
        // "(s0 = 'a') is not true", same rows as "s0 <> 'a'", but also with null rows
        assertFilterMatches(NotDimFilter.of(IsTrueDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null))), ImmutableList.of("0", "2", "3", "4"));
        // "(s0 = 'a') is true", equivalent to "s0 = 'a'"
        assertFilterMatches(IsTrueDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null)), ImmutableList.of("1", "5"));
        // "(s0 = 'a') is false", equivalent results to "s0 <> 'a'"
        assertFilterMatches(IsFalseDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "4"));
        // "(s0 = 'a') is not false", same rows as "s0 = 'a'", but also with null rows
        assertFilterMatches(NotDimFilter.of(IsFalseDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null))), ImmutableList.of("1", "3", "5"));
        try {
            // make sure if 3vl is disabled with behave with 2vl
            NullHandling.initializeForTestsWithValues(false, false, null);
            assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "3", "4"));
        } finally {
            NullHandling.initializeForTests();
        }
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "noexist", null)), ImmutableList.of("0", "1", "2", "4", "5"));
    } else {
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "3", "4"));
        assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "noexist", null)), ImmutableList.of("0", "1", "2", "3", "4", "5"));
        // in default value mode, is true/is false are basically pointless since they have the same behavior as = and <>
        // "(s0 = 'a') is not true" equivalent to "s0 <> 'a'"
        assertFilterMatches(NotDimFilter.of(IsTrueDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null))), ImmutableList.of("0", "2", "3", "4"));
        // "(s0 = 'a') is true", equivalent to "s0 = 'a'"
        assertFilterMatches(IsTrueDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null)), ImmutableList.of("1", "5"));
        // "(s0 = 'a') is false" equivalent to "s0 <> 'a'"
        assertFilterMatches(IsFalseDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null)), ImmutableList.of("0", "2", "3", "4"));
        // "(s0 = 'a') is not false", equivalent to "s0 = 'a'"
        assertFilterMatches(NotDimFilter.of(IsFalseDimFilter.of(new EqualityFilter("nested.s0", ColumnType.STRING, "a", null))), ImmutableList.of("1", "5"));
    }
    /*
        dim0   d0         l0
        "0" .. 0.0,       0L
        "1" .. 10.1,      100L
        "2" .. null,      40L
        "3" .. 120.0245,  null
        "4" .. 60.0,      9001L
        "5" .. 765.432,   12345L
     */
    // nested columns do not coerce null to default values
    assertFilterMatches(new EqualityFilter("nested.d0", ColumnType.DOUBLE, 0.0, null), ImmutableList.of("0"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.d0", ColumnType.DOUBLE, 0.0, null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "3", "4", "5") : ImmutableList.of("1", "2", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.LONG, 0L, null), ImmutableList.of("0"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.l0", ColumnType.LONG, 0L, null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "2", "4", "5") : ImmutableList.of("1", "2", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.STRING, "0", null), ImmutableList.of("0"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.STRING, "0", null), ImmutableList.of("0"));
    assertFilterMatches(new EqualityFilter("nested.d0", ColumnType.DOUBLE, 10.1, null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("nested.d0", ColumnType.DOUBLE, 120.0245, null), ImmutableList.of("3"));
    assertFilterMatches(new EqualityFilter("nested.d0", ColumnType.DOUBLE, 765.432, null), ImmutableList.of("5"));
    assertFilterMatches(new EqualityFilter("nested.d0", ColumnType.DOUBLE, 765.431, null), ImmutableList.of());
    // different type matcher
    assertFilterMatches(new EqualityFilter("nested.d0", ColumnType.LONG, 0L, null), ImmutableList.of("0"));
    assertFilterMatches(new EqualityFilter("d0", ColumnType.LONG, 60L, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.LONG, 100L, null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.LONG, 40L, null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.LONG, 9001L, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.LONG, 9000L, null), ImmutableList.of());
    // test loss of precision
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.DOUBLE, 100.1, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.DOUBLE, 100.0, null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.DOUBLE, 40.1, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.DOUBLE, 40.0, null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.DOUBLE, 9001.1, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("nested.l0", ColumnType.DOUBLE, 9001.0, null), ImmutableList.of("4"));
    /*
          dim0 .. arrayString               arrayLong             arrayDouble
          "0", .. ["a", "b", "c"],          [1L, 2L, 3L],         [1.1, 2.2, 3.3]
          "1", .. [],                       [],                   [1.1, 2.2, 3.3]
          "2", .. null,                     [1L, 2L, 3L],         [null]
          "3", .. ["a", "b", "c"],          null,                 []
          "4", .. ["c", "d"],               [null],               [-1.1, -333.3]
          "5", .. [null],                   [123L, 345L],         null
       */
    assertFilterMatches(new EqualityFilter("nested.arrayString", ColumnType.STRING_ARRAY, ImmutableList.of("a", "b", "c"), null), ImmutableList.of("0", "3"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.arrayString", ColumnType.STRING_ARRAY, ImmutableList.of("a", "b", "c"), null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "4", "5") : ImmutableList.of("1", "2", "4", "5"));
    assertFilterMatches(new EqualityFilter("nested.arrayString", ColumnType.STRING_ARRAY, new Object[] { "a", "b", "c" }, null), ImmutableList.of("0", "3"));
    assertFilterMatches(new EqualityFilter("nested.arrayString", ColumnType.STRING_ARRAY, ImmutableList.of(), null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("nested.arrayString", ColumnType.STRING_ARRAY, new Object[] { null }, null), ImmutableList.of("5"));
    assertFilterMatches(new EqualityFilter("nested.arrayString", ColumnType.STRING_ARRAY, new Object[] { null, null }, null), ImmutableList.of());
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.arrayString", ColumnType.STRING_ARRAY, new Object[] { null, null }, null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "1", "3", "4", "5") : ImmutableList.of("0", "1", "2", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.LONG_ARRAY, ImmutableList.of(1L, 2L, 3L), null), ImmutableList.of("0", "2"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.arrayLong", ColumnType.LONG_ARRAY, ImmutableList.of(1L, 2L, 3L), null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "4", "5") : ImmutableList.of("1", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.LONG_ARRAY, new Object[] { 1L, 2L, 3L }, null), ImmutableList.of("0", "2"));
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.LONG_ARRAY, ImmutableList.of(), null), ImmutableList.of("1"));
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.LONG_ARRAY, new Object[] { null }, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.LONG_ARRAY, new Object[] { null, null }, null), ImmutableList.of());
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.arrayLong", ColumnType.LONG_ARRAY, new Object[] { null, null }, null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "1", "2", "4", "5") : ImmutableList.of("0", "1", "2", "3", "4", "5"));
    // test loss of precision matching long arrays with double array match values
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.DOUBLE_ARRAY, new Object[] { 1.0, 2.0, 3.0 }, null), ImmutableList.of("0", "2"));
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 2.2, 3.3 }, null), ImmutableList.of());
    assertFilterMatches(new EqualityFilter("nested.arrayLong", ColumnType.DOUBLE_ARRAY, new Object[] { null }, null), ImmutableList.of("4"));
    assertFilterMatches(new EqualityFilter("nested.arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.3), null), ImmutableList.of("0", "1"));
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.3), null)), NullHandling.sqlCompatible() ? ImmutableList.of("2", "3", "4") : ImmutableList.of("2", "3", "4", "5"));
    assertFilterMatches(new EqualityFilter("nested.arrayDouble", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 2.2, 3.3 }, null), ImmutableList.of("0", "1"));
    assertFilterMatches(new EqualityFilter("nested.arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(), null), ImmutableList.of("3"));
    assertFilterMatches(new EqualityFilter("nested.arrayDouble", ColumnType.DOUBLE_ARRAY, new Object[] { null }, null), ImmutableList.of("2"));
    assertFilterMatches(new EqualityFilter("nested.arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.4), null), ImmutableList.of());
    assertFilterMatches(NotDimFilter.of(new EqualityFilter("nested.arrayDouble", ColumnType.DOUBLE_ARRAY, ImmutableList.of(1.1, 2.2, 3.4), null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "1", "2", "3", "4") : ImmutableList.of("0", "1", "2", "3", "4", "5"));
}

@Test
public void testSerde() throws JsonProcessingException {
    ObjectMapper mapper = new DefaultObjectMapper();
    EqualityFilter filter = new EqualityFilter("x", ColumnType.STRING, "hello", null);
    String s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.LONG, 1L, null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.LONG, 1, null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.DOUBLE, 111.111, null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.FLOAT, 1234.0f, null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.STRING_ARRAY, new Object[] { "a", "b", null, "c" }, null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.STRING_ARRAY, Arrays.asList("a", "b", null, "c"), null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.LONG_ARRAY, new Object[] { 1L, null, 2L, 3L }, null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.LONG_ARRAY, Arrays.asList(1L, null, 2L, 3L), null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 2.1, null, 3.1 }, null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.DOUBLE_ARRAY, Arrays.asList(1.1, 2.1, null, 3.1), null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
    filter = new EqualityFilter("x", ColumnType.NESTED_DATA, ImmutableMap.of("x", ImmutableList.of(1, 2, 3)), null);
    s = mapper.writeValueAsString(filter);
    Assert.assertEquals(filter, mapper.readValue(s, EqualityFilter.class));
}

