@Test
public void testLegacyMatchWithExtractionFn() {
    String extractionJsFn = "function(str) { return 'super-' + str; }";
    ExtractionFn superFn = new JavaScriptExtractionFn(extractionJsFn, false, JavaScriptConfig.getEnabledInstance());
    String nullJsFn = "function(str) { if (str === null) { return 'YES'; } else { return 'NO';} }";
    ExtractionFn yesNullFn = new JavaScriptExtractionFn(nullJsFn, false, JavaScriptConfig.getEnabledInstance());
    if (NullHandling.replaceWithDefault()) {
        assertFilterMatchesSkipArrays(legacyInFilterWithFn("dim2", superFn, "super-null", "super-a", "super-b"), ImmutableList.of("a", "b", "c", "d", "f"));
        assertFilterMatchesSkipArrays(NotDimFilter.of(legacyInFilterWithFn("dim2", superFn, "super-null", "super-a", "super-b")), ImmutableList.of("e"));
        assertFilterMatchesSkipArrays(legacyInFilterWithFn("dim2", yesNullFn, "YES"), ImmutableList.of("b", "c", "f"));
        assertFilterMatchesSkipArrays(NotDimFilter.of(legacyInFilterWithFn("dim2", yesNullFn, "YES")), ImmutableList.of("a", "d", "e"));
        assertLegacyFilterMatches(legacyInFilterWithFn("dim1", superFn, "super-null", "super-10", "super-def"), ImmutableList.of("a", "b", "e"));
        assertLegacyFilterMatches(legacyInFilterWithFn("dim1", yesNullFn, "NO"), ImmutableList.of("b", "c", "d", "e", "f"));
    } else {
        assertFilterMatchesSkipArrays(legacyInFilterWithFn("dim2", superFn, "super-null", "super-a", "super-b"), ImmutableList.of("a", "b", "d", "f"));
        assertFilterMatchesSkipArrays(NotDimFilter.of(legacyInFilterWithFn("dim2", superFn, "super-null", "super-a", "super-b")), ImmutableList.of("c", "e"));
        assertFilterMatchesSkipArrays(legacyInFilterWithFn("dim2", yesNullFn, "YES"), ImmutableList.of("b", "f"));
        assertFilterMatchesSkipArrays(NotDimFilter.of(legacyInFilterWithFn("dim2", yesNullFn, "YES")), ImmutableList.of("a", "c", "d", "e"));
        assertLegacyFilterMatches(legacyInFilterWithFn("dim1", superFn, "super-null", "super-10", "super-def"), ImmutableList.of("b", "e"));
        assertLegacyFilterMatches(legacyInFilterWithFn("dim1", yesNullFn, "NO"), ImmutableList.of("a", "b", "c", "d", "e", "f"));
    }
    assertLegacyFilterMatches(legacyInFilterWithFn("dim3", yesNullFn, "NO"), ImmutableList.of());
    assertLegacyFilterMatches(NotDimFilter.of(legacyInFilterWithFn("dim3", yesNullFn, "NO")), ImmutableList.of("a", "b", "c", "d", "e", "f"));
    assertLegacyFilterMatches(legacyInFilterWithFn("dim3", yesNullFn, "YES"), ImmutableList.of("a", "b", "c", "d", "e", "f"));
}

@Test
public void testLegacyMatchWithLookupExtractionFn() {
    final Map<String, String> stringMap = ImmutableMap.of("a", "HELLO", "10", "HELLO", "def", "HELLO", "c", "BYE");
    LookupExtractor mapExtractor = new MapLookupExtractor(stringMap, false);
    LookupExtractionFn lookupFn = new LookupExtractionFn(mapExtractor, false, "UNKNOWN", false, true);
    assertLegacyFilterMatches(legacyInFilterWithFn("dim0", lookupFn, null, "HELLO"), ImmutableList.of("a"));
    assertLegacyFilterMatches(legacyInFilterWithFn("dim0", lookupFn, "HELLO", "BYE"), ImmutableList.of("a", "c"));
    assertLegacyFilterMatches(legacyInFilterWithFn("dim0", lookupFn, "UNKNOWN"), ImmutableList.of("b", "d", "e", "f"));
    assertLegacyFilterMatches(legacyInFilterWithFn("dim1", lookupFn, "HELLO"), ImmutableList.of("b", "e"));
    assertLegacyFilterMatches(legacyInFilterWithFn("dim1", lookupFn, "N/A"), ImmutableList.of());
    if (optimize) {
        // Arrays don't cause errors when the extractionFn is optimized, because the "IN" filter vanishes completely.
        assertLegacyFilterMatches(legacyInFilterWithFn("dim2", lookupFn, "a"), ImmutableList.of());
    } else {
        assertFilterMatchesSkipArrays(legacyInFilterWithFn("dim2", lookupFn, "a"), ImmutableList.of());
    }
    assertFilterMatchesSkipArrays(legacyInFilterWithFn("dim2", lookupFn, "HELLO"), ImmutableList.of("a", "d"));
    assertFilterMatchesSkipArrays(legacyInFilterWithFn("dim2", lookupFn, "HELLO", "BYE", "UNKNOWN"), ImmutableList.of("a", "b", "c", "d", "e", "f"));
    final Map<String, String> stringMap2 = ImmutableMap.of("a", "e");
    LookupExtractor mapExtractor2 = new MapLookupExtractor(stringMap2, false);
    LookupExtractionFn lookupFn2 = new LookupExtractionFn(mapExtractor2, true, null, false, true);
    assertLegacyFilterMatches(legacyInFilterWithFn("dim0", lookupFn2, null, "e"), ImmutableList.of("a", "e"));
    assertLegacyFilterMatches(legacyInFilterWithFn("dim0", lookupFn2, "a"), ImmutableList.of());
    final Map<String, String> stringMap3 = ImmutableMap.of("c", "500", "100", "e");
