@Test
public void testLexicographicalMatch() {
    assertFilterMatches(new RangeFilter("dim0", ColumnType.STRING, null, "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
    assertFilterMatches(new RangeFilter("vdim0", ColumnType.STRING, null, "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
    if (NullHandling.sqlCompatible()) {
        assertFilterMatches(new RangeFilter("dim1", ColumnType.STRING, null, "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
        assertFilterMatches(new RangeFilter("vdim0", ColumnType.STRING, null, "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
        assertFilterMatches(NotDimFilter.of(new RangeFilter("dim1", ColumnType.STRING, null, "z", false, false, null)), ImmutableList.of());
        assertFilterMatches(NotDimFilter.of(new RangeFilter("vdim0", ColumnType.STRING, null, "z", false, false, null)), ImmutableList.of());
        assertFilterMatches(new RangeFilter("s0", ColumnType.STRING, null, "b", false, false, null), ImmutableList.of("0", "1", "2", "5"));
        assertFilterMatches(new RangeFilter("vs0", ColumnType.STRING, null, "b", false, false, null), ImmutableList.of("0", "1", "2", "5"));
        assertFilterMatches(NotDimFilter.of(new RangeFilter("s0", ColumnType.STRING, null, "b", false, false, null)), ImmutableList.of("4", "6", "7"));
        assertFilterMatches(NotDimFilter.of(new RangeFilter("vs0", ColumnType.STRING, null, "b", false, false, null)), ImmutableList.of("4", "6", "7"));
    } else {
        assertFilterMatches(new RangeFilter("dim1", ColumnType.STRING, null, "z", false, false, null), ImmutableList.of("1", "2", "3", "4", "5", "6", "7"));
        assertFilterMatches(new RangeFilter("vdim0", ColumnType.STRING, null, "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
        assertFilterMatches(NotDimFilter.of(new RangeFilter("dim1", ColumnType.STRING, null, "z", false, false, null)), NullHandling.sqlCompatible() ? ImmutableList.of() : ImmutableList.of("0"));
        assertFilterMatches(NotDimFilter.of(new RangeFilter("vdim0", ColumnType.STRING, null, "z", false, false, null)), NullHandling.sqlCompatible() ? ImmutableList.of("0") : ImmutableList.of());
        assertFilterMatches(new RangeFilter("s0", ColumnType.STRING, null, "b", false, false, null), ImmutableList.of("1", "2", "5"));
        assertFilterMatches(new RangeFilter("vs0", ColumnType.STRING, null, "b", false, false, null), ImmutableList.of("1", "2", "5"));
        assertFilterMatches(NotDimFilter.of(new RangeFilter("s0", ColumnType.STRING, null, "b", false, false, null)), NullHandling.sqlCompatible() ? ImmutableList.of("4", "6", "7") : ImmutableList.of("0", "3", "4", "6", "7"));
        assertFilterMatches(NotDimFilter.of(new RangeFilter("vs0", ColumnType.STRING, null, "b", false, false, null)), NullHandling.sqlCompatible() ? ImmutableList.of("4", "6", "7") : ImmutableList.of("0", "3", "4", "6", "7"));
    }
    if (isAutoSchema()) {
        // auto schema ingests arrays instead of mvds.. this is covered in array tests
    } else {
        assertFilterMatches(new RangeFilter("dim2", ColumnType.STRING, null, "z", false, false, null), NullHandling.sqlCompatible() ? ImmutableList.of("0", "2", "3", "4", "6", "7") : ImmutableList.of("0", "3", "4", "6", "7"));
        // vdim2 does not exist...
        assertFilterMatches(new RangeFilter("dim3", ColumnType.STRING, null, "z", false, false, null), ImmutableList.of());
    }
}

@Test
public void testLexicographicMatchWithEmptyString() {
    if (NullHandling.sqlCompatible()) {
        assertFilterMatches(new RangeFilter("dim0", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
        assertFilterMatches(new RangeFilter("dim1", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
        if (!isAutoSchema()) {
            // auto schema ingests arrays which are currently incompatible with the range filter
            assertFilterMatches(new RangeFilter("dim2", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of("0", "2", "3", "4", "6", "7"));
        }
        assertFilterMatches(new RangeFilter("dim3", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of());
    } else {
        assertFilterMatches(new RangeFilter("dim0", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
        assertFilterMatches(new RangeFilter("dim1", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of("1", "2", "3", "4", "5", "6", "7"));
        if (!isAutoSchema()) {
            // auto schema ingests arrays which are currently incompatible with the range filter
            assertFilterMatches(new RangeFilter("dim2", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of("0", "3", "4", "6", "7"));
        }
        assertFilterMatches(new RangeFilter("dim3", ColumnType.STRING, "", "z", false, false, null), ImmutableList.of());
    }
}

@Test
public void testLexicographicMatchNull() {
    if (NullHandling.replaceWithDefault()) {
        // in default value mode this is null on both ends...
        Throwable t = Assert.assertThrows(DruidException.class, () -> assertFilterMatches(new RangeFilter("dim0", ColumnType.STRING, "", "", false, false, null), ImmutableList.of()));
        Assert.assertEquals("Invalid range filter on column [dim0], lower and upper cannot be null at the same time", t.getMessage());
    } else {
        assertFilterMatches(new RangeFilter("dim0", ColumnType.STRING, "", "", false, false, null), ImmutableList.of());
        assertFilterMatches(new RangeFilter("dim1", ColumnType.STRING, "", "", false, false, null), ImmutableList.of("0"));
        // still matches even with auto-schema because match-values are upcast to array types
        assertFilterMatches(new RangeFilter("dim2", ColumnType.STRING, "", "", false, false, null), ImmutableList.of("2"));
    }
}

