@Test
public void testNumericMatchPrecisionLoss() {
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12345.1, 12345.4, false, true, null), ImmutableList.of());
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.1, 12345.4, false, false, null), ImmutableList.of("5"));
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.1, 12345.4, false, true, null), ImmutableList.of("5"));
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.1, 12345.4, true, false, null), ImmutableList.of("5"));
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.1, 12345.4, false, true, null), ImmutableList.of("5"));
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12345.0, 12345.1, false, true, null), ImmutableList.of("5"));
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12345.0, 12345.1, true, true, null), ImmutableList.of());
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.0, 12344.9, false, false, null), ImmutableList.of());
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.0, 12344.9, false, true, null), ImmutableList.of());
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.5, null, true, true, null), ImmutableList.of("5"));
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12344.5, null, false, true, null), ImmutableList.of("5"));
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12345.5, null, true, true, null), ImmutableList.of());
    assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, 12345.5, null, false, true, null), ImmutableList.of());
    if (canTestNumericNullsAsDefaultValues) {
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12344.5, true, true, null), ImmutableList.of("0", "1", "2", "3", "4", "6", "7"));
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12344.5, false, true, null), ImmutableList.of("0", "1", "2", "3", "4", "6", "7"));
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12345.5, true, true, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12345.5, false, true, null), ImmutableList.of("0", "1", "2", "3", "4", "5", "6", "7"));
    } else {
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12344.5, true, true, null), ImmutableList.of("0", "1", "2", "4", "6"));
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12344.5, false, true, null), ImmutableList.of("0", "1", "2", "4", "6"));
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12345.5, true, true, null), ImmutableList.of("0", "1", "2", "4", "5", "6"));
        assertFilterMatches(new RangeFilter("l0", ColumnType.DOUBLE, null, 12345.5, false, true, null), ImmutableList.of("0", "1", "2", "4", "5", "6"));
    }
}

