@Test
public void testArrayRanges() {
    // only auto schema supports array columns currently, this means the match value will need to be coerceable to
    // the column value type...
    Assume.assumeTrue(isAutoSchema());
    /*  dim0 .. arrayString               arrayLong             arrayDouble
          "0", .. ["a", "b", "c"],          [1L, 2L, 3L],         [1.1, 2.2, 3.3]
          "1", .. [],                       [],                   [1.1, 2.2, 3.3]
          "2", .. null,                     [1L, 2L, 3L],         [null]
          "3", .. ["a", "b", "c"],          null,                 []
          "4", .. ["c", "d"],               [null],               [-1.1, -333.3]
          "5", .. [null],                   [123L, 345L],         null
          "6", .. ["x", "y"],               [100, 200],           [1.1, null, 3.3]
          "7", .. [null, "hello", "world"], [1234, 3456L, null],  [1.23, 4.56, 6.78]
       */
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { "a", "b", "c" }, new Object[] { "a", "b", "c" }, false, false, null), ImmutableList.of("0", "3"));
    assertFilterMatches(NotDimFilter.of(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { "a", "b", "c" }, new Object[] { "a", "b", "c" }, false, false, null)), NullHandling.sqlCompatible() ? ImmutableList.of("1", "4", "5", "6", "7") : ImmutableList.of("1", "2", "4", "5", "6", "7"));
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, null, new Object[] { "a", "b", "c" }, false, false, null), ImmutableList.of("0", "1", "3", "5", "7"));
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { "a", "b", "c" }, null, true, false, null), ImmutableList.of("4", "6"));
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, null, new Object[] { "a", "b", "c" }, false, true, null), ImmutableList.of("1", "5", "7"));
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { "a", "b" }, new Object[] { "a", "b", "c", "d" }, true, true, null), ImmutableList.of("0", "3"));
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, new Object[] { "c", "d" }, new Object[] { "c", "d", "e" }, false, true, null), ImmutableList.of("4"));
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, null, new Object[] {}, false, false, null), ImmutableList.of("1"));
    assertFilterMatches(new RangeFilter("arrayString", ColumnType.STRING_ARRAY, null, new Object[] { null }, false, false, null), ImmutableList.of("1", "5"));
    assertFilterMatches(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, null, new Object[] {}, false, false, null), ImmutableList.of("1"));
    assertFilterMatches(NotDimFilter.of(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, null, new Object[] {}, false, false, null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "2", "4", "5", "6", "7") : ImmutableList.of("0", "2", "3", "4", "5", "6", "7"));
    assertFilterMatches(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, new Object[] {}, null, true, false, null), ImmutableList.of("0", "2", "4", "5", "6", "7"));
    assertFilterMatches(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, null, new Object[] { null }, false, false, null), ImmutableList.of("1", "4"));
    assertFilterMatches(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, new Object[] { 1L, 2L, 3L }, new Object[] { 1L, 2L, 3L }, false, false, null), ImmutableList.of("0", "2"));
    assertFilterMatches(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, null, new Object[] { 1L, 2L, 3L }, false, true, null), ImmutableList.of("1", "4"));
    assertFilterMatches(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, new Object[] { 1L, 2L, 3L }, null, true, false, null), ImmutableList.of("5", "6", "7"));
    // empties and nulls still sort before numbers
    assertFilterMatches(new RangeFilter("arrayLong", ColumnType.LONG_ARRAY, null, new Object[] { -1L }, false, false, null), ImmutableList.of("1", "4"));
    assertFilterMatches(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, null, new Object[] {}, false, false, null), ImmutableList.of("3"));
    assertFilterMatches(NotDimFilter.of(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, null, new Object[] {}, false, false, null)), NullHandling.sqlCompatible() ? ImmutableList.of("0", "1", "2", "4", "6", "7") : ImmutableList.of("0", "1", "2", "4", "5", "6", "7"));
    assertFilterMatches(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, new Object[] {}, null, true, false, null), ImmutableList.of("0", "1", "2", "4", "6", "7"));
    assertFilterMatches(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, null, new Object[] { null }, false, false, null), ImmutableList.of("2", "3"));
    assertFilterMatches(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 2.2, 3.3 }, new Object[] { 1.1, 2.2, 3.3 }, false, false, null), ImmutableList.of("0", "1"));
    assertFilterMatches(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 2.2, 3.3 }, null, true, false, null), ImmutableList.of("7"));
    assertFilterMatches(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, null, new Object[] { 1.1, 2.2, 3.3 }, true, false, null), ImmutableList.of("0", "1", "2", "3", "4", "6"));
    // empties and nulls sort before numbers
    assertFilterMatches(new RangeFilter("arrayDouble", ColumnType.DOUBLE_ARRAY, null, new Object[] { 0.0 }, true, false, null), ImmutableList.of("2", "3", "4"));
}

