    RangeFilter f3 = new RangeFilter("x", ColumnType.STRING, "abc", "xyz", true, true, new FilterTuning(true, null, null));
    Assert.assertArrayEquals(f1.getCacheKey(), f1_2.getCacheKey());
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2.getCacheKey()));
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2_2.getCacheKey()));
    Assert.assertArrayEquals(f1.getCacheKey(), f3.getCacheKey());
    f1 = new RangeFilter("x", ColumnType.LONG, 100L, 300L, true, true, null);
    f1_2 = new RangeFilter("x", ColumnType.LONG, 100, 300, true, true, null);
    f2 = new RangeFilter("x", ColumnType.LONG, 100L, 300L, false, true, null);
    f2_2 = new RangeFilter("x", ColumnType.LONG, 101L, 300L, true, true, null);
    f3 = new RangeFilter("x", ColumnType.LONG, 100L, 300L, true, true, new FilterTuning(true, null, null));
    Assert.assertArrayEquals(f1.getCacheKey(), f1_2.getCacheKey());
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2.getCacheKey()));
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2_2.getCacheKey()));
    Assert.assertArrayEquals(f1.getCacheKey(), f3.getCacheKey());
    f1 = new RangeFilter("x", ColumnType.DOUBLE, -1.1, 1.1, true, true, null);
    f1_2 = new RangeFilter("x", ColumnType.DOUBLE, -1.1, 1.1, true, true, null);
    f2 = new RangeFilter("x", ColumnType.DOUBLE, -1.1, 1.1, false, true, null);
    f2_2 = new RangeFilter("x", ColumnType.DOUBLE, -1.1000000001, 1.1, true, true, null);
    f3 = new RangeFilter("x", ColumnType.DOUBLE, -1.1, 1.1, true, true, new FilterTuning(true, null, null));
    Assert.assertArrayEquals(f1.getCacheKey(), f1_2.getCacheKey());
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2.getCacheKey()));
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2_2.getCacheKey()));
    Assert.assertArrayEquals(f1.getCacheKey(), f3.getCacheKey());
    f1 = new RangeFilter("x", ColumnType.STRING_ARRAY, new Object[] { "a", "b" }, new Object[] { "x", null, "z" }, true, true, null);
    f1_2 = new RangeFilter("x", ColumnType.STRING_ARRAY, Arrays.asList("a", "b"), Arrays.asList("x", null, "z"), true, true, null);
    f2 = new RangeFilter("x", ColumnType.STRING_ARRAY, new Object[] { "a", "b" }, new Object[] { "x", null, "z" }, false, true, null);
    f2_2 = new RangeFilter("x", ColumnType.STRING_ARRAY, new Object[] { "a", "b" }, new Object[] { "x", "z" }, true, true, null);
    f3 = new RangeFilter("x", ColumnType.STRING_ARRAY, new Object[] { "a", "b" }, new Object[] { "x", null, "z" }, true, true, new FilterTuning(true, null, null));
    Assert.assertArrayEquals(f1.getCacheKey(), f1_2.getCacheKey());
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2.getCacheKey()));
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2_2.getCacheKey()));
    Assert.assertArrayEquals(f1.getCacheKey(), f3.getCacheKey());
    f1 = new RangeFilter("x", ColumnType.LONG_ARRAY, new Object[] { 101L, 1L }, new Object[] { 101L, 100L }, true, true, null);
    f1_2 = new RangeFilter("x", ColumnType.LONG_ARRAY, Arrays.asList(101L, 1L), Arrays.asList(101L, 100L), true, true, null);
    f2 = new RangeFilter("x", ColumnType.LONG_ARRAY, new Object[] { 101L, 1L }, new Object[] { 101L, 100L }, false, true, null);
    f2_2 = new RangeFilter("x", ColumnType.LONG_ARRAY, new Object[] { 101L, 1L }, new Object[] { 101L, 99L }, true, true, null);
    f3 = new RangeFilter("x", ColumnType.LONG_ARRAY, new Object[] { 101L, 1L }, new Object[] { 101L, 100L }, true, true, new FilterTuning(true, null, null));
    Assert.assertArrayEquals(f1.getCacheKey(), f1_2.getCacheKey());
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2.getCacheKey()));
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2_2.getCacheKey()));
    Assert.assertArrayEquals(f1.getCacheKey(), f3.getCacheKey());
    f1 = new RangeFilter("x", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, null, 1.2 }, new Object[] { 2.02, 3.03 }, true, true, null);
    f1_2 = new RangeFilter("x", ColumnType.DOUBLE_ARRAY, Arrays.asList(1.1, null, 1.2), Arrays.asList(2.02, 3.03), true, true, null);
    f2 = new RangeFilter("x", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, null, 1.2 }, new Object[] { 2.02, 3.03 }, false, true, null);
    f2_2 = new RangeFilter("x", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, 1.2 }, new Object[] { 2.02, 3.03 }, true, true, null);
    f3 = new RangeFilter("x", ColumnType.DOUBLE_ARRAY, new Object[] { 1.1, null, 1.2 }, new Object[] { 2.02, 3.03 }, true, true, new FilterTuning(true, null, null));
    Assert.assertArrayEquals(f1.getCacheKey(), f1_2.getCacheKey());
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2.getCacheKey()));
    Assert.assertFalse(Arrays.equals(f1.getCacheKey(), f2_2.getCacheKey()));
    Assert.assertArrayEquals(f1.getCacheKey(), f3.getCacheKey());
}

@Test
public void testRequiredColumnRewrite() {
    RangeFilter filter = new RangeFilter("dim0", ColumnType.STRING, "abc", "def", false, false, null);
    RangeFilter filter2 = new RangeFilter("dim1", ColumnType.STRING, "abc", "def", false, false, null);
