@Test
public void testNumericMatchBadParameters() {
    Throwable t = Assert.assertThrows(DruidException.class, () -> new RangeFilter(null, ColumnType.DOUBLE, "1234", "", false, false, null));
    Assert.assertEquals("Invalid range filter, column cannot be null", t.getMessage());
    t = Assert.assertThrows(DruidException.class, () -> new RangeFilter("dim0", null, "1234", "", false, false, null));
    Assert.assertEquals("Invalid range filter on column [dim0], matchValueType cannot be null", t.getMessage());
    t = Assert.assertThrows(DruidException.class, () -> new RangeFilter("dim0", ColumnType.DOUBLE, null, null, false, false, null));
    Assert.assertEquals("Invalid range filter on column [dim0], lower and upper cannot be null at the same time", t.getMessage());
    t = Assert.assertThrows(DruidException.class, () -> new RangeFilter("dim0", ColumnType.DOUBLE, "1234", "", false, false, null));
    Assert.assertEquals("Invalid range filter on column [dim0], upper bound [] cannot be parsed as specified match value type [DOUBLE]", t.getMessage());
    t = Assert.assertThrows(DruidException.class, () -> new RangeFilter("dim0", ColumnType.DOUBLE, "abc", "1234", false, false, null));
    Assert.assertEquals("Invalid range filter on column [dim0], lower bound [abc] cannot be parsed as specified match value type [DOUBLE]", t.getMessage());
}

@Test
public void testGetDimensionRangeSet() {
    RangeFilter filter = new RangeFilter("x", ColumnType.STRING, "abc", "xyz", true, true, null);
    RangeSet<String> set = TreeRangeSet.create();
    set.add(Range.range("abc", BoundType.OPEN, "xyz", BoundType.OPEN));
    Assert.assertEquals(set, filter.getDimensionRangeSet("x"));
    Assert.assertNull(filter.getDimensionRangeSet("y"));
    ExprEval<?> evalLower = ExprEval.ofType(ExpressionType.STRING_ARRAY, new Object[] { "abc", "def" });
    filter = new RangeFilter("x", ColumnType.STRING_ARRAY, evalLower.value(), null, true, false, null);
    set = TreeRangeSet.create();
    set.add(Range.greaterThan(Arrays.deepToString(evalLower.asArray())));
    Assert.assertEquals(set, filter.getDimensionRangeSet("x"));
    Assert.assertNull(filter.getDimensionRangeSet("y"));
}

