@Test
public void testNullDimensionSelectorCanBeBoolean() {
    ConstantMatcherType resultMatchNull = ValueMatchers.toConstantMatcherTypeIfPossible(DimensionSelector.constant(null), false, DruidObjectPredicate.isNull());
    Assert.assertNotNull(resultMatchNull);
    Assert.assertEquals(ConstantMatcherType.ALL_TRUE, resultMatchNull);
    ConstantMatcherType resultMatchNotNull = ValueMatchers.toConstantMatcherTypeIfPossible(DimensionSelector.constant(null), false, DruidObjectPredicate.notNull());
    Assert.assertNotNull(resultMatchNotNull);
    Assert.assertEquals(ConstantMatcherType.ALL_FALSE, resultMatchNotNull);
    ConstantMatcherType resultMatchNullUnknown = ValueMatchers.toConstantMatcherTypeIfPossible(DimensionSelector.constant(null), false, value -> value == null ? DruidPredicateMatch.UNKNOWN : DruidPredicateMatch.of(true));
    Assert.assertNotNull(resultMatchNullUnknown);
    Assert.assertEquals(ConstantMatcherType.ALL_UNKNOWN, resultMatchNullUnknown);
    ConstantMatcherType resultMatchNonNilConstant = ValueMatchers.toConstantMatcherTypeIfPossible(supplierSingleConstant.get().makeDimensionSelector(new SimpleAscendingOffset(1), null), false, DruidObjectPredicate.notNull());
    Assert.assertNotNull(resultMatchNonNilConstant);
    Assert.assertEquals(ConstantMatcherType.ALL_TRUE, resultMatchNonNilConstant);
    ConstantMatcherType resultMatchNonNil = ValueMatchers.toConstantMatcherTypeIfPossible(supplierSingle.get().makeDimensionSelector(new SimpleAscendingOffset(1), null), false, DruidObjectPredicate.notNull());
    Assert.assertNull(resultMatchNonNil);
    ConstantMatcherType resultMatchNonNilMulti = ValueMatchers.toConstantMatcherTypeIfPossible(supplierMulti.get().makeDimensionSelector(new SimpleAscendingOffset(1), null), true, DruidObjectPredicate.notNull());
    Assert.assertNull(resultMatchNonNilMulti);
}

