@Test
public void testSanity() throws Exception {
    IncrementalIndex index = indexCreator.createIndex();
    index.add(new MapBasedInputRow(System.currentTimeMillis() - 1, Collections.singletonList("billy"), ImmutableMap.of("billy", "hi")));
    index.add(new MapBasedInputRow(System.currentTimeMillis() - 1, Collections.singletonList("sally"), ImmutableMap.of("sally", "bo")));
    try (CloseableStupidPool<ByteBuffer> pool = new CloseableStupidPool<>("GroupByQueryEngine-bufferPool", () -> ByteBuffer.allocate(50000));
        ResourceHolder<ByteBuffer> processingBuffer = pool.take()) {
        final GroupByQuery query = GroupByQuery.builder().setDataSource("test").setGranularity(Granularities.ALL).setInterval(new Interval(DateTimes.EPOCH, DateTimes.nowUtc())).addDimension("billy").addDimension("sally").addAggregator(new LongSumAggregatorFactory("cnt", "cnt")).addOrderByColumn("billy").build();
        final Filter filter = Filters.convertToCNFFromQueryContext(query, Filters.toFilter(query.getFilter()));
        final Interval interval = Iterables.getOnlyElement(query.getIntervals());
        final Sequence<ResultRow> rows = GroupByQueryEngine.process(query, new IncrementalIndexStorageAdapter(index), processingBuffer.get(), null, new GroupByQueryConfig(), new DruidProcessingConfig(), filter, interval, null);
        final List<ResultRow> results = rows.toList();
        Assert.assertEquals(2, results.size());
        ResultRow row = results.get(0);
        Assert.assertArrayEquals(new Object[] { NullHandling.defaultStringValue(), "bo", 1L }, row.getArray());
        row = results.get(1);
        Assert.assertArrayEquals(new Object[] { "hi", NullHandling.defaultStringValue(), 1L }, row.getArray());
    }
}

