@Test
public void testMerge() {
    Assert.assertNull(Metadata.merge(null, null));
    Assert.assertNull(Metadata.merge(ImmutableList.of(), null));
    List<Metadata> metadataToBeMerged = new ArrayList<>();
    metadataToBeMerged.add(null);
    Assert.assertNull(Metadata.merge(metadataToBeMerged, null));
    //sanity merge check
    AggregatorFactory[] aggs = new AggregatorFactory[] { new LongMaxAggregatorFactory("n", "f") };
    final Metadata m1 = new Metadata(Collections.singletonMap("k", "v"), aggs, new TimestampSpec("ds", "auto", null), Granularities.ALL, Boolean.FALSE);
    final Metadata m2 = new Metadata(Collections.singletonMap("k", "v"), aggs, new TimestampSpec("ds", "auto", null), Granularities.ALL, Boolean.FALSE);
    final Metadata m3 = new Metadata(Collections.singletonMap("k", "v"), aggs, new TimestampSpec("ds", "auto", null), Granularities.ALL, Boolean.TRUE);
    final Metadata merged = new Metadata(Collections.singletonMap("k", "v"), new AggregatorFactory[] { new LongMaxAggregatorFactory("n", "n") }, new TimestampSpec("ds", "auto", null), Granularities.ALL, Boolean.FALSE);
    Assert.assertEquals(merged, Metadata.merge(ImmutableList.of(m1, m2), null));
    //merge check with one metadata being null
    metadataToBeMerged.clear();
    metadataToBeMerged.add(m1);
    metadataToBeMerged.add(m2);
    metadataToBeMerged.add(null);
    final Metadata merged2 = new Metadata(Collections.singletonMap("k", "v"), null, null, null, null);
    Assert.assertEquals(merged2, Metadata.merge(metadataToBeMerged, null));
    //merge check with client explicitly providing merged aggregators
    AggregatorFactory[] explicitAggs = new AggregatorFactory[] { new DoubleMaxAggregatorFactory("x", "y") };
    final Metadata merged3 = new Metadata(Collections.singletonMap("k", "v"), explicitAggs, null, null, null);
    Assert.assertEquals(merged3, Metadata.merge(metadataToBeMerged, explicitAggs));
    final Metadata merged4 = new Metadata(Collections.singletonMap("k", "v"), explicitAggs, new TimestampSpec("ds", "auto", null), Granularities.ALL, null);
    Assert.assertEquals(merged4, Metadata.merge(ImmutableList.of(m3, m2), explicitAggs));
}

@Test
public void testIdLookup() throws IOException {
    // add some values
    ValueDictionary dictionary = new ValueDictionary();
    dictionary.addStringValue("hello");
    dictionary.addStringValue("world");
    dictionary.addStringValue(null);
    dictionary.addLongValue(123L);
    dictionary.addLongValue(-123L);
    dictionary.addDoubleValue(1.234);
    dictionary.addDoubleValue(0.001);
    dictionary.addStringArray(new Object[] { "hello", "world" });
    dictionary.addLongArray(new Object[] { 1L, 2L, 3L });
    dictionary.addDoubleArray(new Object[] { 0.01, -1.234, 0.001, 1.234 });
    // sort them
    SortedValueDictionary sortedValueDictionary = dictionary.getSortedCollector();
    // setup dictionary writers
    SegmentWriteOutMedium medium = TmpFileSegmentWriteOutMediumFactory.instance().makeSegmentWriteOutMedium(temp.newFolder());
    DictionaryWriter<String> stringWriter = StringEncodingStrategies.getStringDictionaryWriter(new StringEncodingStrategy.FrontCoded(4, (byte) 1), medium, "test");
    FixedIndexedWriter<Long> longWriter = new FixedIndexedWriter<>(medium, TypeStrategies.LONG, ByteOrder.nativeOrder(), Long.BYTES, true);
    FixedIndexedWriter<Double> doubleWriter = new FixedIndexedWriter<>(medium, TypeStrategies.DOUBLE, ByteOrder.nativeOrder(), Double.BYTES, true);
    FrontCodedIntArrayIndexedWriter arrayWriter = new FrontCodedIntArrayIndexedWriter(medium, ByteOrder.nativeOrder(), 4);
    Path dictTempPath = temp.newFolder().toPath();
    // make lookup with references to writers
    DictionaryIdLookup idLookup = new DictionaryIdLookup("test", dictTempPath, stringWriter, longWriter, doubleWriter, arrayWriter);
    // write the stuff
    stringWriter.open();
    longWriter.open();
    doubleWriter.open();
    arrayWriter.open();
    File tempDir = dictTempPath.toFile();
    Assert.assertEquals(0, tempDir.listFiles().length);
    for (String s : sortedValueDictionary.getSortedStrings()) {
        stringWriter.write(s);
    }
    for (Long l : sortedValueDictionary.getSortedLongs()) {
        longWriter.write(l);
    }
    for (Double d : sortedValueDictionary.getSortedDoubles()) {
        doubleWriter.write(d);
    }
    Iterable<int[]> sortedArrays = () -> new AutoTypeColumnMerger.ArrayDictionaryMergingIterator(new Iterable[] { sortedValueDictionary.getSortedArrays() }, idLookup);
    Assert.assertEquals(0, tempDir.listFiles().length);
    // looking up some values pulls in string dictionary and long dictionary
    Assert.assertEquals(0, idLookup.lookupString(null));
    Assert.assertEquals(1, idLookup.lookupString("hello"));
    Assert.assertEquals(2, idLookup.lookupString("world"));
    Assert.assertEquals(3, idLookup.lookupLong(-123L));
    Assert.assertEquals(2, tempDir.listFiles().length);
    // writing arrays needs to use the lookups for lower value dictionaries, so will create string, long, and double
    // temp dictionary files
    for (int[] arr : sortedArrays) {
        arrayWriter.write(arr);
    }
    Assert.assertEquals(3, tempDir.listFiles().length);
    if (NullHandling.sqlCompatible()) {
        Assert.assertEquals(8, idLookup.lookupDouble(-1.234));
        Assert.assertEquals(11, idLookup.lookupDouble(1.234));
        Assert.assertEquals(3, tempDir.listFiles().length);
        // looking up arrays pulls in array file
        Assert.assertEquals(12, idLookup.lookupArray(new int[] { 1, 2 }));
        Assert.assertEquals(13, idLookup.lookupArray(new int[] { 4, 5, 6 }));
        Assert.assertEquals(14, idLookup.lookupArray(new int[] { 10, 8, 9, 11 }));
        Assert.assertEquals(4, tempDir.listFiles().length);
    } else {
        // default value mode sticks zeros in dictionary even if not present in column because of .. reasons
        Assert.assertEquals(9, idLookup.lookupDouble(-1.234));
        Assert.assertEquals(13, idLookup.lookupDouble(1.234));
        Assert.assertEquals(3, tempDir.listFiles().length);
        // looking up arrays pulls in array file
        Assert.assertEquals(14, idLookup.lookupArray(new int[] { 1, 2 }));
        Assert.assertEquals(15, idLookup.lookupArray(new int[] { 5, 6, 7 }));
        Assert.assertEquals(16, idLookup.lookupArray(new int[] { 12, 9, 11, 13 }));
        Assert.assertEquals(4, tempDir.listFiles().length);
    }
    // close it removes all the temp files
    idLookup.close();
    Assert.assertEquals(0, tempDir.listFiles().length);
}

