    // Verify size delta with repeated dimension value
    totalEstimatedSize += verifyEncodedValues(indexer, "abc", new int[] { 0 }, 20L);
    // Verify size delta with newly added dimension value
    totalEstimatedSize += verifyEncodedValues(indexer, "def", new int[] { 2 }, 86L);
    // Verify size delta for multi-values
    totalEstimatedSize += verifyEncodedValues(indexer, Arrays.asList("abc", "def", "ghi"), new int[] { 0, 2, 3 }, 94L);
    Assert.assertEquals(306L, totalEstimatedSize);
}

