    Assert.assertFalse(DeferExpressionDimensions.SINGLE_STRING.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    // innately deferrable
    Assert.assertFalse(DeferExpressionDimensions.FIXED_WIDTH_NON_NUMERIC.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    Assert.assertFalse(DeferExpressionDimensions.FIXED_WIDTH.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    // multiple input columns
    thePlan = plan("concat(scalar_dictionary_string, scalar_dictionary_string_nonunique)");
    Assert.assertTrue(thePlan.is(ExpressionPlan.Trait.VECTORIZABLE));
    Assert.assertFalse(thePlan.is(ExpressionPlan.Trait.SINGLE_INPUT_SCALAR, ExpressionPlan.Trait.SINGLE_INPUT_MAPPABLE, ExpressionPlan.Trait.INCOMPLETE_INPUTS, ExpressionPlan.Trait.UNKNOWN_INPUTS, ExpressionPlan.Trait.NEEDS_APPLIED, ExpressionPlan.Trait.NON_SCALAR_INPUTS, ExpressionPlan.Trait.NON_SCALAR_OUTPUT));
    Assert.assertEquals("concat(\"scalar_dictionary_string\", \"scalar_dictionary_string_nonunique\")", thePlan.getAppliedExpression().stringify());
    Assert.assertEquals("concat(\"scalar_dictionary_string\", \"scalar_dictionary_string_nonunique\")", thePlan.getAppliedFoldExpression("__acc").stringify());
    // what if scalar_dictionary_string_nonunique is an accumulator instead? nope, still no NEEDS_APPLIED so nothing to do
    Assert.assertEquals("concat(\"scalar_dictionary_string\", \"scalar_dictionary_string_nonunique\")", thePlan.getAppliedFoldExpression("scalar_dictionary_string_nonunique").stringify());
    Assert.assertEquals(ExpressionType.STRING, thePlan.getOutputType());
    inferred = thePlan.inferColumnCapabilities(null);
    Assert.assertNotNull(inferred);
    Assert.assertEquals(ValueType.STRING, inferred.getType());
    Assert.assertTrue(inferred.hasNulls().isTrue());
    Assert.assertFalse(inferred.isDictionaryEncoded().isMaybeTrue());
    Assert.assertFalse(inferred.areDictionaryValuesSorted().isMaybeTrue());
    Assert.assertFalse(inferred.areDictionaryValuesUnique().isMaybeTrue());
    Assert.assertFalse(inferred.hasMultipleValues().isMaybeTrue());
    Assert.assertFalse(inferred.hasBitmapIndexes());
    Assert.assertFalse(inferred.hasSpatialIndexes());
    Assert.assertFalse(DeferExpressionDimensions.SINGLE_STRING.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    Assert.assertTrue(DeferExpressionDimensions.FIXED_WIDTH_NON_NUMERIC.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    Assert.assertTrue(DeferExpressionDimensions.FIXED_WIDTH.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    // array output of dictionary encoded string are not considered single scalar/mappable, nor vectorizable
    thePlan = plan("array(scalar_dictionary_string)");
    Assert.assertTrue(thePlan.is(ExpressionPlan.Trait.NON_SCALAR_OUTPUT));
    Assert.assertFalse(thePlan.is(ExpressionPlan.Trait.INCOMPLETE_INPUTS, ExpressionPlan.Trait.UNKNOWN_INPUTS, ExpressionPlan.Trait.NEEDS_APPLIED, ExpressionPlan.Trait.NON_SCALAR_INPUTS, ExpressionPlan.Trait.SINGLE_INPUT_SCALAR, ExpressionPlan.Trait.SINGLE_INPUT_MAPPABLE, ExpressionPlan.Trait.VECTORIZABLE));
    Assert.assertFalse(DeferExpressionDimensions.SINGLE_STRING.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    Assert.assertTrue(DeferExpressionDimensions.FIXED_WIDTH_NON_NUMERIC.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
    Assert.assertTrue(DeferExpressionDimensions.FIXED_WIDTH.useDeferredGroupBySelector(thePlan, thePlan.getAnalysis().getRequiredBindingsList(), SYNTHETIC_INSPECTOR));
}

