    // {Earth} * {USA} * (New York, INF)
    populateDomain(domain, getRangeSet(Range.singleton("Earth")), // EffectiveDomain[:1] == {Earth} == {start[:1]} == {end[:1]}
    getRangeSet(Range.singleton("USA")), // EffectiveDomain[:2] == {<Earth, USA>} == {end[:2]}
