@Test
public void testIsOvershadowed() {
    final SegmentTimeline timeline = SegmentTimeline.forSegments(Arrays.asList(createSegment("2022-01-01/2022-01-02", "v1", 0, 3), createSegment("2022-01-01/2022-01-02", "v1", 1, 3), createSegment("2022-01-01/2022-01-02", "v1", 2, 3), createSegment("2022-01-02/2022-01-03", "v2", 0, 2), createSegment("2022-01-02/2022-01-03", "v2", 1, 2)));
    Assert.assertFalse(timeline.isOvershadowed(createSegment("2022-01-01/2022-01-02", "v1", 1, 3)));
    Assert.assertFalse(timeline.isOvershadowed(createSegment("2022-01-01/2022-01-02", "v1", 2, 3)));
    Assert.assertFalse(timeline.isOvershadowed(createSegment("2022-01-01/2022-01-02", "v1", 1, 4)));
    Assert.assertFalse(timeline.isOvershadowed(createSegment("2022-01-01T00:00:00/2022-01-01T06:00:00", "v1", 1, 4)));
    Assert.assertTrue(timeline.isOvershadowed(createSegment("2022-01-02/2022-01-03", "v1", 2, 4)));
    Assert.assertTrue(timeline.isOvershadowed(createSegment("2022-01-02/2022-01-03", "v1", 0, 1)));
}

