@Test
public void testTimeoutWhileCallingFuture() {
    Future<InputStream> future = new AbstractFuture<InputStream>() {

        @Override
        public InputStream get(long timeout, TimeUnit unit) throws InterruptedException {
            // Sleep longer than timeout
            Thread.sleep(2000);
            // should return null so that JsonParserIterator checks timeout
            return null;
        }
    };
    JsonParserIterator<?> iterator = new JsonParserIterator<>(JAVA_TYPE, future, URL, // timeout in 500 ms
    mockQuery("qid", System.currentTimeMillis() + 500L), HOST, OBJECT_MAPPER);
    expectedException.expect(QueryTimeoutException.class);
    expectedException.expectMessage(StringUtils.format("url[%s] timed out", URL));
    iterator.hasNext();
}

@Test
public void testTimeoutAfterCallingFuture() {
    ExecutorService service = Execs.singleThreaded("timeout-test");
    try {
        JsonParserIterator<?> iterator = new JsonParserIterator<>(JAVA_TYPE, service.submit(() -> {
            // Sleep longer than timeout
            Thread.sleep(2000);
            return null;
        }), URL, // timeout in 500 ms
        mockQuery("qid", System.currentTimeMillis() + 500L), HOST, OBJECT_MAPPER);
        expectedException.expect(QueryTimeoutException.class);
        expectedException.expectMessage("Query [qid] timed out");
        iterator.hasNext();
    } finally {
        service.shutdownNow();
    }
}

