        pendingSegmentsForTask.add(new PendingSegmentRecord(SegmentIdWithShardSpec.fromDataSegment(segment), v1, segment.getId().toString(), null, taskAllocatorId));
        // Add upgraded pending segment
        pendingSegmentsForTask.add(new PendingSegmentRecord(new SegmentIdWithShardSpec(DS.WIKI, Intervals.of("2023-01-01/2023-02-01"), alreadyUpgradedVersion, new NumberedShardSpec(i, 0)), alreadyUpgradedVersion, segment.getId().toString(), segment.getId().toString(), taskAllocatorId));
    }
    for (int i = 0; i < 10; i++) {
        final DataSegment segment = createSegment(Intervals.of("2023-01-02/2023-01-03"), v2, new LinearShardSpec(i));
        appendSegments.add(segment);
        expectedSegmentsToUpgrade.add(segment);
        // Add the same segment
        pendingSegmentsForTask.add(new PendingSegmentRecord(SegmentIdWithShardSpec.fromDataSegment(segment), v2, segment.getId().toString(), null, taskAllocatorId));
        // Add upgraded pending segment
        pendingSegmentsForTask.add(new PendingSegmentRecord(new SegmentIdWithShardSpec(DS.WIKI, Intervals.of("2023-01-01/2023-02-01"), alreadyUpgradedVersion, new NumberedShardSpec(10 + i, 0)), alreadyUpgradedVersion, segment.getId().toString(), segment.getId().toString(), taskAllocatorId));
    }
    for (int i = 0; i < 10; i++) {
        final DataSegment segment = createSegment(Intervals.of("2023-01-03/2023-01-04"), v3, new LinearShardSpec(i));
        appendSegments.add(segment);
        // Add the same segment
        pendingSegmentsForTask.add(new PendingSegmentRecord(SegmentIdWithShardSpec.fromDataSegment(segment), v3, segment.getId().toString(), null, taskAllocatorId));
        // Add upgraded pending segment
        pendingSegmentsForTask.add(new PendingSegmentRecord(new SegmentIdWithShardSpec(DS.WIKI, Intervals.of("2023-01-01/2023-02-01"), alreadyUpgradedVersion, new NumberedShardSpec(20 + i, 0)), alreadyUpgradedVersion, segment.getId().toString(), segment.getId().toString(), taskAllocatorId));
    }
    derbyConnector.retryWithHandle(handle -> coordinator.insertPendingSegmentsIntoMetastore(handle, pendingSegmentsForTask, DS.WIKI, false));
    final Map<DataSegment, ReplaceTaskLock> segmentToReplaceLock = expectedSegmentsToUpgrade.stream().collect(Collectors.toMap(s -> s, s -> replaceLock));
    // Commit the segment and verify the results
    SegmentPublishResult commitResult = coordinator.commitAppendSegments(appendSegments, segmentToReplaceLock, taskAllocatorId, null);
    Assert.assertTrue(commitResult.isSuccess());
    Set<DataSegment> allCommittedSegments = new HashSet<>(retrieveUsedSegments(derbyConnectorRule.metadataTablesConfigSupplier().get()));
    Map<String, String> upgradedFromSegmentIdMap = coordinator.retrieveUpgradedFromSegmentIds(DS.WIKI, allCommittedSegments.stream().map(DataSegment::getId).map(SegmentId::toString).collect(Collectors.toSet()));
    // Verify the segments present in the metadata store
    Assert.assertTrue(allCommittedSegments.containsAll(appendSegments));
    for (DataSegment segment : appendSegments) {
        Assert.assertNull(upgradedFromSegmentIdMap.get(segment.getId().toString()));
    }
    allCommittedSegments.removeAll(appendSegments);
    // Verify the commit of upgraded pending segments
    Assert.assertEquals(appendSegments.size(), allCommittedSegments.size());
    Map<String, DataSegment> segmentMap = new HashMap<>();
    for (DataSegment segment : appendSegments) {
        segmentMap.put(segment.getId().toString(), segment);
    }
    for (DataSegment segment : allCommittedSegments) {
        for (PendingSegmentRecord pendingSegmentRecord : pendingSegmentsForTask) {
            if (pendingSegmentRecord.getId().asSegmentId().toString().equals(segment.getId().toString())) {
                DataSegment upgradedFromSegment = segmentMap.get(pendingSegmentRecord.getUpgradedFromSegmentId());
                Assert.assertNotNull(upgradedFromSegment);
                Assert.assertEquals(segment.getLoadSpec(), upgradedFromSegment.getLoadSpec());
                Assert.assertEquals(pendingSegmentRecord.getUpgradedFromSegmentId(), upgradedFromSegmentIdMap.get(segment.getId().toString()));
            }
        }
    }
    // Verify entries in the segment task lock table
    final Set<String> expectedUpgradeSegmentIds = expectedSegmentsToUpgrade.stream().map(s -> s.getId().toString()).collect(Collectors.toSet());
    final Map<String, String> observedSegmentToLock = getSegmentsCommittedDuringReplaceTask(replaceTaskId, derbyConnectorRule.metadataTablesConfigSupplier().get());
    Assert.assertEquals(expectedUpgradeSegmentIds, observedSegmentToLock.keySet());
    final Set<String> observedLockVersions = new HashSet<>(observedSegmentToLock.values());
    Assert.assertEquals(1, observedLockVersions.size());
    Assert.assertEquals(replaceLock.getVersion(), Iterables.getOnlyElement(observedLockVersions));
}

@Test
public void testCommitReplaceSegments() {
    final ReplaceTaskLock replaceLock = new ReplaceTaskLock("g1", Intervals.of("2023-01-01/2023-02-01"), "2023-02-01");
    final Set<DataSegment> segmentsAppendedWithReplaceLock = new HashSet<>();
    final Map<DataSegment, ReplaceTaskLock> appendedSegmentToReplaceLockMap = new HashMap<>();
    final PendingSegmentRecord pendingSegmentInInterval = new PendingSegmentRecord(new SegmentIdWithShardSpec("foo", Intervals.of("2023-01-01/2023-01-02"), "2023-01-02", new NumberedShardSpec(100, 0)), "", "", null, "append");
    final PendingSegmentRecord pendingSegmentOutsideInterval = new PendingSegmentRecord(new SegmentIdWithShardSpec("foo", Intervals.of("2023-04-01/2023-04-02"), "2023-01-02", new NumberedShardSpec(100, 0)), "", "", null, "append");
    for (int i = 1; i < 9; i++) {
        final DataSegment segment = new DataSegment("foo", Intervals.of("2023-01-0" + i + "/2023-01-0" + (i + 1)), "2023-01-0" + i, ImmutableMap.of("path", "a-" + i), ImmutableList.of("dim1"), ImmutableList.of("m1"), new LinearShardSpec(0), 9, 100);
        segmentsAppendedWithReplaceLock.add(segment);
        appendedSegmentToReplaceLockMap.put(segment, replaceLock);
    }
    segmentSchemaTestUtils.insertUsedSegments(segmentsAppendedWithReplaceLock, Collections.emptyMap());
    derbyConnector.retryWithHandle(handle -> coordinator.insertPendingSegmentsIntoMetastore(handle, ImmutableList.of(pendingSegmentInInterval, pendingSegmentOutsideInterval), "foo", true));
    insertIntoUpgradeSegmentsTable(appendedSegmentToReplaceLockMap, derbyConnectorRule.metadataTablesConfigSupplier().get());
    final Set<DataSegment> replacingSegments = new HashSet<>();
    for (int i = 1; i < 9; i++) {
        final DataSegment segment = new DataSegment("foo", Intervals.of("2023-01-01/2023-02-01"), "2023-02-01", ImmutableMap.of("path", "b-" + i), ImmutableList.of("dim1"), ImmutableList.of("m1"), new NumberedShardSpec(i, 9), 9, 100);
        replacingSegments.add(segment);
    }
    coordinator.commitReplaceSegments(replacingSegments, ImmutableSet.of(replaceLock), null);
    Assert.assertEquals(2L * segmentsAppendedWithReplaceLock.size() + replacingSegments.size(), retrieveUsedSegmentIds(derbyConnectorRule.metadataTablesConfigSupplier().get()).size());
    final Set<DataSegment> usedSegments = new HashSet<>(retrieveUsedSegments(derbyConnectorRule.metadataTablesConfigSupplier().get()));
    final Map<String, String> upgradedFromSegmentIdMap = coordinator.retrieveUpgradedFromSegmentIds("foo", usedSegments.stream().map(DataSegment::getId).map(SegmentId::toString).collect(Collectors.toSet()));
    Assert.assertTrue(usedSegments.containsAll(segmentsAppendedWithReplaceLock));
    for (DataSegment appendSegment : segmentsAppendedWithReplaceLock) {
        Assert.assertNull(upgradedFromSegmentIdMap.get(appendSegment.getId().toString()));
    }
    usedSegments.removeAll(segmentsAppendedWithReplaceLock);
    Assert.assertTrue(usedSegments.containsAll(replacingSegments));
    for (DataSegment replaceSegment : replacingSegments) {
        Assert.assertNull(upgradedFromSegmentIdMap.get(replaceSegment.getId().toString()));
    }
    usedSegments.removeAll(replacingSegments);
    Assert.assertEquals(segmentsAppendedWithReplaceLock.size(), usedSegments.size());
    for (DataSegment segmentReplicaWithNewVersion : usedSegments) {
        boolean hasBeenCarriedForward = false;
        for (DataSegment appendedSegment : segmentsAppendedWithReplaceLock) {
            if (appendedSegment.getLoadSpec().equals(segmentReplicaWithNewVersion.getLoadSpec())) {
                Assert.assertEquals(appendedSegment.getId().toString(), upgradedFromSegmentIdMap.get(segmentReplicaWithNewVersion.getId().toString()));
                hasBeenCarriedForward = true;
                break;
            }
        }
        Assert.assertTrue(hasBeenCarriedForward);
    }
    List<PendingSegmentRecord> pendingSegmentsInInterval = coordinator.getPendingSegments("foo", Intervals.of("2023-01-01/2023-02-01"));
    Assert.assertEquals(2, pendingSegmentsInInterval.size());
    final SegmentId rootPendingSegmentId = pendingSegmentInInterval.getId().asSegmentId();
    if (pendingSegmentsInInterval.get(0).getUpgradedFromSegmentId() == null) {
        Assert.assertEquals(rootPendingSegmentId, pendingSegmentsInInterval.get(0).getId().asSegmentId());
        Assert.assertEquals(rootPendingSegmentId.toString(), pendingSegmentsInInterval.get(1).getUpgradedFromSegmentId());
    } else {
        Assert.assertEquals(rootPendingSegmentId, pendingSegmentsInInterval.get(1).getId().asSegmentId());
        Assert.assertEquals(rootPendingSegmentId.toString(), pendingSegmentsInInterval.get(0).getUpgradedFromSegmentId());
    }
    List<PendingSegmentRecord> pendingSegmentsOutsideInterval = coordinator.getPendingSegments("foo", Intervals.of("2023-04-01/2023-05-01"));
    Assert.assertEquals(1, pendingSegmentsOutsideInterval.size());
    Assert.assertEquals(pendingSegmentOutsideInterval.getId().asSegmentId(), pendingSegmentsOutsideInterval.get(0).getId().asSegmentId());
}

