    Assert.assertEquals(oddYearSegments.size(), actualUnusedSegmentsPlus1.size());
    final ImmutableList<DataSegment> actualUnusedSegments2 = retrieveUnusedSegments(ImmutableList.of(interval), null, null, null, maxUsedStatusLastUpdatedTime2, derbyConnectorRule.metadataTablesConfigSupplier().get());
