@Test
public void testRetrieveUnusedSegmentsWithVersions() {
    final DateTime now = DateTimes.nowUtc();
    final String v1 = now.toString();
    final String v2 = now.plusDays(2).toString();
    final String v3 = now.plusDays(3).toString();
    final String v4 = now.plusDays(4).toString();
    final DataSegment segment1 = createSegment(Intervals.of("2023-01-01/2023-01-02"), v1, new LinearShardSpec(0));
    final DataSegment segment2 = createSegment(Intervals.of("2023-01-02/2023-01-03"), v2, new LinearShardSpec(0));
    final DataSegment segment3 = createSegment(Intervals.of("2023-01-03/2023-01-04"), v3, new LinearShardSpec(0));
    final DataSegment segment4 = createSegment(Intervals.of("2023-01-03/2023-01-04"), v4, new LinearShardSpec(0));
    final ImmutableSet<DataSegment> unusedSegments = ImmutableSet.of(segment1, segment2, segment3, segment4);
    Assert.assertEquals(unusedSegments, coordinator.commitSegments(unusedSegments, null));
    markAllSegmentsUnused(unusedSegments, DateTimes.nowUtc());
    for (DataSegment unusedSegment : unusedSegments) {
        Assertions.assertThat(coordinator.retrieveUnusedSegmentsForInterval(DS.WIKI, Intervals.of("2023-01-01/2023-01-04"), ImmutableList.of(unusedSegment.getVersion()), null, null)).contains(unusedSegment);
    }
    Assertions.assertThat(coordinator.retrieveUnusedSegmentsForInterval(DS.WIKI, Intervals.of("2023-01-01/2023-01-04"), ImmutableList.of(v1, v2), null, null)).contains(segment1, segment2);
    Assertions.assertThat(coordinator.retrieveUnusedSegmentsForInterval(DS.WIKI, Intervals.of("2023-01-01/2023-01-04"), null, null, null)).containsAll(unusedSegments);
    Assertions.assertThat(coordinator.retrieveUnusedSegmentsForInterval(DS.WIKI, Intervals.of("2023-01-01/2023-01-04"), ImmutableList.of("some-non-existent-version"), null, null)).containsAll(ImmutableSet.of());
}

