@Test
public void testIsTransientException() {
    MetadataStorageConnectorConfig config = MetadataStorageConnectorConfig.create("connectURI", "user", "password", Collections.emptyMap());
    TestSQLMetadataConnector metadataConnector = new TestSQLMetadataConnector(Suppliers.ofInstance(config), Suppliers.ofInstance(tablesConfig), CentralizedDatasourceSchemaConfig.create());
    // Transient exceptions
    Assert.assertTrue(metadataConnector.isTransientException(new RetryTransactionException("")));
    Assert.assertTrue(metadataConnector.isTransientException(new SQLRecoverableException()));
    Assert.assertTrue(metadataConnector.isTransientException(new SQLTransientException()));
    Assert.assertTrue(metadataConnector.isTransientException(new SQLTransientConnectionException()));
    // Non transient exceptions
    Assert.assertFalse(metadataConnector.isTransientException(null));
    Assert.assertFalse(metadataConnector.isTransientException(new SQLException()));
    Assert.assertFalse(metadataConnector.isTransientException(new UnableToExecuteStatementException("")));
    // Nested transient exceptions
    Assert.assertTrue(metadataConnector.isTransientException(new CallbackFailedException(new SQLTransientException())));
    Assert.assertTrue(metadataConnector.isTransientException(new UnableToObtainConnectionException(new SQLException())));
    Assert.assertTrue(metadataConnector.isTransientException(new UnableToExecuteStatementException(new SQLTransientException())));
    // Nested non-transient exceptions
    Assert.assertFalse(metadataConnector.isTransientException(new CallbackFailedException(new SQLException())));
    Assert.assertFalse(metadataConnector.isTransientException(new UnableToExecuteStatementException(new SQLException())));
}

