@Test
public void testGetUnusedSegmentIntervals() throws IOException {
    publishWikiSegments();
    sqlSegmentsMetadataManager.startPollingDatabasePeriodically();
    sqlSegmentsMetadataManager.poll();
    // Allow null values of used_status_last_updated to test upgrade from older Druid versions
    allowUsedFlagLastUpdatedToBeNullable();
    Assert.assertTrue(sqlSegmentsMetadataManager.isPollingDatabasePeriodically());
    int numChangedSegments = sqlSegmentsMetadataManager.markAsUnusedAllSegmentsInDataSource(DS.WIKI);
    Assert.assertEquals(2, numChangedSegments);
    // Publish an unused segment with used_status_last_updated 2 hours ago
    final DataSegment koalaSegment1 = createSegment(DS.KOALA, "2017-10-15T00:00:00.000/2017-10-16T00:00:00.000", "2017-10-15T20:19:12.565Z");
    publishUnusedSegments(koalaSegment1);
    derbyConnectorRule.segments().updateUsedStatusLastUpdated(koalaSegment1.getId().toString(), DateTimes.nowUtc().minus(Duration.standardHours(2)));
    // Publish an unused segment with used_status_last_updated 2 days ago
    final DataSegment koalaSegment2 = createSegment(DS.KOALA, "2017-10-16T00:00:00.000/2017-10-17T00:00:00.000", "2017-10-15T20:19:12.565Z");
    publishUnusedSegments(koalaSegment2);
    derbyConnectorRule.segments().updateUsedStatusLastUpdated(koalaSegment2.getId().toString(), DateTimes.nowUtc().minus(Duration.standardDays(2)));
    // Publish an unused segment and set used_status_last_updated to null
    final DataSegment koalaSegment3 = createSegment(DS.KOALA, "2017-10-17T00:00:00.000/2017-10-18T00:00:00.000", "2017-10-15T20:19:12.565Z");
    publishUnusedSegments(koalaSegment3);
    updateUsedStatusLastUpdatedToNull(koalaSegment3);
    Assert.assertEquals(ImmutableList.of(wikiSegment2.getInterval()), sqlSegmentsMetadataManager.getUnusedSegmentIntervals(DS.WIKI, null, DateTimes.of("3000"), 1, DateTimes.COMPARE_DATE_AS_STRING_MAX));
    // Test the DateTime maxEndTime argument of getUnusedSegmentIntervals
    Assert.assertEquals(ImmutableList.of(wikiSegment2.getInterval()), sqlSegmentsMetadataManager.getUnusedSegmentIntervals(DS.WIKI, null, DateTimes.of(2012, 1, 7, 0, 0), 1, DateTimes.COMPARE_DATE_AS_STRING_MAX));
    Assert.assertEquals(ImmutableList.of(wikiSegment1.getInterval()), sqlSegmentsMetadataManager.getUnusedSegmentIntervals(DS.WIKI, DateTimes.of(2012, 1, 7, 0, 0), DateTimes.of(2012, 4, 7, 0, 0), 1, DateTimes.COMPARE_DATE_AS_STRING_MAX));
    Assert.assertEquals(ImmutableList.of(), sqlSegmentsMetadataManager.getUnusedSegmentIntervals(DS.WIKI, DateTimes.of(2012, 1, 7, 0, 0), DateTimes.of(2012, 1, 7, 0, 0), 1, DateTimes.COMPARE_DATE_AS_STRING_MAX));
    Assert.assertEquals(ImmutableList.of(wikiSegment2.getInterval(), wikiSegment1.getInterval()), sqlSegmentsMetadataManager.getUnusedSegmentIntervals(DS.WIKI, null, DateTimes.of("3000"), 5, DateTimes.COMPARE_DATE_AS_STRING_MAX));
    // Test a buffer period that should exclude some segments
    // The wikipedia datasource has segments generated with last used time equal to roughly the time of test run. None of these segments should be selected with a bufer period of 1 day
    Assert.assertEquals(ImmutableList.of(), sqlSegmentsMetadataManager.getUnusedSegmentIntervals(DS.WIKI, DateTimes.COMPARE_DATE_AS_STRING_MIN, DateTimes.of("3000"), 5, DateTimes.nowUtc().minus(Duration.parse("PT86400S"))));
    // koalaSegment3 has a null used_status_last_updated which should mean getUnusedSegmentIntervals never returns it
    // koalaSegment2 has a used_status_last_updated older than 1 day which means it should be returned
    // The last of the 3 segments in koala has a used_status_last_updated date less than one day and should not be returned
    Assert.assertEquals(ImmutableList.of(koalaSegment2.getInterval()), sqlSegmentsMetadataManager.getUnusedSegmentIntervals(DS.KOALA, DateTimes.COMPARE_DATE_AS_STRING_MIN, DateTimes.of("3000"), 5, DateTimes.nowUtc().minus(Duration.parse("PT86400S"))));
}

