    pluses.add(new SegmentSchemaManager.SegmentSchemaMetadataPlus(segment2.getId(), fingerprintGenerator.generateFingerprint(new SchemaPayload(index2StorageAdaptor.getRowSignature()), segment1.getDataSource(), CentralizedDatasourceSchemaConfig.SCHEMA_VERSION), new SchemaPayloadPlus(new SchemaPayload(index2StorageAdaptor.getRowSignature()), (long) index2StorageAdaptor.getNumRows())));
