    CountDownLatch latch = new CountDownLatch(2);
    CoordinatorSegmentMetadataCache schema = new CoordinatorSegmentMetadataCache(getQueryLifecycleFactory(walker), serverView, SEGMENT_CACHE_CONFIG_DEFAULT, new NoopEscalator(), new InternalQueryConfig(), new NoopServiceEmitter(), segmentSchemaCache, backFillQueue, sqlSegmentsMetadataManager, segmentsMetadataManagerConfigSupplier) {

