public void testCacheFinalizedSegmentSchema() {
    SegmentSchemaCache cache = new SegmentSchemaCache(new NoopServiceEmitter());
    Assert.assertFalse(cache.isInitialized());
    RowSignature rowSignature = RowSignature.builder().add("cx", ColumnType.FLOAT).build();
    SchemaPayloadPlus expected = new SchemaPayloadPlus(new SchemaPayload(rowSignature), 20L);
    SegmentId id = SegmentId.dummy("ds");
    ImmutableMap.Builder<String, SchemaPayload> schemaPayloadBuilder = new ImmutableMap.Builder<>();
    schemaPayloadBuilder.put("fp1", new SchemaPayload(rowSignature));
    ImmutableMap.Builder<SegmentId, SegmentMetadata> segmentMetadataBuilder = new ImmutableMap.Builder<>();
    segmentMetadataBuilder.put(id, new SegmentMetadata(20L, "fp1"));
    cache.updateFinalizedSegmentSchema(new SegmentSchemaCache.FinalizedSegmentSchemaInfo(segmentMetadataBuilder.build(), schemaPayloadBuilder.build()));
    Assert.assertTrue(cache.isInitialized());
    Assert.assertTrue(cache.isSchemaCached(id));
    Optional<SchemaPayloadPlus> schema = cache.getSchemaForSegment(id);
    Assert.assertTrue(schema.isPresent());
    Assert.assertEquals(expected, schema.get());
}

@Test
public void testPersistSchemaAndUpdateSegmentsTable() {
    final Map<String, Pair<SchemaPayload, Integer>> segmentIdSchemaMap = new HashMap<>();
    Random random = new Random(5);
    Set<DataSegment> segments = new HashSet<>();
    List<SegmentSchemaManager.SegmentSchemaMetadataPlus> schemaMetadataPluses = new ArrayList<>();
    for (int i = 1; i < 9; i++) {
        final DataSegment segment = new DataSegment("foo", Intervals.of("2023-01-0" + i + "/2023-01-0" + (i + 1)), "2023-01-0" + i, ImmutableMap.of("path", "a-" + i), ImmutableList.of("dim1"), ImmutableList.of("m1"), new LinearShardSpec(0), 9, 100);
        segments.add(segment);
        int randomNum = random.nextInt();
        RowSignature rowSignature = RowSignature.builder().add("c" + randomNum, ColumnType.FLOAT).build();
        Map<String, AggregatorFactory> aggregatorFactoryMap = new HashMap<>();
        aggregatorFactoryMap.put("longFirst", new LongFirstAggregatorFactory("longFirst", "long-col", null));
        SchemaPayload schemaPayload = new SchemaPayload(rowSignature, aggregatorFactoryMap);
        SchemaPayloadPlus schemaMetadata = new SchemaPayloadPlus(schemaPayload, (long) randomNum);
        SegmentSchemaManager.SegmentSchemaMetadataPlus plus = new SegmentSchemaManager.SegmentSchemaMetadataPlus(segment.getId(), fingerprintGenerator.generateFingerprint(schemaPayload, segment.getDataSource(), CentralizedDatasourceSchemaConfig.SCHEMA_VERSION), schemaMetadata);
        schemaMetadataPluses.add(plus);
        segmentIdSchemaMap.put(segment.getId().toString(), Pair.of(schemaPayload, randomNum));
    }
    segmentSchemaTestUtils.insertUsedSegments(segments, Collections.emptyMap());
    segmentSchemaManager.persistSchemaAndUpdateSegmentsTable("foo", schemaMetadataPluses, CentralizedDatasourceSchemaConfig.SCHEMA_VERSION);
    segmentSchemaTestUtils.verifySegmentSchema(segmentIdSchemaMap);
    // associate a new segment with existing schema
    DataSegment segment = segments.stream().findAny().get();
    Pair<SchemaPayload, Integer> schemaPayloadIntegerPair = segmentIdSchemaMap.get(segment.getId().toString());
    final DataSegment newSegment = new DataSegment("foo", Intervals.of("2024-01-01/2024-01-02"), "2023-01-01", ImmutableMap.of("path", "a-1"), ImmutableList.of("dim1"), ImmutableList.of("m1"), new LinearShardSpec(0), 9, 100);
    SchemaPayloadPlus schemaMetadata = new SchemaPayloadPlus(schemaPayloadIntegerPair.lhs, 500L);
    SegmentSchemaManager.SegmentSchemaMetadataPlus plus = new SegmentSchemaManager.SegmentSchemaMetadataPlus(newSegment.getId(), fingerprintGenerator.generateFingerprint(schemaPayloadIntegerPair.lhs, newSegment.getDataSource(), CentralizedDatasourceSchemaConfig.SCHEMA_VERSION), schemaMetadata);
    segmentSchemaTestUtils.insertUsedSegments(Collections.singleton(newSegment), Collections.emptyMap());
    segmentSchemaManager.persistSchemaAndUpdateSegmentsTable("foo", Collections.singletonList(plus), CentralizedDatasourceSchemaConfig.SCHEMA_VERSION);
    segmentIdSchemaMap.clear();
    segmentIdSchemaMap.put(newSegment.getId().toString(), Pair.of(schemaPayloadIntegerPair.lhs, 500));
    segmentSchemaTestUtils.verifySegmentSchema(segmentIdSchemaMap);
}

@Test
public void testPersistAndUpdateSegmentsTable_unusedExistingSegment() {
    final Map<String, Pair<SchemaPayload, Integer>> segmentIdSchemaMap = new HashMap<>();
    Set<DataSegment> segments = new HashSet<>();
    List<SegmentSchemaManager.SegmentSchemaMetadataPlus> schemaMetadataPluses = new ArrayList<>();
    for (int i = 1; i < 9; i++) {
        final DataSegment segment = new DataSegment("foo", Intervals.of("2023-01-0" + i + "/2023-01-0" + (i + 1)), "2023-01-0" + i, ImmutableMap.of("path", "a-" + i), ImmutableList.of("dim1"), ImmutableList.of("m1"), new LinearShardSpec(0), 9, 100);
        segments.add(segment);
        RowSignature rowSignature = RowSignature.builder().add("c" + i, ColumnType.FLOAT).build();
        Map<String, AggregatorFactory> aggregatorFactoryMap = new HashMap<>();
        aggregatorFactoryMap.put("longFirst", new LongFirstAggregatorFactory("longFirst", "long-col", null));
