@Test
public void testSimpleIngestion() throws Exception {
    try (final ClosedSegmensSinksBatchAppenderatorTester tester = new ClosedSegmensSinksBatchAppenderatorTester(3, false)) {
        final Appenderator appenderator = tester.getAppenderator();
        // startJob
        Assert.assertNull(appenderator.startJob());
        // getDataSource
        Assert.assertEquals(ClosedSegmensSinksBatchAppenderatorTester.DATASOURCE, appenderator.getDataSource());
        // add #1
        Assert.assertEquals(1, appenderator.add(IDENTIFIERS.get(0), createInputRow("2000", "foo", 1), null).getNumRowsInSegment());
        // add #2
        Assert.assertEquals(1, appenderator.add(IDENTIFIERS.get(1), createInputRow("2000", "bar", 2), null).getNumRowsInSegment());
        // getSegments
        Assert.assertEquals(IDENTIFIERS.subList(0, 2), appenderator.getSegments().stream().sorted().collect(Collectors.toList()));
        // add #3, this hits max rows in memory:
        Assert.assertEquals(2, appenderator.add(IDENTIFIERS.get(1), createInputRow("2000", "sux", 1), null).getNumRowsInSegment());
        // since we just added three rows and the max rows in memory is three, all the segments (sinks etc.)
        // above should be cleared now
        Assert.assertEquals(Collections.emptyList(), ((BatchAppenderator) appenderator).getInMemorySegments().stream().sorted().collect(Collectors.toList()));
        // add #4, this will add one more temporary segment:
        Assert.assertEquals(1, appenderator.add(IDENTIFIERS.get(2), createInputRow("2001", "qux", 4), null).getNumRowsInSegment());
        // push all
        final SegmentsAndCommitMetadata segmentsAndCommitMetadata = appenderator.push(appenderator.getSegments(), null, false).get();
        Assert.assertEquals(IDENTIFIERS.subList(0, 3), Lists.transform(segmentsAndCommitMetadata.getSegments(), SegmentIdWithShardSpec::fromDataSegment).stream().sorted().collect(Collectors.toList()));
        Assert.assertEquals(tester.getPushedSegments().stream().sorted().collect(Collectors.toList()), segmentsAndCommitMetadata.getSegments().stream().sorted().collect(Collectors.toList()));
        appenderator.close();
        Assert.assertTrue(appenderator.getSegments().isEmpty());
    }
}

