/**
 * Test the case when a segment identifier contains non UTC timestamps in its interval. This can happen
 * when a custom segment granularity for an interval with a non UTC Chronlogy is created by
 * {@link org.apache.druid.java.util.common.granularity.PeriodGranularity#bucketStart(DateTime)}
 */
@Test
public void testPeriodGranularityNonUTCIngestion() throws Exception {
    try (final ClosedSegmensSinksBatchAppenderatorTester tester = new ClosedSegmensSinksBatchAppenderatorTester(1, false)) {
        final Appenderator appenderator = tester.getAppenderator();
        // startJob
        Assert.assertNull(appenderator.startJob());
        // getDataSource
        Assert.assertEquals(ClosedSegmensSinksBatchAppenderatorTester.DATASOURCE, appenderator.getDataSource());
        // Create a segment identifier with a non-utc interval
        SegmentIdWithShardSpec segmentIdWithNonUTCTime = createNonUTCSegmentId("2021-06-27T00:00:00.000+09:00/2021-06-28T00:00:00.000+09:00", "A", // should be in seg_0
        0);
        Assert.assertEquals(1, appenderator.add(segmentIdWithNonUTCTime, createInputRow("2021-06-27T00:01:11.080Z", "foo", 1), null).getNumRowsInSegment());
        // getSegments
        Assert.assertEquals(Collections.singletonList(segmentIdWithNonUTCTime), appenderator.getSegments().stream().sorted().collect(Collectors.toList()));
        // since we just added one row and the max rows in memory is one, all the segments (sinks etc)
        // above should be cleared now
        Assert.assertEquals(Collections.emptyList(), ((BatchAppenderator) appenderator).getInMemorySegments().stream().sorted().collect(Collectors.toList()));
        // push all
        final SegmentsAndCommitMetadata segmentsAndCommitMetadata = appenderator.push(appenderator.getSegments(), null, false).get();
        Assert.assertEquals(Collections.singletonList(segmentIdWithNonUTCTime), Lists.transform(segmentsAndCommitMetadata.getSegments(), SegmentIdWithShardSpec::fromDataSegment).stream().sorted().collect(Collectors.toList()));
        Assert.assertEquals(tester.getPushedSegments().stream().sorted().collect(Collectors.toList()), segmentsAndCommitMetadata.getSegments().stream().sorted().collect(Collectors.toList()));
        appenderator.close();
        Assert.assertTrue(appenderator.getSegments().isEmpty());
    }
}

@Test
public void testMaxBytesInMemoryWithSkipBytesInMemoryOverheadCheckConfig() throws Exception {
    try (final ClosedSegmensSinksBatchAppenderatorTester tester = new ClosedSegmensSinksBatchAppenderatorTester(100, 1024, null, true, new SimpleRowIngestionMeters(), true)) {
        final Appenderator appenderator = tester.getAppenderator();
        appenderator.startJob();
        appenderator.add(IDENTIFIERS.get(0), createInputRow("2000", "foo", 1), null);
        //expectedSizeInBytes =
        // 44(map overhead) + 28 (TimeAndDims overhead) + 56 (aggregator metrics) + 54 (dimsKeySize) =
        // 182 + 1 byte when null handling is enabled
        int nullHandlingOverhead = NullHandling.sqlCompatible() ? 1 : 0;
        Assert.assertEquals(182 + nullHandlingOverhead, ((BatchAppenderator) appenderator).getBytesInMemory(IDENTIFIERS.get(0)));
        appenderator.add(IDENTIFIERS.get(1), createInputRow("2000", "bar", 1), null);
        Assert.assertEquals(182 + nullHandlingOverhead, ((BatchAppenderator) appenderator).getBytesInMemory(IDENTIFIERS.get(1)));
        appenderator.close();
        Assert.assertEquals(0, ((BatchAppenderator) appenderator).getRowsInMemory());
    }
}

