@Test
public void testSimpleIngestion() throws Exception {
    try (final StreamAppenderatorTester tester = new StreamAppenderatorTester.Builder().maxRowsInMemory(2).basePersistDirectory(temporaryFolder.newFolder()).build()) {
        final Appenderator appenderator = tester.getAppenderator();
        boolean thrown;
        final ConcurrentMap<String, String> commitMetadata = new ConcurrentHashMap<>();
        final Supplier<Committer> committerSupplier = committerSupplierFromConcurrentMap(commitMetadata);
        // startJob
        Assert.assertEquals(null, appenderator.startJob());
        // getDataSource
        Assert.assertEquals(StreamAppenderatorTester.DATASOURCE, appenderator.getDataSource());
        // add
        commitMetadata.put("x", "1");
        Assert.assertEquals(1, appenderator.add(IDENTIFIERS.get(0), ir("2000", "foo", 1), committerSupplier).getNumRowsInSegment());
        commitMetadata.put("x", "2");
        Assert.assertEquals(2, appenderator.add(IDENTIFIERS.get(0), ir("2000", "bar", 2), committerSupplier).getNumRowsInSegment());
        commitMetadata.put("x", "3");
        Assert.assertEquals(1, appenderator.add(IDENTIFIERS.get(1), ir("2000", "qux", 4), committerSupplier).getNumRowsInSegment());
        // getSegments
        Assert.assertEquals(IDENTIFIERS.subList(0, 2), sorted(appenderator.getSegments()));
        // getRowCount
        Assert.assertEquals(2, appenderator.getRowCount(IDENTIFIERS.get(0)));
        Assert.assertEquals(1, appenderator.getRowCount(IDENTIFIERS.get(1)));
        thrown = false;
        try {
            appenderator.getRowCount(IDENTIFIERS.get(2));
        } catch (IllegalStateException e) {
            thrown = true;
        }
        Assert.assertTrue(thrown);
        // push all
        final SegmentsAndCommitMetadata segmentsAndCommitMetadata = appenderator.push(appenderator.getSegments(), committerSupplier.get(), false).get();
        Assert.assertEquals(ImmutableMap.of("x", "3"), (Map<String, String>) segmentsAndCommitMetadata.getCommitMetadata());
        Assert.assertEquals(IDENTIFIERS.subList(0, 2), sorted(Lists.transform(segmentsAndCommitMetadata.getSegments(), new Function<DataSegment, SegmentIdWithShardSpec>() {

            @Override
            public SegmentIdWithShardSpec apply(DataSegment input) {
                return SegmentIdWithShardSpec.fromDataSegment(input);
            }
        })));
        Assert.assertEquals(sorted(tester.getPushedSegments()), sorted(segmentsAndCommitMetadata.getSegments()));
        // clear
        appenderator.clear();
        Assert.assertTrue(appenderator.getSegments().isEmpty());
    }
}

