public void testGetSinkSignature() throws IndexSizeExceededException {
    final DataSchema schema = new DataSchema("test", new TimestampSpec(null, null, null), new DimensionsSpec(Arrays.asList(new StringDimensionSchema("dim1"), new LongDimensionSchema("dimLong"))), new AggregatorFactory[] { new CountAggregatorFactory("rows") }, new UniformGranularitySpec(Granularities.HOUR, Granularities.MINUTE, null), null);
    final Interval interval = Intervals.of("2013-01-01/2013-01-02");
    final String version = DateTimes.nowUtc().toString();
    final Sink sink = new Sink(interval, schema, SHARD_SPEC, version, TuningConfig.DEFAULT_APPENDABLE_INDEX, MAX_ROWS_IN_MEMORY, TuningConfig.DEFAULT_APPENDABLE_INDEX.getDefaultMaxBytesInMemory(), true);
    sink.add(new MapBasedInputRow(DateTimes.of("2013-01-01"), ImmutableList.of("dim1", "dimLong"), ImmutableMap.of("dim1", "value1", "dimLong", "20")), false);
    Map<String, ColumnType> expectedColumnTypeMap = Maps.newLinkedHashMap();
    expectedColumnTypeMap.put("__time", ColumnType.LONG);
    expectedColumnTypeMap.put("dim1", ColumnType.STRING);
    expectedColumnTypeMap.put("dimLong", ColumnType.LONG);
    expectedColumnTypeMap.put("rows", ColumnType.LONG);
    RowSignature signature = sink.getSignature();
    Assert.assertEquals(toRowSignature(expectedColumnTypeMap), signature);
    sink.add(new MapBasedInputRow(DateTimes.of("2013-01-01"), ImmutableList.of("dim1", "dimLong", "newCol1"), ImmutableMap.of("dim1", "value2", "dimLong", "30", "newCol1", "value")), false);
    expectedColumnTypeMap.remove("rows");
    expectedColumnTypeMap.put("newCol1", ColumnType.STRING);
    expectedColumnTypeMap.put("rows", ColumnType.LONG);
    signature = sink.getSignature();
    Assert.assertEquals(toRowSignature(expectedColumnTypeMap), signature);
    sink.swap();
    sink.add(new MapBasedInputRow(DateTimes.of("2013-01-01"), ImmutableList.of("dim1", "dimLong", "newCol2"), ImmutableMap.of("dim1", "value3", "dimLong", "30", "newCol2", "value")), false);
    expectedColumnTypeMap.put("newCol2", ColumnType.STRING);
    signature = sink.getSignature();
    Assert.assertEquals(toRowSignature(expectedColumnTypeMap), signature);
    sink.add(new MapBasedInputRow(DateTimes.of("2013-01-01"), ImmutableList.of("dim1", "dimLong", "newCol3"), ImmutableMap.of("dim1", "value3", "dimLong", "30", "newCol3", "value")), false);
    expectedColumnTypeMap.put("newCol3", ColumnType.STRING);
    signature = sink.getSignature();
    Assert.assertEquals(toRowSignature(expectedColumnTypeMap), signature);
    sink.swap();
    sink.add(new MapBasedInputRow(DateTimes.of("2013-01-01"), ImmutableList.of("dim1", "dimLong", "newCol4"), ImmutableMap.of("dim1", "value3", "dimLong", "30", "newCol4", "value")), false);
    expectedColumnTypeMap.put("newCol4", ColumnType.STRING);
    signature = sink.getSignature();
    Assert.assertEquals(toRowSignature(expectedColumnTypeMap), signature);
}

