@Test
public void testScanOnScanWithStringExpression() {
    initWalker(ImmutableMap.of(QueryContexts.MAX_SUBQUERY_ROWS_KEY, "1", QueryContexts.MAX_SUBQUERY_BYTES_KEY, "1000"), scheduler);
    final Query<?> subquery = Druids.newScanQueryBuilder().dataSource(FOO).intervals(new MultipleIntervalSegmentSpec(Intervals.ONLY_ETERNITY)).columns("s").resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_COMPACTED_LIST).build().withId(DUMMY_QUERY_ID);
    final Query<?> query = Druids.newScanQueryBuilder().dataSource(new QueryDataSource(subquery)).intervals(new MultipleIntervalSegmentSpec(Intervals.ONLY_ETERNITY)).virtualColumns(new ExpressionVirtualColumn("v", "case_searched(s == 'x',2,3)", ColumnType.LONG, ExprMacroTable.nil())).columns("v").resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_COMPACTED_LIST).build().withId(DUMMY_QUERY_ID);
    testQuery(query, ImmutableList.of(ExpectedQuery.cluster(subquery.withId(DUMMY_QUERY_ID).withSubQueryId("1.1")), ExpectedQuery.local(query.withDataSource(InlineDataSource.fromIterable(ImmutableList.of(new Object[] { "x" }, new Object[] { "x" }, new Object[] { "y" }, new Object[] { "z" }), RowSignature.builder().add("s", null).build())))), ImmutableList.of(new Object[] { 2L }, new Object[] { 2L }, new Object[] { 3L }, new Object[] { 3L }));
    Assert.assertEquals(2, scheduler.getTotalRun().get());
    Assert.assertEquals(1, scheduler.getTotalPrioritizedAndLaned().get());
    Assert.assertEquals(2, scheduler.getTotalAcquired().get());
    Assert.assertEquals(2, scheduler.getTotalReleased().get());
}

