    SegmentSchemas.SegmentSchema absoluteSchema2 = new SegmentSchemas.SegmentSchema(dataSource, segmentId, false, 40, ImmutableList.of("dim1", "dim2", "dim3"), ImmutableList.of(), ImmutableMap.of("dim1", ColumnType.UNKNOWN_COMPLEX, "dim2", ColumnType.STRING, "dim3", ColumnType.STRING));
    SegmentSchemas.SegmentSchema deltaSchema = new SegmentSchemas.SegmentSchema(dataSource, segmentId, true, 40, ImmutableList.of("dim3"), ImmutableList.of("dim1"), ImmutableMap.of("dim1", ColumnType.UNKNOWN_COMPLEX, "dim3", ColumnType.STRING));
