@Test
public void testCoordinatorConfigFailsWhenCleanupPeriodIsInvalid() {
    // Validation fails when cleanup period is less than metadata store management period
    final MetadataCleanupConfig cleanupConfig = new MetadataCleanupConfig(true, Duration.standardMinutes(30), null);
    final CoordinatorPeriodConfig periodConfig = new CoordinatorPeriodConfig(Duration.standardHours(1), null);
    verifyCoordinatorConfigFailsWith(createKillConfig().audit(cleanupConfig).build(), periodConfig, "'druid.coordinator.kill.audit.period'[PT1800S] must be greater than" + " 'druid.coordinator.period.metadataStoreManagementPeriod'[PT3600S]");
