@Parameters({ "historical", "broker" })
public void testRun(String serverType) {
    segmentsMetadataManager.addSegment(segmentV0);
    segmentsMetadataManager.addSegment(segmentV1);
    segmentsMetadataManager.addSegment(segmentV2);
    final ImmutableDruidServer druidServer = new DruidServer("", "", "", 0L, ServerType.fromString(serverType), "", 0).addDataSegment(segmentV1).addDataSegment(segmentV2).toImmutableDruidServer();
    DruidCluster druidCluster = DruidCluster.builder().add(new ServerHolder(druidServer, new TestLoadQueuePeon())).build();
    DruidCoordinatorRuntimeParams params = DruidCoordinatorRuntimeParams.newBuilder(DateTimes.nowUtc()).withDataSourcesSnapshot(segmentsMetadataManager.getSnapshotOfDataSourcesWithAllUsedSegments()).withDruidCluster(druidCluster).withDynamicConfigs(CoordinatorDynamicConfig.builder().withMarkSegmentAsUnusedDelayMillis(0).build()).withBalancerStrategy(new RandomBalancerStrategy()).withSegmentAssignerUsing(new SegmentLoadQueueManager(null, null)).build();
    SegmentTimeline timeline = segmentsMetadataManager.getSnapshotOfDataSourcesWithAllUsedSegments().getUsedSegmentsTimelinesPerDataSource().get("test");
    // Verify that the segments V0 and V1 are overshadowed
    Assert.assertTrue(timeline.isOvershadowed(segmentV0));
    Assert.assertTrue(timeline.isOvershadowed(segmentV1));
    // Run the duty and verify that the overshadowed segments are marked unused
    params = new MarkOvershadowedSegmentsAsUnused(segmentsMetadataManager::markSegmentsAsUnused).run(params);
    Set<DataSegment> updatedUsedSegments = Sets.newHashSet(segmentsMetadataManager.iterateAllUsedSegments());
    Assert.assertEquals(1, updatedUsedSegments.size());
    Assert.assertTrue(updatedUsedSegments.contains(segmentV2));
    CoordinatorRunStats runStats = params.getCoordinatorStats();
    Assert.assertEquals(2L, runStats.get(Stats.Segments.OVERSHADOWED, RowKey.of(Dimension.DATASOURCE, "test")));
}

