@Test
public void testReasonForBroadcastFailure() {
    final ServerHolder eligibleServer = create10gbHistorical(TIER_1);
    final ServerHolder serverWithNoDiskSpace = new ServerHolder(new DruidServer("server1", "server1", null, 0L, ServerType.HISTORICAL, TIER_1, 0).toImmutableDruidServer(), new TestLoadQueuePeon());
    // Create a server with full load queue
    final int maxSegmentsInLoadQueue = 5;
    final ServerHolder serverWithFullQueue = new ServerHolder(create10gbServer(ServerType.HISTORICAL, TIER_1).toImmutableDruidServer(), new TestLoadQueuePeon(), false, maxSegmentsInLoadQueue, 100);
    List<DataSegment> segmentsInQueue = CreateDataSegments.ofDatasource("koala").forIntervals(maxSegmentsInLoadQueue, Granularities.MONTH).withNumPartitions(1).eachOfSizeInMb(10);
    segmentsInQueue.forEach(s -> serverWithFullQueue.startOperation(SegmentAction.LOAD, s));
    Assert.assertTrue(serverWithFullQueue.isLoadQueueFull());
    DruidCluster cluster = DruidCluster.builder().add(eligibleServer).add(serverWithNoDiskSpace).add(serverWithFullQueue).build();
    DruidCoordinatorRuntimeParams params = makeParamsWithUsedSegments(cluster, wikiSegment);
    ForeverBroadcastDistributionRule rule = new ForeverBroadcastDistributionRule();
    final CoordinatorRunStats stats = runRuleOnSegment(rule, wikiSegment, params);
    // Verify that the segment is broadcast only to the eligible server
    Assert.assertEquals(1L, stats.getSegmentStat(Stats.Segments.ASSIGNED, TIER_1, DS_WIKI));
    RowKey metricKey = RowKey.with(Dimension.DATASOURCE, DS_WIKI).with(Dimension.TIER, TIER_1).and(Dimension.DESCRIPTION, "Not enough disk space");
    Assert.assertEquals(1L, stats.get(Stats.Segments.ASSIGN_SKIPPED, metricKey));
    metricKey = RowKey.with(Dimension.DATASOURCE, DS_WIKI).with(Dimension.TIER, TIER_1).and(Dimension.DESCRIPTION, "Load queue is full");
    Assert.assertEquals(1L, stats.get(Stats.Segments.ASSIGN_SKIPPED, metricKey));
}

