@Test
public void testCreateLookupLoadingSpecFromContext() {
    // Only required lookups are returned in the case of context having the lookup keys.
    Assert.assertEquals(LookupLoadingSpec.loadOnly(ImmutableSet.of("lookup1", "lookup2")), LookupLoadingSpec.createFromContext(ImmutableMap.of(LookupLoadingSpec.CTX_LOOKUPS_TO_LOAD, Arrays.asList("lookup1", "lookup2"), LookupLoadingSpec.CTX_LOOKUP_LOADING_MODE, LookupLoadingSpec.Mode.ONLY_REQUIRED), LookupLoadingSpec.ALL));
    // No lookups are returned in the case of context having mode=NONE, irrespective of the default spec.
    Assert.assertEquals(LookupLoadingSpec.NONE, LookupLoadingSpec.createFromContext(ImmutableMap.of(LookupLoadingSpec.CTX_LOOKUP_LOADING_MODE, LookupLoadingSpec.Mode.NONE), LookupLoadingSpec.ALL));
    // All lookups are returned in the case of context having mode=ALL, irrespective of the default spec.
    Assert.assertEquals(LookupLoadingSpec.ALL, LookupLoadingSpec.createFromContext(ImmutableMap.of(LookupLoadingSpec.CTX_LOOKUP_LOADING_MODE, LookupLoadingSpec.Mode.ALL), LookupLoadingSpec.NONE));
}

