@Test
public void testAuthorizeQueryContext_authorized() {
    EasyMock.expect(queryConfig.getContext()).andReturn(ImmutableMap.of()).anyTimes();
    EasyMock.expect(authenticationResult.getIdentity()).andReturn(IDENTITY).anyTimes();
    EasyMock.expect(authenticationResult.getAuthorizerName()).andReturn(AUTHORIZER).anyTimes();
    EasyMock.expect(authorizer.authorize(authenticationResult, new Resource(DATASOURCE, ResourceType.DATASOURCE), Action.READ)).andReturn(Access.OK).times(2);
    EasyMock.expect(authorizer.authorize(authenticationResult, new Resource("foo", ResourceType.QUERY_CONTEXT), Action.WRITE)).andReturn(Access.OK).times(2);
    EasyMock.expect(authorizer.authorize(authenticationResult, new Resource("baz", ResourceType.QUERY_CONTEXT), Action.WRITE)).andReturn(Access.OK).times(2);
    EasyMock.expect(toolChestWarehouse.getToolChest(EasyMock.anyObject())).andReturn(toolChest).times(2);
    replayAll();
    final Map<String, Object> userContext = ImmutableMap.of("foo", "bar", "baz", "qux");
    final TimeseriesQuery query = Druids.newTimeseriesQueryBuilder().dataSource(DATASOURCE).intervals(ImmutableList.of(Intervals.ETERNITY)).aggregators(new CountAggregatorFactory("chocula")).context(userContext).build();
    AuthConfig authConfig = AuthConfig.newBuilder().setAuthorizeQueryContextParams(true).build();
    QueryLifecycle lifecycle = createLifecycle(authConfig);
    lifecycle.initialize(query);
    final Map<String, Object> revisedContext = new HashMap<>(lifecycle.getQuery().getContext());
    Assert.assertTrue(lifecycle.getQuery().getContext().containsKey("queryId"));
    revisedContext.remove("queryId");
    Assert.assertEquals(userContext, revisedContext);
    Assert.assertTrue(lifecycle.authorize(mockRequest()).isAllowed());
    lifecycle = createLifecycle(authConfig);
    lifecycle.initialize(query);
    Assert.assertTrue(lifecycle.authorize(authenticationResult).isAllowed());
}

