@Test
public void testDistribution() throws IOException {
    String[] uuids = IOUtils.toString(Objects.requireNonNull(this.getClass().getClassLoader().getResourceAsStream("random_uuid_100")), StandardCharsets.UTF_8).split("\n");
    RendezvousHasher hasher = new RendezvousHasher();
    Set<String> nodes = new HashSet<>();
    for (int i = 0; i < 5; i++) {
        nodes.add("localhost:" + i);
    }
    Map<String, Integer> brokerToConnectionCount = new HashMap<>();
    for (String uuid : uuids) {
        brokerToConnectionCount.merge(hasher.chooseNode(nodes, uuid.getBytes(StandardCharsets.UTF_8)), 1, Integer::sum);
    }
    Map<String, Integer> expectedDistribution = ImmutableMap.<String, Integer>builder().put("localhost:0", 14).put("localhost:1", 22).put("localhost:2", 24).put("localhost:3", 25).put("localhost:4", 15).build();
    Assert.assertEquals(expectedDistribution, brokerToConnectionCount);
}

