public void testConcurrentQueries() {
    final List<ListenableFuture<Integer>> futures = new ArrayList<>();
    final ListeningExecutorService exec = MoreExecutors.listeningDecorator(Execs.multiThreaded(AVATICA_CONFIG.getMaxStatementsPerConnection(), "DruidAvaticaHandlerTest-%d"));
    for (int i = 0; i < 2000; i++) {
        final String query = StringUtils.format("SELECT COUNT(*) + %s AS ci FROM foo", i);
        futures.add(exec.submit(() -> {
            try (final Statement statement = client.createStatement();
                final ResultSet resultSet = statement.executeQuery(query)) {
                final List<Map<String, Object>> rows = getRows(resultSet);
                return ((Number) Iterables.getOnlyElement(rows).get("ci")).intValue();
            } catch (SQLException e) {
                throw new RuntimeException(e);
            }
        }));
    }
    final List<Integer> integers;
    try {
        integers = Futures.allAsList(futures).get();
    } catch (InterruptedException e) {
        throw new RE(e);
    } catch (ExecutionException e) {
        throw new RE(e);
    }
    for (int i = 0; i < 2000; i++) {
        Assert.assertEquals(i + 6, (int) integers.get(i));
    }
    exec.shutdown();
}

