@Test
public void testEscapingForGetColumns() throws SQLException {
    final DatabaseMetaData metaData = client.getMetaData();
    ImmutableList<Map<String, Object>> someDatasourceColumns = ImmutableList.of(row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "__time")), row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "dim1")), row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "dim2")), row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "dim3")), row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "cnt")), row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "m1")), row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "m2")), row(Pair.of("TABLE_SCHEM", "druid"), Pair.of("TABLE_NAME", CalciteTests.SOME_DATASOURCE), Pair.of("COLUMN_NAME", "unique_dim1")));
    // If the escape clause wasn't correctly set, rows for potentially none or more than
    // one datasource (some_datasource and somexdatasource) would have been returned
    Assert.assertEquals(someDatasourceColumns, getRows(metaData.getColumns(null, "dr_id", CalciteTests.SOME_DATSOURCE_ESCAPED, null), ImmutableSet.of("TABLE_NAME", "TABLE_SCHEM", "COLUMN_NAME")));
