    // which will still always be stringified to ultimately adhere to the varchar type
    // as array support increases in the engine this will likely change since using explict array functions should
    // probably kick it into an array
    List<Object[]> expectedResults;
    if (useDefault) {
        expectedResults = ImmutableList.of(new Object[] { "", "a", "[\"a\",\"b\"]", Arrays.asList("a", "b", "c"), Arrays.asList(1L, 2L, 3L), Arrays.asList(1.9, 2.2, 4.3), Arrays.asList("a", "b", "foo"), Arrays.asList("foo", "a"), Arrays.asList(1L, 2L, 7L), Arrays.asList(0L, 1L, 2L), Arrays.asList(1.2, 2.2, 1.0), Arrays.asList(0.0, 1.1, 2.2), Arrays.asList("a", "a", "b"), Arrays.asList(7L, 0L), Arrays.asList(1.0, 0.0) });
    } else {
        expectedResults = ImmutableList.of(new Object[] { "", "a", "[\"a\",\"b\"]", Arrays.asList("a", "b", "c"), Arrays.asList(1L, 2L, 3L), Arrays.asList(1.9, 2.2, 4.3), Arrays.asList("a", "b", "foo"), Arrays.asList("foo", "a"), Arrays.asList(1L, 2L, 7L), Arrays.asList(null, 1L, 2L), Arrays.asList(1.2, 2.2, 1.0), Arrays.asList(null, 1.1, 2.2), Arrays.asList("a", "a", "b"), Arrays.asList(7L, null), Arrays.asList(1.0, null) });
