@Test
public void testArrayScalarInFilter_MVD() {
    // In the fifth row, dim3 is an empty list. The Scan query in MSQ reads this with makeDimensionSelector, whereas
    // the Scan query in native reads this makeColumnValueSelector. Behavior of those selectors is inconsistent.
    // The DimensionSelector returns an empty list; the ColumnValueSelector returns a list containing a single null.
    final String expectedValueForEmptyMvd = queryFramework().engine().name().equals("msq-task") ? NullHandling.defaultStringValue() : "not abd";
    testBuilder().sql("SELECT dim3, (CASE WHEN scalar_in_array(dim3, Array['a', 'b', 'd']) THEN 'abd' ELSE 'not abd' END) " + "FROM druid.numfoo").expectedQueries(ImmutableList.of(newScanQueryBuilder().dataSource(CalciteTests.DATASOURCE3).intervals(querySegmentSpec(Filtration.eternity())).virtualColumns(expressionVirtualColumn("v0", "case_searched(scalar_in_array(\"dim3\",array('a','b','d')),'abd','not abd')", ColumnType.STRING)).columns("dim3", "v0").resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_COMPACTED_LIST).context(QUERY_CONTEXT_DEFAULT).build())).expectedResults(ImmutableList.of(new Object[] { "[\"a\",\"b\"]", "[\"abd\",\"abd\"]" }, new Object[] { "[\"b\",\"c\"]", "[\"abd\",\"not abd\"]" }, new Object[] { "d", "abd" }, new Object[] { "", "not abd" }, new Object[] { NullHandling.defaultStringValue(), expectedValueForEmptyMvd }, new Object[] { NullHandling.defaultStringValue(), "not abd" })).run();
}

