@Test
public void testFilterMultipleIsDistinctFrom() {
    cannotVectorize();
    // One optimize call is needed for each "IS DISTINCT FROM", because "x IS DISTINCT FROM y" is sugar for
    // "(x = y) IS NOT TRUE", and ReverseLookupRule doesn't peek into the "IS NOT TRUE" calls nested beneatth
    // the "AND".
    final ImmutableMap<String, Object> queryContext = ImmutableMap.<String, Object>builder().putAll(QUERY_CONTEXT_DEFAULT).put(PlannerContext.CTX_SQL_REVERSE_LOOKUP, true).put(ReverseLookupRule.CTX_MAX_OPTIMIZE_COUNT, 3).build();
    testQuery(buildFilterTestSql("LOOKUP(dim1, 'lookyloo') IS DISTINCT FROM 'xabc' AND " + "LOOKUP(dim1, 'lookyloo') IS DISTINCT FROM 'x6' AND " + "LOOKUP(dim1, 'lookyloo') IS DISTINCT FROM 'nonexistent'"), queryContext, buildFilterTestExpectedQuery(NullHandling.sqlCompatible() ? and(not(istrue(equality("dim1", "abc", ColumnType.STRING))), not(istrue(equality("dim1", "6", ColumnType.STRING)))) : and(not(equality("dim1", "abc", ColumnType.STRING)), not(equality("dim1", "6", ColumnType.STRING)))), ImmutableList.of(new Object[] { NULL_STRING, 5L }));
}

