@Test
public void testMultiValueListFilterComposedNested() {
    // Cannot vectorize due to usage of expressions.
    cannotVectorize();
    testQuery("SELECT COALESCE(MV_FILTER_ONLY(dim3, ARRAY['b']), 'no b'), SUM(cnt) FROM druid.numfoo GROUP BY 1 ORDER BY 2 DESC", ImmutableList.of(GroupByQuery.builder().setDataSource(CalciteTests.DATASOURCE3).setInterval(querySegmentSpec(Filtration.eternity())).setGranularity(Granularities.ALL).setVirtualColumns(expressionVirtualColumn("v0", "nvl(\"v1\",'no b')", ColumnType.STRING), new ListFilteredVirtualColumn("v1", DefaultDimensionSpec.of("dim3"), ImmutableSet.of("b"), true)).setDimensions(dimensions(new DefaultDimensionSpec("v0", "_d0", ColumnType.STRING))).setAggregatorSpecs(aggregators(new LongSumAggregatorFactory("a0", "cnt"))).setLimitSpec(new DefaultLimitSpec(ImmutableList.of(new OrderByColumnSpec("a0", OrderByColumnSpec.Direction.DESCENDING, StringComparators.NUMERIC)), Integer.MAX_VALUE)).setContext(QUERY_CONTEXT_DEFAULT).build()), // this behavior is strange - you might be expecting instead of default values it should actually be 'no b', but
    // instead we end up with something else
    //
    // it happens when using 'notnull' on the mv-filtered virtual column because deferred expression selector
    // returns a 0 sized row, which is treated as a missing value by the grouping, and so the expression which would
    // evaluate and return 'no b' is never evaluated. If we were not using the deferred selector, the results would
    // be 'no b' because IndexedInts representing [], [null], and null are homogenized into [null] to handle
    // variation between segments.
    //
    // if the 'notnull' was instead using the array filtering fallback expression
    // case_searched(notnull(filter((x) -> array_contains(array('b'), x), \"dim3\")),\"v1\",'no b')
    // where it doesn't use the deferred selector because it is no longer a single input expression, it would still
    // evaluate to null because the filter expression never returns null, only an empty array, which is not null,
    // so it evaluates 'v1' which of course is null because it is an empty row
    useDefault ? ImmutableList.of(new Object[] { "", 4L }, new Object[] { "b", 2L }) : ImmutableList.of(new Object[] { null, 4L }, new Object[] { "b", 2L }));
}

