@Test
public void testGroupByRootSingleTypeArrayLongNullsAsMvd() {
    cannotVectorize();
    testBuilder().sql("SELECT " + "ARRAY_TO_MV(arrayLongNulls), " + "SUM(cnt) " + "FROM druid.arrays GROUP BY 1").queryContext(QUERY_CONTEXT_NO_STRINGIFY_ARRAY).expectedQueries(ImmutableList.of(GroupByQuery.builder().setDataSource(TableDataSource.create(DATA_SOURCE_ARRAYS)).setInterval(querySegmentSpec(Filtration.eternity())).setGranularity(Granularities.ALL).setDimensions(dimensions(new DefaultDimensionSpec("v0", "d0", ColumnType.STRING))).setVirtualColumns(expressionVirtualColumn("v0", "array_to_mv(\"arrayLongNulls\")", ColumnType.STRING)).setAggregatorSpecs(aggregators(new LongSumAggregatorFactory("a0", "cnt"))).setContext(QUERY_CONTEXT_NO_STRINGIFY_ARRAY).build())).expectedResults(ImmutableList.of(// implicit mvd unnest treats null and empty as [null] so we get extra null matches than unnest
    // directly on the ARRAY
    new Object[] { NullHandling.defaultStringValue(), 9L }, new Object[] { "1", 5L }, new Object[] { "2", 6L }, new Object[] { "3", 6L }, new Object[] { "9", 2L })).expectedSignature(RowSignature.builder().add("EXPR$0", ColumnType.STRING).add("EXPR$1", ColumnType.LONG).build()).run();
}

