@Test
public void testInFilterWith23Elements() {
    // Regression test for https://github.com/apache/druid/issues/4203.
    final List<String> elements = new ArrayList<>();
    elements.add("abc");
    elements.add("def");
    elements.add("ghi");
    for (int i = 0; i < 20; i++) {
        elements.add("dummy" + i);
    }
    final String elementsString = Joiner.on(",").join(elements.stream().map(s -> "'" + s + "'").iterator());
    testQuery("SELECT dim1, COUNT(*) FROM druid.foo\n" + "WHERE dim1 IN (" + elementsString + ") OR dim1 = 'xyz' OR dim1 IS NULL\n" + "GROUP BY dim1", ImmutableList.of(GroupByQuery.builder().setDataSource(CalciteTests.DATASOURCE1).setInterval(querySegmentSpec(Filtration.eternity())).setGranularity(Granularities.ALL).setDimensions(dimensions(new DefaultDimensionSpec("dim1", "d0"))).setDimFilter(NullHandling.sqlCompatible() ? or(in("dim1", ImmutableSet.<String>builder().addAll(elements).add("xyz").build()), isNull("dim1")) : in("dim1", Lists.newArrayList(Iterables.concat(Collections.singleton(null), elements, Collections.singleton("xyz"))))).setAggregatorSpecs(aggregators(new CountAggregatorFactory("a0"))).setContext(QUERY_CONTEXT_DEFAULT).build()), NullHandling.sqlCompatible() ? ImmutableList.of(new Object[] { "abc", 1L }, new Object[] { "def", 1L }) : ImmutableList.of(new Object[] { "", 1L }, new Object[] { "abc", 1L }, new Object[] { "def", 1L }));
}

