@Test
public void testUnplannableJoinQueriesInNonSQLCompatibleMode() {
    msqIncompatible();
    Assumptions.assumeFalse(NullHandling.sqlCompatible());
    assertQueryIsUnplannable(// JOIN condition with not-equals (<>).
    "SELECT foo.dim1, foo.dim2, l.k, l.v\n" + "FROM foo INNER JOIN lookup.lookyloo l ON foo.dim2 <> l.k", "SQL requires a join with 'NOT_EQUALS' condition that is not supported.");
    assertQueryIsUnplannable(// JOIN condition with a function of both sides.
    "SELECT foo.dim1, foo.dim2, l.k, l.v\n" + "FROM foo INNER JOIN lookup.lookyloo l ON CHARACTER_LENGTH(foo.dim2 || l.k) > 3\n", "SQL requires a join with 'GREATER_THAN' condition that is not supported.");
}

