    // NOTE: the first expression HUMAN_READABLE_BINARY_BYTE_FORMAT(45678) in SQL is calculated during SQL parse phase,
    // so the converted Druid native query is its result intead of the raw function call
    //
    virtualColumns(expressionVirtualColumn("v0", "'44.61 KiB'", ColumnType.STRING), expressionVirtualColumn("v1", "human_readable_binary_byte_format((\"m1\" * 12345))", ColumnType.STRING), expressionVirtualColumn("v2", "human_readable_binary_byte_format((\"m1\" * 12345),0)", ColumnType.STRING), expressionVirtualColumn("v3", "human_readable_decimal_byte_format((\"m1\" * 12345))", ColumnType.STRING), expressionVirtualColumn("v4", "human_readable_decimal_format((\"m1\" * 12345))", ColumnType.STRING), expressionVirtualColumn("v5", "human_readable_binary_byte_format(\"l1\")", ColumnType.STRING), expressionVirtualColumn("v6", "human_readable_decimal_byte_format(\"l1\")", ColumnType.STRING), expressionVirtualColumn("v7", "human_readable_decimal_format(\"l1\")", ColumnType.STRING)).columns("m1", "v0", "v1", "v2", "v3", "v4", "v5", "v6", "v7").filters(equality("dim1", "1", ColumnType.STRING)).resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_COMPACTED_LIST).limit(1).context(QUERY_CONTEXT_DEFAULT).build()), ImmutableList.of(new Object[] { (float) 4.0, // 45678 / 1024
    "44.61 KiB", // = m1(4.0) * 12345 / 1024
    "48.22 KiB", // = m1(4.0) * 12345 / 1024, precision = 0
    "48 KiB", // decimal byte format, m1(4.0) * 12345 / 1000,
    "49.38 KB", // decimal format, m1(4.0) * 12345 / 1000,
    "49.38 K", NullHandling.replaceWithDefault() ? "0 B" : null, NullHandling.replaceWithDefault() ? "0 B" : null, NullHandling.replaceWithDefault() ? "0" : null }));
