    //
    // See DruidQuery#canUseQueryGranularity for the relevant check.
    cannotVectorize();
    testQuery("SELECT TIME_FLOOR(__time, 'P1m'), max(m1) from " + "(VALUES (TIMESTAMP '2000-01-01', 1.0), (TIMESTAMP '2000-01-02', 2.0)) t (__time, m1)\n" + "GROUP BY 1\n" + "ORDER BY 1 DESC", ImmutableList.of(GroupByQuery.builder().setDataSource(InlineDataSource.fromIterable(ImmutableList.of(new Object[] { timestamp("2000-01-01"), 1.0 }, // Floor to month is applied while creating inline source, so this is
