    new DateTime("2000-01-01T00:00:00.123Z", timeZone).withZone(DateTimeZone.UTC).getMillis(), new DateTime("2000-01-01T00:00:00.000Z", timeZone).withZone(DateTimeZone.UTC).getMillis(), new DateTime("2000-01-01T00:00:00.100Z", timeZone).withZone(DateTimeZone.UTC).getMillis(), new DateTime("2000-01-01T00:00:00.120Z", timeZone).withZone(DateTimeZone.UTC).getMillis(), new DateTime("2000-01-01T00:00:00.123Z", timeZone).withZone(DateTimeZone.UTC).getMillis(), new DateTime("1999-12-31", timeZone).withZone(DateTimeZone.UTC).getMillis(), new DateTime("2000-01-01", timeZone).withZone(DateTimeZone.UTC).getMillis() }), RowSignature.builder().add("CURRENT_TIMESTAMP", ColumnType.LONG).add("EXPR$1", ColumnType.LONG).add("EXPR$2", ColumnType.LONG).add("EXPR$3", ColumnType.LONG).add("EXPR$4", ColumnType.LONG).add("CURRENT_DATE", ColumnType.LONG).add("EXPR$6", ColumnType.LONG).build())).intervals(querySegmentSpec(Filtration.eternity())).columns("CURRENT_DATE", "CURRENT_TIMESTAMP", "EXPR$1", "EXPR$2", "EXPR$3", "EXPR$4", "EXPR$6").resultFormat(ScanQuery.ResultFormat.RESULT_FORMAT_COMPACTED_LIST).context(context).build()), ImmutableList.of(new Object[] { timestamp("2000-01-01T00:00:00.123Z", LOS_ANGELES), timestamp("2000-01-01T00:00:00.000Z", LOS_ANGELES), timestamp("2000-01-01T00:00:00.100Z", LOS_ANGELES), timestamp("2000-01-01T00:00:00.120Z", LOS_ANGELES), timestamp("2000-01-01T00:00:00.123Z", LOS_ANGELES), day("1999-12-31"), day("2000-01-01") }));
