     */
    testHelper.testExpressionString(HumanReadableFormatOperatorConversion.BINARY_BYTE_FORMAT.calciteOperator(), ImmutableList.of(testHelper.makeLiteral(1000)), makeExpression("human_readable_binary_byte_format(1000)"), "1000 B");
