    testHelper.testExpressionString(HumanReadableFormatOperatorConversion.BINARY_BYTE_FORMAT.calciteOperator(), ImmutableList.of(testHelper.makeLiteral(Long.MIN_VALUE)), makeExpression("human_readable_binary_byte_format(-9223372036854775808)"), "-8.00 EiB");
    /*
     * test input with variable reference
     */
    testHelper.testExpressionString(HumanReadableFormatOperatorConversion.BINARY_BYTE_FORMAT.calciteOperator(), ImmutableList.of(testHelper.makeInputRef("b"), testHelper.makeInputRef("p")), makeExpression("human_readable_binary_byte_format(\"b\",\"p\")"), "25 B");
    /*
     * test different precision
     */
    testHelper.testExpressionString(HumanReadableFormatOperatorConversion.BINARY_BYTE_FORMAT.calciteOperator(), ImmutableList.of(testHelper.makeLiteral(45000), //precision 0
    testHelper.makeLiteral(0)), makeExpression("human_readable_binary_byte_format(45000,0)"), "44 KiB");
    testHelper.testExpressionString(HumanReadableFormatOperatorConversion.BINARY_BYTE_FORMAT.calciteOperator(), ImmutableList.of(testHelper.makeLiteral(45000), //precision 1
    testHelper.makeLiteral(1)), makeExpression("human_readable_binary_byte_format(45000,1)"), "43.9 KiB");
    testHelper.testExpressionString(HumanReadableFormatOperatorConversion.BINARY_BYTE_FORMAT.calciteOperator(), ImmutableList.of(testHelper.makeLiteral(45000), //precision 2
