    final JsonConfigProvider<BrokerSegmentMetadataCacheConfig> provider = JsonConfigProvider.of(CONFIG_BASE, BrokerSegmentMetadataCacheConfig.class);
    final Properties properties = new Properties();
    properties.setProperty(CONFIG_BASE + ".metadataColumnTypeMergePolicy", "latestInterval");
    properties.setProperty(CONFIG_BASE + ".metadataRefreshPeriod", "PT2M");
    properties.setProperty(CONFIG_BASE + ".awaitInitializationOnStart", "false");
