@SuppressWarnings("rawtypes")
public void testArrayResultFormatWithHeader() throws Exception {
    final String query = "SELECT *, CASE dim2 WHEN '' THEN dim2 END FROM foo LIMIT 2";
    final String nullStr = NullHandling.replaceWithDefault() ? "" : null;
    final String hllStr = "org.apache.druid.hll.VersionOneHyperLogLogCollector";
    List[] expectedQueryResults = new List[] { Arrays.asList("2000-01-01T00:00:00.000Z", "", "a", "[\"a\",\"b\"]", 1, 1.0, 1.0, hllStr, nullStr), Arrays.asList("2000-01-02T00:00:00.000Z", "10.1", nullStr, "[\"b\",\"c\"]", 1, 2.0, 2.0, hllStr, nullStr) };
    MockHttpServletResponse response = postForAsyncResponse(new SqlQuery(query, ResultFormat.ARRAY, true, true, true, null, null), req.mimic());
    Assert.assertEquals(200, response.getStatus());
    Assert.assertEquals("yes", response.getHeader("X-Druid-SQL-Header-Included"));
    Assert.assertEquals(ImmutableList.builder().add(EXPECTED_COLUMNS_FOR_RESULT_FORMAT_TESTS).add(EXPECTED_TYPES_FOR_RESULT_FORMAT_TESTS).add(EXPECTED_SQL_TYPES_FOR_RESULT_FORMAT_TESTS).addAll(Arrays.asList(expectedQueryResults)).build(), JSON_MAPPER.readValue(response.baos.toByteArray(), Object.class));
    MockHttpServletResponse responseNoSqlTypesHeader = postForAsyncResponse(new SqlQuery(query, ResultFormat.ARRAY, true, true, false, null, null), req.mimic());
    Assert.assertEquals(200, responseNoSqlTypesHeader.getStatus());
    Assert.assertEquals("yes", responseNoSqlTypesHeader.getHeader("X-Druid-SQL-Header-Included"));
    Assert.assertEquals(ImmutableList.builder().add(EXPECTED_COLUMNS_FOR_RESULT_FORMAT_TESTS).add(EXPECTED_TYPES_FOR_RESULT_FORMAT_TESTS).addAll(Arrays.asList(expectedQueryResults)).build(), JSON_MAPPER.readValue(responseNoSqlTypesHeader.baos.toByteArray(), Object.class));
    MockHttpServletResponse responseNoTypesHeader = postForAsyncResponse(new SqlQuery(query, ResultFormat.ARRAY, true, false, true, null, null), req.mimic());
    Assert.assertEquals(200, responseNoTypesHeader.getStatus());
    Assert.assertEquals("yes", responseNoTypesHeader.getHeader("X-Druid-SQL-Header-Included"));
    Assert.assertEquals(ImmutableList.builder().add(EXPECTED_COLUMNS_FOR_RESULT_FORMAT_TESTS).add(EXPECTED_SQL_TYPES_FOR_RESULT_FORMAT_TESTS).addAll(Arrays.asList(expectedQueryResults)).build(), JSON_MAPPER.readValue(responseNoTypesHeader.baos.toByteArray(), Object.class));
    MockHttpServletResponse responseNoTypes = postForAsyncResponse(new SqlQuery(query, ResultFormat.ARRAY, true, false, false, null, null), req.mimic());
    Assert.assertEquals(200, responseNoTypes.getStatus());
    Assert.assertEquals("yes", responseNoTypes.getHeader("X-Druid-SQL-Header-Included"));
    Assert.assertEquals(ImmutableList.builder().add(EXPECTED_COLUMNS_FOR_RESULT_FORMAT_TESTS).addAll(Arrays.asList(expectedQueryResults)).build(), JSON_MAPPER.readValue(responseNoTypes.baos.toByteArray(), Object.class));
    MockHttpServletResponse responseNoHeader = postForAsyncResponse(new SqlQuery(query, ResultFormat.ARRAY, false, false, false, null, null), req.mimic());
    Assert.assertEquals(200, responseNoHeader.getStatus());
    Assert.assertNull(responseNoHeader.getHeader("X-Druid-SQL-Header-Included"));
    Assert.assertEquals(Arrays.asList(expectedQueryResults), JSON_MAPPER.readValue(responseNoHeader.baos.toByteArray(), Object.class));
}

