    final Pair<ErrorResponse, String> pair = doPostRaw(new SqlQuery(query, ResultFormat.ARRAYLINES, false, false, false, null, null));
    Assert.assertNull(pair.lhs);
    final String response = pair.rhs;
    final String nullStr = NullHandling.replaceWithDefault() ? "" : null;
    final List<String> lines = Splitter.on('\n').splitToList(response);
    Assert.assertEquals(4, lines.size());
    Assert.assertEquals(Arrays.asList("2000-01-01T00:00:00.000Z", "", "a", "[\"a\",\"b\"]", 1, 1.0, 1.0, "org.apache.druid.hll.VersionOneHyperLogLogCollector", nullStr), JSON_MAPPER.readValue(lines.get(0), List.class));
