@Test
public void testTransformUTC() {
    SqlRowTransformer transformer = new SqlRowTransformer(DateTimeZone.UTC, rowType);
    DateTime timestamp = DateTimes.of("2021-08-01T12:00:00");
    DateTime date = DateTimes.of("2021-01-01");
    Object[] expectedRow = new Object[] { ISODateTimeFormat.dateTime().print(timestamp), ISODateTimeFormat.dateTime().print(date), "string", null };
    Object[] row = new Object[] { Calcites.jodaToCalciteTimestamp(timestamp, DateTimeZone.UTC), Calcites.jodaToCalciteDate(date, DateTimeZone.UTC), expectedRow[2], null };
    Assert.assertArrayEquals(expectedRow, IntStream.range(0, expectedRow.length).mapToObj(i -> transformer.transform(row, i)).toArray());
}

