    SqlQueryPlus sqlReq = SqlQueryPlus.builder("select 1 + ?").context(ImmutableMap.of(QueryContexts.BY_SEGMENT_KEY, "true")).auth(CalciteTests.REGULAR_USER_AUTH_RESULT).build();
